INSERT INTO spells (id, name, school, subschool, descriptor, level, type, class_lists, casting_time, range, target, area, effect, duration, saving_throw, spell_resistance, description, material, arcane_focus, divine_focus, costly_components)
VALUES
  ('miracle', 'Miracle', 'evocation', NULL, NULL, 9, 'divine', 'cleric/oracle 9; Domain community 9, luck 9; Subdomain divine 9', '1 standard action', 'see text', NULL, 'see text', NULL, 'see text', 'see text', 'yes', 'You don’t so much cast a miracle as request one. You state what you would like to have happen and request that your deity (or the power you pray to for spells) intercede.', NULL, NULL, false, false),
  ('mirage', 'Mirage', 'illusion', 'figment', NULL, 3, 'divine', 'bard 3, druid 3, mesmerist 3, occultist 3, psychic 3, ranger 3', '10 minutes', 'long (400 ft. + 40 ft./level)', NULL, 'one 40-ft. cube/level (S)', NULL, '2 hours/level (D)', 'Will disbelief (see below)', 'yes', 'You create an image of a pool of water, a group of standing stones, a cove, an island, or another simple land formation over a stretch of flat land or water. The image is purely visual, and structures, equipment, and creatures within the area are not hidden or changed in appearance.', 'a pinch of sand and a drop of water', NULL, false, false),
  ('mirage_arcana', 'Mirage Arcana', 'illusion', 'glamer', NULL, 5, 'arcane', 'bard 5, sorcerer/wizard 5; Subdomain solitude 5; Elemental School wood 5', '1 standard action', NULL, NULL, 'one 20-ft. cube/level (S)', NULL, 'concentration +1 hour/ level (D)', NULL, NULL, 'This spell functions like hallucinatory terrain, except that it enables you to make any area appear to be something other than it is. The illusion includes audible, visual, tactile, and olfactory elements. Unlike hallucinatory terrain, the spell can alter the appearance of structures (or add them where none are present). Still, it can’t disguise, conceal, or add creatures (though creatures within the area might hide themselves within the illusion just as they can hide themselves within a real location).', NULL, NULL, false, false),
  ('mirror_hideaway', 'Mirror Hideaway', 'transmutation', NULL, NULL, 2, 'arcane', 'occultist 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'one mirror', NULL, NULL, '1 hour/level (D)', 'none', 'no', 'You transform a mirror into a portal to an extradimensional space. The space can hold as many as eight Medium creatures. Creatures that enter this space are hidden and beyond the reach of spells (including divinations), unless those spells work across planes. If the mirror is covered (such as by a cloth, or by being placed face down or against a wall), the portal becomes inactive. If the mirror is broken or moved more than 5 feet from where it was when you cast the spell, the spell ends; any creatures within the extradimensional space are expelled from it (see below) and become nauseated for 1d6 rounds.', 'a glass or metal marble and a twisted loop of parchment', NULL, false, false),
  ('mirror_image', 'Mirror Image', 'illusion', 'figment', NULL, 2, 'arcane', 'bard 2, bloodrager 2, magus 2, medium 2, mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 2; Subdomain deception 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 min./level', NULL, NULL, 'This spell creates a number of illusory doubles of you that inhabit your square. These doubles make it difficult for enemies to precisely locate and attack you.', NULL, NULL, false, false),
  ('mirror_mantis', 'Mirror Mantis', 'illusion', 'phantasm', 'mind-affecting', 1, 'divine', 'bard 1, cleric 1, mesmerist 1, occultist 1, psychic 1, sorcerer/wizard 1', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one living creature', NULL, NULL, '1 hour/level', 'Will negates', 'yes', 'Whenever the target of this spell looks into a mirror or other reflective surface where it can see its own visage clearly, it sees a crimson assassin (in full armor, face hidden by a mantis mask) looking back at it. The reflection is harmless and mimics the target’s motions perfectly; no one else can see this illusion. The first time the target sees the crimson assassin reflection, it must succeed at a Will save be or shaken and take a -2 penalty on saves against fear effects for as long as it can see the altered image and for 3 rounds thereafter. A new save must be attempted each time the creature views its reflection during the spell’s duration. Once a creature successfully saves, it becomes immune to being shaken by the caster’s mirror mantis spell for 24 hours, though it will still see the crimson assassin reflection until the spell ends.', NULL, 'a hand mirror stained with a dried drop of blood', false, false),
  ('mirror_polish', 'Mirror Polish', 'transmutation', NULL, NULL, 1, 'arcane', 'sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'one metal item of up to 1 sq. ft.', NULL, NULL, 'instantaneous', 'yes (object)', 'yes (object)', 'You polish a metal item until it is reflective enough to be used as a mirror. This does not prevent the item from later damage or corrosion that would ruin the mirrored surface. The spell can be cast only on a metal item with a fairly smooth and contiguous surface, such as a breastplate, a helm, a shield, or a sword, but not a mace, chainmail, or scale mail.', 'a soft cloth', NULL, false, false),
  ('mirror_sight', 'Mirror Sight', 'divination', 'scrying', NULL, 3, 'arcane', 'sorcerer/wizard 3', '10 minutes', 'see text', NULL, NULL, 'magical sensor', '1 minute/level', 'none', 'no', 'This spell lets you look into a mirror near you and see an image that is reflected in another specific mirror (chosen by you) or an individual reflected in any other mirror.', NULL, 'a mirror', false, false),
  ('mirror_strike', 'Mirror Strike', 'transmutation', NULL, NULL, 1, 'arcane', 'bloodrager 1, magus 1, psychic 1, sorcerer/wizard 1', '1 standard action', 'personal', 'you', NULL, NULL, 'see text', NULL, NULL, 'You briefly alter the flow of time to split a melee attack into two attacks. Before the end of your next turn, when you make your next melee attack roll, compare the result to the AC of two opponents within your reach. If the selected opponents are flanking you, you gain a +2 bonus on your attack roll (and confirmation attack roll, see below). If you hit both enemies, you can deal half damage to each. Hitting only one opponent allows you to deal that opponent normal damage for your attack. On a critical threat, you can make only one attack roll to confirm the critical hit against both opponents. If you confirm against both, you deal half your critical hit damage to each. Your hit is a normal hit rather than a critical if you confirm against only one opponent. If you fail to use the effect before the end of your next turn, the spell ends.', 'a shard of mirror', NULL, false, false),
  ('mirror_transport', 'Mirror Transport', 'transmutation', NULL, NULL, 4, 'arcane', 'sorcerer/wizard 4, witch 4', '1 standard action', 'touch', 'one mirror', NULL, NULL, '1 hour/level (D)', 'yes (object)', 'yes (object)', 'This spell functions as mirror hideaway, except any creature that enters the target mirror can spend a swift action to exit through another mirror within 500 feet as if using dimension door; this is a one-way transport. The creature can exit through a mirror only if it could fit through an opening the same size as the mirror. Each transport through the target mirror reduces the spell’s duration by 1 hour.', 'a glass or metal marble and a twisted loop of parchment', NULL, false, false),
  ('mischievous_shadow', 'Mischievous Shadow', 'necromancy', 'haunted', 'emotion, fear, mind-affecting', 3, 'divine', 'bard 4, magus 4, medium 3, shaman 4, sorcerer/wizard 4, spiritualist 4, summoner 4, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, 'one 5-ft. cube/level (S)', NULL, '1 day/level (D)', 'Will negates', 'yes', 'You direct spirits into the shadows of creatures. The shadows of creatures that fail their Will saving throws appear slightly different for the duration of the spell, bearing small horns, unusually long and slender arms, or other small discrepancies.', 'a black candle', NULL, false, false),
  ('misdirection', 'Misdirection', 'illusion', 'glamer', NULL, 2, 'arcane', 'bard 2, medium 2, mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 2, spiritualist 2, summoner/unchained summoner 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature or object, up to a 10-ft. cube in size', NULL, NULL, '1 hour/level', 'none or Will negates; see text', 'no', 'By means of this spell, you misdirect the information from divination spells that reveal auras (detect evil, detect magic, discern lies, and the like). On casting the spell, you choose another object within range. For the duration of the spell, the subject of misdirection is detected as if it were the other object. Neither the subject nor the other object gets a saving throw against this effect. Detection spells provide information based on the second object rather than on the actual target of the detection unless the caster of the detection succeeds on a Will save. For instance, you could make yourself detect as a tree if one were within range at casting: not evil, not lying, not magical, neutral in alignment, and so forth. This spell does not affect other types of divination magic (augury, detect thoughts, clairaudience/clairvoyance, and the like).', NULL, NULL, false, false),
  ('miserable_pity', 'Miserable Pity', 'abjuration', NULL, 'emotion, mind-affecting', 2, 'arcane', 'bard 2, mesmerist 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level and 1 minute; see text', 'Will negates (see text)', 'yes', 'This spell functions as sanctuary, except creatures attempting to attack the target who fail their saves also feel a strong sense of pity toward the target, as if it were weak, pathetic, and not a threat. If the target breaks the spell by attacking, any creature that failed its save against the spell gains a +2 morale bonus on attack rolls against the target for 1 minute.', NULL, NULL, false, false),
  ('mislead', 'Mislead', 'illusion', 'figment, glamer', NULL, 5, 'arcane', 'alchemist 6, bard 5, magus 6, sorcerer/wizard 6; Domain luck 6, trickery 6; Bloodline destined 6, fey 6; Mystery whimsy 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'you/one illusory double', '1 round/level (D) and concentration + 3 rounds; see text', 'none or Will disbelief (if interacted with); see text', 'no', 'You become invisible (as greater invisibility, a glamer), and at the same time, an illusory double of you (as major image, a figment) appears. You are then free to go elsewhere while your double moves away. The double appears within range but thereafter moves as you direct it (which requires concentration beginning on the first round after the casting). You can make the figment appear superimposed perfectly over your own body so that observers don’t notice an image appearing and you turning invisible. You and the figment can then move in different directions. The double moves at your speed and can talk and gesture as if it were real, but it cannot attack or cast spells, though it can pretend to do so.', NULL, NULL, false, false),
  ('mnemonic_enhancer', 'Mnemonic Enhancer', 'transmutation', NULL, NULL, 4, 'arcane', 'wizard 4', '10 minutes', 'personal', 'you', NULL, NULL, 'instantaneous', NULL, NULL, 'Casting this spell allows you to prepare additional spells or retain spells recently cast. Pick one of these two versions when the spell is cast.', 'a piece of string, and ink consisting of squid secretion mixed with black dragon’s blood', 'an ivory plaque worth 50 gp', false, true),
  ('mnemonic_siphon', 'Mnemonic Siphon', 'divination', NULL, NULL, 3, 'arcane', 'arcanist 4, magus 3, occultist 3, sorcerer 4, witch 4, wizard 4', '10 minutes', 'touch', 'object touched', NULL, NULL, '1 day/level or until discharged (D)', 'none', 'no', 'You inscribe a rune on the target object. The rune remains dormant until the object finds its way into the hands of a spellcaster, at which point the rune steals one of that creature’s spells and passes the knowledge back to you. The stolen spell is selected randomly. An object inscribed with this rune is affected as though by the spell magic aura. Additionally, if a creature in possession of the object casts a spell that appears on your spell list, there is a 10% chance that the mnemonic siphon absorbs that spell, causing it to fail as though it had been successfully countered. Whenever the mnemonic siphon absorbs a spell in this fashion, it causes the knowledge of the absorbed spell to appear directly in your mind. You can use this knowledge to prepare the spell if you have an unused spell slot capable of casting it. You can also use the knowledge to write the spell into a spellbook or teach it to your familiar. This knowledge remains in your mind for 24 hours, after which time it is lost. The mnemonic siphon is capable of absorbing up to 1 spell per 2 caster levels you have before being discharged. If you are not capable of learning a stolen spell normally, the knowledge is useless to you.', NULL, NULL, false, false),
  ('modify_memory', 'Modify Memory', 'enchantment', 'compulsion', 'mind-affecting', 6, 'arcane', 'bard 4; Subdomain loss 6, memory 6', '1 round; see text', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, 'permanent', 'Will negates', 'yes', 'You reach into the subject’s mind and modify as many as 5 minutes of its memories in one of the following ways.', NULL, NULL, false, false),
  ('molten_orb', 'Molten Orb', 'evocation', 'earth, fire', NULL, 2, 'arcane', 'bloodrager 2, magus 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'ranged attack', 'instantaneous', 'none', 'yes', 'You create a fist-sized, red-hot ball of molten metal that you immediately hurl as a splash weapon. A direct hit deals 2d6 points of fire damage. Every creature within 5 feet of where the ball hits takes 1d6 points of fire damage from the splash (Reflex half). Each of these creatures takes an additional 1d6 points of fire damage on its turn for the next 1d3 rounds, unless it is cooled off (with water, snow, or any effect that deals 5 or more points of cold damage).', NULL, NULL, false, false),
  ('moment_of_greatness', 'Moment of Greatness', 'enchantment', 'compulsion', 'mind-affecting', 1, 'divine', 'bard 1, cleric 1, psychic 1, sorcerer/wizard 1; Bloodline imperious 1', '1 standard action', '50 ft.', 'The caster and allies within a 50-ft. burst centered on the caster', NULL, NULL, '1 minute/level or until discharged', 'none', 'yes (harmless)', 'Each creature affected by this spell is given the potential for greater success and glory. If the affected creature is benefiting from a morale bonus of any type, it can double that morale bonus on one roll or check, before making the roll. Once an affected creature uses this spell’s effect, the spell is discharged for that subject.', 'rabbit fur', NULL, true, false),
  ('moment_of_prescience', 'Moment of Prescience', 'divination', NULL, NULL, 8, 'arcane', 'sorcerer/wizard 8, witch 8; Domain luck 8; Subdomain memory 8; Bloodline destined 8, dreamspun 8, harrow 8; Elemental School void 8; Mystery lore 8, occult 8', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level or until discharged', NULL, NULL, 'This spell grants you a sixth sense. Once during the spell’s duration, you may choose to use its effect. This spell grants you an insight bonus equal to your caster level (maximum +25) on any single attack roll, combat maneuver check, opposed ability or skill check, or saving throw. Alternatively, you can apply the insight bonus to your AC against a single attack (even if flat-footed). Activating the effect doesn’t take an action; you can even activate it on another character’s turn. You must choose to use the moment of prescience before you make the roll it is to modify. Once used, the spell ends. You can’t have more than one moment of prescience active on you at the same time.', NULL, NULL, false, false),
  ('monkey_fish', 'Monkey Fish', 'transmutation', NULL, NULL, 1, 'divine', 'alchemist 1, druid 1, magus 1, psychic 1, shaman 1, sorcerer/wizard 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'Your hands and feet alter to make you better at climbing and swimming. You gain a 10 foot climb speed and swim speed. This spell has no effect if you are wearing medium or heavy armor or carrying a medium or heavy load.', NULL, NULL, false, false),
  ('monstrous_extremities', 'Monstrous Extremities', 'transmutation', 'polymorph', NULL, 3, 'divine', 'bloodrager 3, cleric 3, sorcerer/wizard 3, witch 4', '1 minute', 'touch', 'creature touched', NULL, NULL, '1 hour/level', 'Will negates', 'yes', 'You change one of the extremities of the creature touched—arms or legs only—into another shape of approximately the same size and mass. You can choose a tentacle, a hoof, or a wing.', NULL, NULL, false, false),
  ('monstrous_physique', 'Monstrous Physique', 'transmutation', 'polymorph', NULL, 3, 'arcane', 'alchemist 3, bloodrager 3, magus 3, sorcerer/wizard 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'When you cast this spell, you can assume the form of any Small or Medium creature of the monstrous humanoid type. If the form you assume has any of the following abilities, you gain the listed ability: climb 30 feet, fly 30 feet (average maneuverability), swim 30 feet, darkvision 60 feet, low-light vision, and scent. If the form you assume has the aquatic subtype, you gain the aquatic and amphibious subtypes.', 'a piece of the creature whose form you plan to assume', NULL, false, false),
  ('moonstruck', 'Moonstruck', 'enchantment   Level bloodrager 4, druid 4, sorcerer/wizard 4, witch 4; Subdomain insanity 4, moon 4, rage 6; Elemental School void 4; Mystery lunar 4', 'compulsion', 'emotion, mind-affecting', 9, 'arcane', NULL, '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 round/level', 'Will negates', 'yes', 'You invoke the mystical power of the moon to drive the target into a mad, bestial frenzy. If the target fails its save, it is dazed for 1 round, dropping held items as its nails and teeth elongate and sharpen. The target gains a bite attack and two claw attacks that deal damage appropriate for the creature’s size, and for the remainder of the spell’s duration the target behaves as if under simultaneous rage and confusion spells, attacking with its natural weapons in preference to other actions. During the final round of the spell’s duration, the target is again dazed as it returns to its normal state.', 'a pinch of powdered moonstone', NULL, false, false),
  ('morning_sun', 'Morning Sun', 'evocation', NULL, 'light', 6, 'divine', 'cleric/oracle 7, druid 7, inquisitor 6, shaman 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '60-ft. radius', NULL, '1 minute/level (D)', 'Fort negates and Reflex half; see text', 'no', 'This spell conjures a miniature sphere of sunlight, approximately the size of a human fist, at a desired location within range.', '500 gp worth of gold dust', NULL, false, true),
  ('mortal_terror', 'Mortal Terror', 'enchantment', NULL, 'fear, mind-affecting', 2, 'divine', 'antipaladin 2, arcanist 2, bard 2, cleric/oracle 2, inquisitor 2, mesmerist 2, psychic 2, shaman 2, skald 2, sorcerer/wizard 2, warpriest 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will partial (see text)', 'yes', 'You imbue the target with an exaggerated sense of its own mortality and a drive for self-preservation.', NULL, NULL, false, false),
  ('motes_of_dusk_and_dawn', 'Motes of Dusk And Dawn', 'evocation', NULL, 'darkness, light', 3, 'divine', 'bard 3, magus 3, medium 3, mesmerist 3, occultist 3, psychic 3, shaman 3, sorcerer/wizard 3, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'Up to four motes, all within a 10-ft.-radius area', '1 minute (D)', 'none', 'no', 'When you cast this spell, you create up to four motes that shed light or darkness in a 20-foot-radius, increasing or decreasing the illumination level by up to two categories. You decide whether each individual mote sheds light or darkness when the spell is cast.', NULL, NULL, false, false),
  ('mount', 'Mount', 'conjuration', 'summoning', NULL, 1, 'arcane', 'bloodrager 1, magus 1, sorcerer/wizard 1, summoner/unchained summoner 1, witch 1', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one mount', '2 hours/level (D)', 'none', 'no', 'You summon a light horse or a pony (your choice) to serve you as a mount. The steed serves willingly and well. The mount comes with a bit and bridle and a riding saddle.', 'a bit of horse hair', NULL, false, false),
  ('move_earth', 'Move Earth', 'transmutation', NULL, 'earth', 6, 'divine', 'druid 6, sorcerer/wizard 6; Bloodline ghoul 6; Elemental School earth 6', 'see text', 'long (400 ft. + 40 ft./level)', NULL, 'dirt in an area up to 750 ft. square and up to 10 ft. deep (S)', NULL, 'instantaneous', 'none', 'no', 'Move earth moves dirt (clay, loam, sand, and soil), possibly collapsing embankments, moving hillocks, shifting dunes, and so forth.', 'clay, loam, sand, and an iron blade', NULL, false, false),
  ('mud_buddy', 'Mud Buddy', 'conjuration', 'creation', NULL, 2, 'divine', 'druid 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '5 cubic feet of earth or mud', NULL, NULL, '1 hour/level (D) (see text)', NULL, NULL, 'You create a Small minion out of mud, and it obeys your commands.', '1 pint of water', NULL, false, false),
  ('mudball', 'Mudball', 'conjuration', 'creation', 'earth', 1, 'divine', 'bloodrager 1, druid 1, magus 1, sorcerer/wizard 1, witch 1 (goblin)', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'single fist-sized blob of sticky mud', 'instantaneous', 'Reflex negates; see text', 'no', 'When you cast this spell, you conjure a single ball of sticky mud and launch it at an enemy’s face as a ranged touch attack. If the mudball hits, the target is blinded. Each round at the beginning of its turn, a creature blinded by this spell can attempt a Reflex saving throw to shake off the mud, ending the effect. The mudball can also be wiped off by the creature affected by it or by a creature adjacent to the creature affected by it as a standard action.', NULL, NULL, false, false),
  ('muffle_sound', 'Muffle Sound', 'illusion', 'glamer', NULL, 2, 'divine', 'bard 2, cleric/oracle 2, inquisitor 2, mesmerist 2, psychic 2', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 minute/level (D)', 'Will negates', 'yes', 'You suppress sounds made by the targets, granting them a +4 bonus on Stealth checks. The targets have a 20% chance of spell failure when casting spells with verbal components or using abilities that have audible components (such as some bardic performances). This spell does not hamper the targets’ ability to hear other sounds and provides no protection against language-dependent or sonic spells and effects.', NULL, NULL, false, false),
  ('murderous_command', 'Murderous Command', 'enchantment', 'compulsion', 'mind-affecting', 1, 'divine', 'antipaladin 1, cleric/oracle 1, psychic 1; Subdomain hatred 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, '1 round', 'Will negates', 'yes', 'You give the target a mental urge to kill its nearest ally, which it obeys to the best of its ability. The target attacks its nearest ally on its next turn with a melee weapon or natural weapon. If necessary, it moves to or charges to the nearest ally in order to make this attack. If it is unable to reach its closest ally on its next turn, the target uses its turn to get as close as possible to the ally.', NULL, NULL, false, false),
  ('murderous_crow_orc', 'Murderous Crow (Orc)', 'conjuration', 'summoning', 'see text', 1, 'divine', 'antipaladin 1, cleric 1, paladin 1, sorcerer/wizard 1, summoner 1, witch 1', '1 round', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'one crow', '1 round/level', 'none', 'no', 'You conjure a supernaturally vicious and clever crow to watch over you on the battlefield. Choose one of the following templates; the crow has that template and this spell gains the descriptor listed in parentheses: celestial (good), entropic (chaotic), fiendish (evil), or resolute (lawful). In addition to its normal abilities, the crow gains the Improved Steal feat as a bonus feat and gains an eye rake attack. If both of its claw attacks hit the same living foe in a single round, that foe must succeed at a DC 13 Reflex save or be blinded as the bird scratches and tears at the foe’s eyes. The blindness lasts for 1d4 days or until healed with remove blindness.', NULL, 'a crow’s feather', false, false),
  ('music_of_the_spheres', 'Music of the Spheres', 'conjuration', 'healing', 'sonic', 5, 'divine', 'bard 5, cleric 6', '1 standard action', '20 ft.', NULL, '20-ft.-radius spherical emanation, centered on you', NULL, 'concentration, up to 1 round per level', 'none', 'yes (harmless)', 'The music of the spheres is the harmonic constant that plays under and through all of reality. It is this constant song, this otherworldly music, that keeps the laws of reality constant and the connections between the planes of existence strong.', 'a stick of incense treated with special balms', NULL, false, false),
  ('mutagenic_touch', 'Mutagenic Touch', 'transmutation', NULL, NULL, 4, 'arcane', 'alchemist 4', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'special (see below)', 'Fortitude negates (harmless)', 'yes (harmless)', 'When you are under of the effects of your mutagen, you can cast this spell to safely pass it to another creature with a touch. You must make a successful touch attack against the target. On a hit, the effect of the mutagen passes to the target touched, though in a lesser form. The mutagen’s effect ends for you, and passes on to the creature touched, but the target only gets half of the alchemical bonus to the physical ability modifier you chose when took the mutagen, and twice the penalty to the corresponding mental ability score. If the target’s mental ability score drops below 3, the target is also confused for the remaining duration of the mutagen. The mutagen continues until the duration has ended. It can be ended earlier if the target drinks or is fed the contents of a vial of antitoxin, but with only 50% chance of success.', 'a whole fingernail', NULL, false, false),
  ('mydriatic_spontaneity', 'Mydriatic Spontaneity', 'evocation', NULL, 'darkness, light', 3, 'arcane', 'bard 3, mesmerist 3, psychic 3, sorcerer/wizard 4, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level', 'Will negates', 'yes', 'You overstimulate the target with alternating flashes of light and shadow within its eyes, causing its pupils to rapidly dilate and contract. While under the effects of this spell, the target is racked by splitting headaches and unable to see clearly, becoming nauseated for the spell’s duration. Each round, the target’s pupils randomly become dilated or contracted for 1 round. During any round that its eyes are dilated, the target is blinded if exposed to bright light or dazzled if exposed to normal light. During any round its eyes are contracted, the target is blinded if exposed to darkness or dazzled if exposed to dim light. In addition, any creature can attempt a Stealth check to avoid detection from the target, even if the creature lacks cover or concealment.', NULL, NULL, false, false),
  ('naga_shape', 'Naga Shape', 'transmutation', 'polymorph', NULL, 4, 'arcane', 'alchemist 4, bloodrager 4, magus 4, sorcerer/wizard 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'Whenever you cast this spell, you can assume the form of any type of Large naga (including most nagas, but not royal nagas), though not the form of a specific individual. In effect, you transform into a Large serpent, gaining a +4 size bonus to your Strength, a –2 penalty to your Dexterity, and a +4 natural armor bonus. Unlike with beast shape II, however, you keep your own head when using this spell and can cast spells with verbal and somatic components, even though the naga form doesn’t have hands.', 'a piece of the creature whose form you want to assume', NULL, false, false),
  ('named_bullet', 'Named Bullet', 'divination', NULL, NULL, 3, 'divine', 'inquisitor 4, ranger 3, sorcerer/wizard 4, witch 4', '1 standard action', 'touch', 'one piece of ammunition or one thrown weapon', NULL, NULL, '10 minutes/level or until discharged', 'Will negates (harmless, object)', 'yes (harmless, object)', 'You imbue the target with deadly accuracy against a selected creature type (and subtype for humanoids or outsiders) or a specific creature you know and can name. When used against the selected creature, the ammunition never misfires and is unaffected by concealment (but not total concealment), and at a range of 30 feet or less, the attack targets the selected creature’s touch AC. When the target hits the selected creature, you must overcome that creature’s spell resistance, or this spell has no effect. A normal hit scored using the target against the selected creature is considered to be a critical threat and deals 1 extra point of damage per caster level (maximum 20), which is not multiplied on a critical hit. A natural critical hit deals the same extra damage, but that damage is multiplied due to the critical.', 'an item from the selected creature or creature type', NULL, true, false),
  ('nap_stack', 'Nap Stack', 'necromancy', NULL, NULL, 3, 'divine', 'cleric/oracle 3', '1 minute', '30 ft.', NULL, '30-ft.-radius emanation', NULL, '8 hours', 'Will negates (harmless)', 'yes (harmless)', 'You reduce the amount of uninterrupted sleep or rest creatures within the spell’s area need in order to recover from injuries, regain spells, or other special abilities to 2 hours instead of the normal eight. In addition, if creatures continue to sleep or rest beyond the initial 2 hours, every additional 2 hours counts as a day of rest for the purpose of recovering hit points, ability damage, as well as for enduring diseases, poisons, or other afflictions. This means 8 total hours of sleep counts as 4 days for natural healing and for saving throws as diseases or similar afflictions run their course. When suffering from diseases, poison, or other afflictions, sleepers experience vivid dreams that help them track their recovery. If things go poorly they can, at any time, wake themselves up in order to seek a better alternative. If awoken or otherwise disturbed during this 8-hour period, creatures may return to sleep but they no longer enjoy the benefits of the accelerated recovery time. Creatures can only enjoy the benefits of this spell once in any 1-week period.', 'a little silk pillow worth 100 gp', NULL, false, true),
  ('natural_rhythm', 'Natural Rhythm', 'transmutation', NULL, NULL, 2, 'divine', 'druid 2', '1 standard action', 'touch', NULL, NULL, NULL, '1 round/level', 'Will negates (harmless)', 'yes (harmless)', 'You enhance a creature’s ability to harm an opponent based on the number of times it has already injured that opponent with a natural attack. Each time the creature successfully strikes an opponent with a natural attack, the subject gains a cumulative +1 bonus on damage rolls made against that opponent when making natural attacks (maximum +5 bonus). If an attack misses, the bonus to damage for all attacks resets to +0.', 'a handful of pebbles dropped one by one onto the ground', NULL, false, false),
  ('nature_s_exile', 'Nature’s Exile', 'transmutation', NULL, 'curse', 3, 'divine', 'druid 3, witch 3', '1 standard action', 'touch', NULL, NULL, NULL, 'permanent', 'Will negates', 'yes', 'This spell curses the creature touched, making it inimical to the natural world. All animals have an initial attitude of hostile toward the target. Familiars, being magical beasts, are not affected by this spell, but animal companions are. If you have an animal companion, it does not become hostile, but as long as you remain cursed, your animal companion takes a -2 penalty on all attack rolls, skill checks, and saving throws. The target also takes a -10 penalty on Survival skill checks as the weather and environment themselves seem to conspire to cause trouble.', NULL, NULL, true, false),
  ('nature_s_paths', 'Nature’s Paths', 'divination', NULL, NULL, 1, 'divine', 'bard 1, druid 1, hunter 1, inquisitor 1, ranger 1, shaman 1, witch 1', '1 standard action', 'touch', 'one creature', NULL, NULL, '8 hours (D)', 'Will negates (harmless)', 'yes (harmless)', 'The target instinctively knows the shortest, easiest, and fastest way through the wilderness. For the purpose of determining overland speed, the target treats any trackless terrain as though there were a trail or road, and any terrain with a road or trail as though there were a highway. Up to one creature per caster level traveling with the target can also benefit from the effect. The spell functions only outdoors and does not function in magically altered terrain.', 'a smooth stone', NULL, true, false),
  ('nature_s_ravages', 'Nature’s Ravages', 'necromancy', NULL, NULL, 3, 'divine', 'cleric 4, witch 3', '1 minute/HD of target', 'close (25 ft. + 5 ft./level)', 'corpse of creature whose total number of HD does not exceed your caster level', NULL, NULL, 'instantaneous', 'none', 'no', 'You greatly speed up the decomposition process of a nearby corpse and warp the fibers of time that permeate it, aging the corpse an additional amount of time equal to up to 1 day per 2 caster levels (maximum 10 days at 20th level). This spell prompts all the natural effects of the intended decomposition period, including crumbled clothing, rotted or liquefied flesh, maggot infestations, and the infiltration of any surrounding vegetation.', 'dried maggots', NULL, true, false),
  ('nauseating_dart', 'Nauseating Dart', 'conjuration', 'creation', 'poison', 1, 'divine', 'druid 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one poisonous stinger', 'instantaneous', 'Fortitude partial (see text)', 'no', 'You spit a poisonous stinger around the size of a quill at a creature within range, as though you had fired a dart from a blowgun. You must succeed at a ranged attack to hit your target. The stinger deals 1d2 points of piercing damage and poisons the target, causing it to become nauseated for 1 round unless it succeeds at a Fortitude save.', NULL, NULL, true, false),
  ('nauseating_trail', 'Nauseating Trail', 'conjuration', 'creation', 'poison', 3, 'divine', 'alchemist 3, druid 3, magus 3, shaman 3, sorcerer/wizard 3, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one willing creature', NULL, NULL, '1 round/level', 'none and Fort negates (see text)', 'no', 'The target exudes stinking vapors that fill its space. The vapors do not obscure sight, but it nauseates creatures as stinking cloud. The target is immune to these vapors. These vapors persist as the creature moves, filling every square it passes through until it has filled a number of squares equal to 4 × your caster level—if you move through more squares than that, the squares over that amount at not filled with the vapors. Each creature that enters or ends its turn in the area filled with these vapors must succeed at a Fortitude save or become nauseated as long as it remains in the square and for 1d4+1 rounds after it leaves.', 'a rotten egg or cabbage leaves', NULL, false, false),
  ('necromantic_burden', 'Necromantic Burden', 'necromancy', NULL, NULL, 2, 'divine', 'cleric/oracle 2, sorcerer/wizard 3, witch 3', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one undead creature', NULL, NULL, '1 hour/level', 'Will negates', 'yes', 'You make an undead creature more difficult for necromancers and clerics to control via effects such as Command Undead or control undead. If the target fails its Will save, the target’s effective number of Hit Dice is doubled for the purposes of determining whether it remains under the control of another creature. Regardless of the target’s actual Hit Dice, its effective HD cannot exceed twice your caster level. (For example, a 12th-level cleric could cast this spell to cause an undead creature with 15 HD to instead effectively have 24 HD for the purpose of controlling it.)', 'a handful of knucklebones', NULL, true, false),
  ('necrostasis', 'Necrostasis', 'necromancy', NULL, NULL, 2, 'divine', 'cleric 2, inquisitor 2, shaman 2, sorcerer/wizard 3, spiritualist 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one undead creature', NULL, NULL, '1 round/level (D)', 'Will negates', 'yes', 'You drain necromantic energy from an undead creature, inducing a sluggish stupor. The target becomes staggered. For the duration of the spell, dark wisps of energy seep out of the target creature.', 'a finger bone', NULL, true, false),
  ('negate_aroma', 'Negate Aroma', 'transmutation', NULL, NULL, 1, 'divine', 'alchemist 1, druid 1, ranger 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 hour/level (D)', 'Fortitude negates', 'yes', 'With a gesture, this spell allows you to dismiss even the foulest or most distinctive scents. When cast, the targeted creatures or objects lose all natural and unnatural odors. A creature under the effect of negate aroma cannot be tracked, located, or pinpointed by the scent special quality. In addition, this spell prevents the target creature from using the stench special ability and similar odor-based abilities (such as those possessed by troglodytes).', 'a pinch of alum', NULL, true, false),
  ('negative_reaction', 'Negative Reaction', 'illusion', 'glamer', NULL, 1, 'arcane', 'bard 1, magus 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'The target’s actions and words fail to impress. The target of this spell takes a –10 penalty on any Bluff, Diplomacy, and Intimidate checks as well as any performance combat checks it attempts.', NULL, NULL, false, false),
  ('nereid_s_grace', 'Nereid’s Grace', 'abjuration', NULL, NULL, 1, 'divine', 'druid 1, witch 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'You radiate the unearthly grace of a nereid. If you’re not wearing armor, you gain a deflection bonus to your AC and CMD equal to your Charisma bonus (maximum +3). The maximum increases by 1 for every 6 levels you possess (maximum +6 at 18th level).', NULL, NULL, false, false),
  ('neutral_buoyancy', 'Neutral Buoyancy', 'evocation', NULL, NULL, 2, 'divine', 'alchemist 2, bard 2, druid 2, hunter 2, investigator 2, medium 2, occultist 2, psychic 2, ranger 2, shaman 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level', 'Will negates', 'yes', 'The target’s buoyancy becomes and stays neutral, regardless of how dense the target and its gear are. Among other effects, the target neither sinks nor rises when it doesn’t attempt a Swim check, making it easier to stay put while performing demanding actions or when helpless or disabled, and the target can swim up and down with equal ease.', 'a bag of air', NULL, true, false),
  ('neutralize_poison', 'Neutralize Poison', 'conjuration', 'healing', NULL, 3, 'divine', 'alchemist 4, bard 4, cleric/oracle 4, druid 3, inquisitor 4, paladin 4, ranger 3, shaman 4, witch 4; Subdomain restoration 4; Mystery life 3', '1 standard action', 'touch', 'creature or object of up to 1 cu. ft./level touched', NULL, NULL, 'instantaneous or 10 min./level; see text', 'Will negates (harmless, object)', 'yes (harmless, object)', 'You detoxify any sort of venom in the creature or object touched. If the target is a creature, you must make a caster level check (1d20 + caster level) against the DC of each poison affecting the target. Success means that the poison is neutralized. A cured creature suffers no additional effects from the poison, and any temporary effects are ended, but the spell does not reverse instantaneous effects, such as hit point damage, temporary ability damage, or effects that don’t go away on their own.', 'charcoal', NULL, true, false),
  ('night_blindness', 'Night Blindness', 'necromancy', NULL, 'curse', 1, 'divine', 'antipaladin 1, bard 1, bloodrager 1, cleric 2, mesmerist 1, psychic 1, shaman 2, sorcerer/wizard 1, spiritualist 2, witch 1', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one living creature', NULL, NULL, '1 day/level (D)', 'Will negates (harmless)', 'no', 'Your target’s vision becomes impaired as if the light level were one step lower, treating bright light as normal light, normal light as dim light, and dim light as darkness. In addition, the subject gains no benefit from darkvision, low-light vision, or the see in darkness ability. The subject gains a +4 bonus on saving throws to resist the blind or dazzled condition caused by bright light (such as flare). Remove blindness/deafness dispels night blindness.', NULL, NULL, false, false),
  ('night_of_blades', 'Night of Blades', 'evocation', NULL, NULL, 3, 'divine', 'antipaladin 4, inquisitor 3, ranger 4, sorcerer/wizard 3, summoner 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'wall of blades up to 10 ft. long/level and 10 ft. tall', '1 minute/level (D)', 'Reflex half', 'yes', 'Useful primarily to those who skulk in the darkness, this spell is a temporary trap for the unwary. You create an immobile wall of tiny black blades that whirl and tear into creatures like a cyclone. Anyone who enters this space takes 1d4 points of damage per caster level (maximum 10d4), though a successful Reflex save halves the damage. The spell cannot be cast so that it appears in a space already occupied by Small or larger creatures.', NULL, NULL, false, false),
  ('night_terrors', 'Night Terrors', 'illusion )', 'phantasm', 'emotion, evil, mind-affecting', 6, 'arcane', 'bard 6, mesmerist 6, psychic 6, sorcerer/wizard 6, witch 6', '1 standard action', 'touch', 'intelligent creature touched', NULL, NULL, '1 day/level (D)', 'Will negates', 'yes', 'The target of this spell gains no benefit from normal or magical sleep, writhing in a series of nightmares that torture its psyche and diminish its ability to perform strenuous tasks. The target doesn’t heal ability or hit point damage naturally and can’t prepare spells or regain spell slots. After one night of poor sleep, the target is fatigued (or exhausted if it was fatigued before trying to rest). A creature affected by this spell doesn’t recover from the fatigued or exhausted condition inflicted by this spell after resting, nor do spells such as lesser restoration provide any respite. Each restless night, the target takes 1d4 points of Wisdom damage, which also can’t be recovered by magic while night terrors is active.', 'a drop of black ink', NULL, true, false),
  ('nightmare', 'Nightmare', 'illusion', 'phantasm', 'mind-affecting, evil', 5, 'arcane', 'alchemist 5, bard 5, sorcerer/wizard 5; Domain madness 5; Subdomain sleep 6', '10 minutes', 'unlimited', 'one living creature', NULL, NULL, 'instantaneous', 'Will negates; see text', 'yes', 'You send a hideous and unsettling phantasmal vision to a specific creature that you name or otherwise specifically designate.', NULL, NULL, false, false),
  ('nine_lives', 'Nine Lives', 'abjuration', NULL, NULL, 8, 'divine', 'cleric 8, witch 8', '1 standard action', 'touch', 'one creature touched', NULL, NULL, '1 hour/level', 'Will negates (harmless)', 'yes (harmless)', 'Despite its name, this powerful ward does not grant the target multiple lives, but rather gives the target the ability to get out of trouble and relieves harmful effects and conditions. For the spell’s duration, the target can use any of the following abilities as an immediate action, but only up to a total of nine times, at which point the spell ends.', 'a cat’s whisker', NULL, true, false),
  ('nixie_s_lure', 'Nixie’s Lure', 'enchantment', 'charm', 'mind-affecting, sonic', 3, 'divine', 'bard 3, druid 4, mesmerist 3, psychic 3, sorcerer/wizard 4, summoner 4, witch 4', '1 standard action', '300 ft.', 'all creatures within a 300-ft.-radius burst centered on you', NULL, NULL, 'concentration + 1 round/level (D)', 'Will negates', 'yes', 'This spell creates an unearthly and infectious song that seductively summons all who hear it. Nixie’s lure affects a maximum of 24 Hit Dice of creatures. Creatures in the area who fail their saves are lured by the song and move toward you using the most direct means available. If the path leads them into a dangerous area such as through fire or off a cliff, the creatures each receive a second saving throw to end the effect before moving into peril. Creatures lured by the spell’s song can take no actions other than to defend themselves. A victim within 5 feet of you simply stands still and for the duration of the spell remains fascinated.', NULL, NULL, false, false),
  ('node_of_blasting', 'Node of Blasting', 'abjuration', NULL, 'mind-affecting', 2, 'arcane', 'medium 3, mesmerist 3, occultist 2, psychic 3', '1 standard action', 'touch', 'one touched object weighing no more than 10 lbs.', NULL, NULL, 'permanent until discharged (D)', 'Will partial; see text', 'no', 'You imbue an object with psychic energy. The node of blasting unleashes a mental blast when a creature with a mind touches the object, dealing 6d6 points of damage to the creature touching the object and causing the creature to be staggered for 1 minute. A successful saving throw halves the damage and negates the staggered condition.', NULL, NULL, false, false),
  ('nondetection', 'Nondetection', 'abjuration', NULL, NULL, 2, 'divine', 'alchemist 3, antipaladin 3, inquisitor 3, medium 2, mesmerist 3, occultist 3, psychic 3, ranger 4, sorcerer/wizard 3, spiritualist 3, summoner/unchained summoner 3; Domain trickery 3; Elemental School void 3', '1 standard action', 'touch', 'creature or object touched', NULL, NULL, '1 hour/level', 'Will negates (harmless, object)', 'yes (harmless, object)', 'The warded creature or object becomes difficult to detect by divination spells such as clairaudience/clairvoyance, locate object, and detect spells. Nondetection also prevents location by such magic items as crystal balls. If a divination is attempted against the warded creature or item, the caster of the divination must succeed on a caster level check (1d20 + caster level) against a DC of 11 + the caster level of the spellcaster who cast nondetection. If you cast nondetection on yourself or on an item currently in your possession, the DC is 15 + your caster level.', 'diamond dust worth 50 gp', NULL, false, true),
  ('numerological_evocation', 'Numerological Evocation', 'evocation', NULL, NULL, 3, 'arcane', 'magus 3, sorcerer/wizard 3, witch 4', '1 standard action', 'see text', 'see text', NULL, NULL, 'instantaneous', 'Reflex half', 'yes', 'The Path of Numbers', NULL, NULL, false, false),
  ('numerological_resistance', 'Numerological Resistance', 'abjuration', NULL, NULL, 3, 'divine', 'cleric 3, sorcerer/wizard 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'see text', NULL, NULL, 'see text', 'none', 'no', 'Numerological resistance allows numerologists to use the Path of Numbers to grant their allies resilience in the face of elemental dangers. Roll 5d8; this is your dice pool. You will use each die in the pool exactly once to customize numerological resistance.', NULL, NULL, false, false),
  ('oasis', 'Oasis', 'transmutation', NULL, NULL, 5, 'divine', 'cleric 6, druid 5, sorcerer/wizard 6', '30 minutes', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'water source similar to a natural spring', 'instantaneous', 'none', 'no', 'This spell functions in any natural terrain on the Material Plane. It redirects the flow of water in the ground toward the surface at the designated point, creating a permanent water source similar to a natural spring. The spring discharges 5 gallons of pure drinking water per caster level each hour.', '1 gallon of water', NULL, true, false),
  ('oath_of_anonymity', 'Oath of Anonymity', 'illusion', 'glamer', NULL, 0, 'divine', 'bard 0, inquisitor 0, medium 0, paladin 1, sorcerer/wizard 0', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level', NULL, NULL, 'You swear an oath not to reveal your identity, magically preventing anyone from discovering it so long as you avoid revealing your face or other easily identifiable features. The spell distorts your voice and subtly alters your body language and the appearance of your gear and any animals you use, whether as companions, mounts, or otherwise. This spell does not make you appear to be a different creature type, nor does it change your apparent height or body type.', NULL, NULL, false, false),
  ('oath_of_justice', 'Oath of Justice', 'necromancy', NULL, NULL, 3, 'divine', 'cleric/oracle 3, paladin 2 (Kols)', '1 standard action', 'touch', 'two creatures touched', NULL, NULL, 'permanent (see text)', 'none', 'no', 'This spell seals a solemn vow between two creatures. When this spell is cast, the targets must clasp hands and swear their oath in Kols’s name. The spell functions like mark of justice, except as noted above and rather than being cursed, the oath-breaker gains a mark on the face indicating to all dwarves who see it that the target has broken a sacred oath, which gives the oath-breaker a –4 penalty to influence dwarves. The mark can be removed as described in the mark of justice spell, or the other target can forgive the oath- breaker, which causes the mark to vanish.', NULL, NULL, true, false),
  ('oath_of_peace', 'Oath of Peace', 'abjuration', NULL, NULL, 4, 'divine', 'paladin 4', '1 standard action', 'personal', NULL, NULL, NULL, '1 round/level', NULL, NULL, 'Entreating your deity for aid, you make a temporary oath of peace, granting you superior defenses but means you can’t attack for the duration of the oath. For as long as you are subject to this spell, you gain a +5 sacred bonus to AC and on saving throws, as well as DR 10/evil. If you make a direct or indirect attack or any show any hostility toward any creature, the spell immediately ends.', NULL, NULL, false, false),
  ('object_possession_lesser', 'Object Possession, Lesser', 'necromancy', NULL, NULL, 2, 'arcane', 'medium 2, mesmerist 3, occultist 2, psychic 3, sorcerer/wizard 4, spiritualist 3, witch 4', '1 standard action', 'touch', 'unattended Tiny or Small object', NULL, NULL, '1 minute/level (D)', 'none', 'No', 'This spell functions as possession, except you possess an object instead of a creature.', NULL, NULL, false, false),
  ('object_reading', 'Object Reading', 'divination', NULL, NULL, 1, 'arcane', 'medium 1, mesmerist 2, occultist 1, psychic 2, spiritualist 2', '1 standard action', 'touch', 'one touched object', NULL, NULL, 'concentration, up to 1 round per level (D)', 'none', 'no', 'You read the psychic impressions left upon an object by emotionally or psychically charged events in the item’s history, or the information imprinted by the charge object or implant false reading spells. This spell returns the same information as the psychometry occult skill unlock, but gives 1 piece of information when cast and requires 1 round of concentration per additional piece of information instead of 1 minute. You must still attempt an Appraise check to see how much information you gain. You gain a +10 competence bonus on the check.', NULL, NULL, false, false),
  ('obscure_object', 'Obscure Object', 'abjuration', NULL, NULL, 1, 'divine', 'bard 1, cleric/oracle 3, inquisitor 3, mesmerist 1, occultist 2, psychic 2, sorcerer/wizard 2, spiritualist 3; Mystery spellscar 2', '1 standard action', 'touch', 'one object touched of up to 100 lbs./level', NULL, NULL, '8 hours (D)', 'Will negates (object)', 'yes (object)', 'This spell hides an object from location by divination (scrying) effects, such as the scrying spell or a crystal ball. Such an attempt automatically fails (if the divination is targeted on the object) or fails to perceive the object (if the divination is targeted on a nearby location, object, or person).', 'chameleon skin', NULL, true, false),
  ('obscure_poison', 'Obscure Poison', 'abjuration', NULL, NULL, 1, 'divine', 'alchemist 1, antipaladin 1, bard 1, cleric 1, druid 1, mesmerist 1, shaman 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'one dose of poison or one venomous creature touched', NULL, NULL, '1 hour/level', 'none', 'no', 'You make the touched poison difficult to detect or identify. Detect poison and similar effects detect an obscured poison only with a successful caster level check against a DC equal to 15 + your caster level (rolled secretly by the GM). Even if the poison is detected, the DC of Craft (alchemy) or Wisdom checks to identify the poison is increased by 10.', 'herbs used in antitoxins worth 10 gp', NULL, false, true),
  ('obscured_script', 'Obscured Script', 'illusion )', 'phantasm', NULL, 2, 'arcane', 'bard 2, mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 2', '1 standard action', 'touch', 'one touched page, scroll, inscription, book, or other document no more than 3 feet in any dimension', NULL, NULL, '24 hours (D)', 'none; see text', 'no', 'You create a latent illusion that clouds the judgment and reading ability of any creature that examines a targeted text. While casting the spell, you can designate up to one creature other than yourself per level to be immune to the effects. All other creatures that read the text must succeed at a Will save or find it difficult to properly parse and decipher the contents. This increases the DC of Linguistics checks to decipher the text by an amount equal to your caster level (maximum +10), and it increases the DC of the Wisdom check to avoid drawing a false conclusion by an equal amount. Unaffected creatures gain a circumstance bonus equal to your caster level (maximum +10) on Bluff checks to deceive affected creatures about the text’s contents. The spell obscures any magical glyphs, runes, or symbols within the text, increasing the Perception DC to find such traps by an amount equal to half your caster level (maximum +5). Obscured script can be made permanent with a permanency spell by a caster of 10th level or higher for the cost of 5,000 gp.', 'a scrap of paper bearing a simple sentence written in at least five languages', NULL, false, false),
  ('obscuring_mist', 'Obscuring Mist', 'conjuration', 'creation', NULL, 1, 'divine', 'cleric/oracle 1, druid 1, magus 1, shaman 1, sorcerer/wizard 1, unchained summoner 1, witch 1; Domain air 1, darkness 1, water 1, weather 1; Bloodline ectoplasm 1; Elemental School water 1', '1 standard action', '20 ft.', NULL, NULL, 'cloud spreads in 20-ft. radius from you, 20 ft. high', '1 min./level (D)', 'none', 'no', 'A misty vapor arises around you. It is stationary. The vapor obscures all sight, including darkvision, beyond 5 feet. A creature 5 feet away has concealment (attacks have a 20% miss chance). Creatures farther away have total concealment (50% miss chance, and the attacker cannot use sight to locate the target).', NULL, NULL, false, false),
  ('obsidian_flow', 'Obsidian Flow', 'transmutation', NULL, 'earth, fire', 3, 'divine', 'druid 4, sorcerer/wizard 4, summoner 3, unchained summoner 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '20-ft.-radius burst', NULL, 'instantaneous', 'Reflex partial, see text', 'no', 'You convert a thin layer of the ground to molten glass that cools quickly. Creatures in the area take 1d6 points of fire damage per two caster levels (maximum of 10d6) and become entangled. Any creature within the area that makes a successful Reflex save takes half damage and is not entangled. An entangled creature can attempt to free itself by spending a move action to attempt a Strength check or Escape Artist check (the DC equals the spell’s saving throw DC).', 'a small piece of obsidian', NULL, true, false),
  ('old_salt_s_curse', 'Old Salt’s Curse', 'necromancy', NULL, 'curse', 5, 'divine', 'druid 5, witch 5', '1 standard action', 'touch', 'one creature', NULL, NULL, 'permanent', 'Will negates', 'yes', 'You inflict a curse of the roiling sea upon the target, making it permanently sickened. Anytime the target is on or in the water more than a mile from shore, it also becomes staggered with seasickness. This curse cannot be dispelled, though remove curse or break enchantment can negate it.', 'a flask of seawater', NULL, false, false),
  ('oneiric_horror', 'Oneiric Horror', 'illusion )', 'phantasm', 'mind-affecting', 1, 'arcane', 'bard 2, medium 1, mesmerist 2, psychic 2, sorcerer/wizard 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one living creature', NULL, NULL, '1 round/level (D)', 'Will negates', 'yes', 'You cause the subject to believe it is being attacked by a creature out of its nightmares. Each round, the subject makes a full-attack action against the creature. A flying creature can still attempt a Fly check to hover. Each round on its turn after making a full attack against the imaginary creature, the subject can attempt a new saving throw to end the effect. The subject is fatigued for 1 minute after the spell ends.', NULL, NULL, false, false),
  ('ooze_form', 'Ooze Form', 'transmutation', 'polymorph', NULL, 5, 'arcane', 'alchemist 5, magus 5, sorcerer/wizard 5', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'You assume the form of a Small or Medium ooze. Regardless of the type of ooze you transform into, you gain base speed 10 feet, climb speed 10 feet, swim speed 20 feet, and blindsense 30 feet. You gain a +4 resistance bonus on saving throws against mind-affecting effects and poison. A wood or metal weapon that strikes you takes acid damage as if from your slam unless the wielder succeeds at a Reflex saving throw.', 'a bit of the creature whose form you plan to assume', NULL, false, false),
  ('open_and_shut', 'Open and Shut', 'illusion', 'glamer', NULL, 1, 'divine', 'bard 1, inquisitor 1, sorcerer/wizard 1, witch 1', '1 swift action', 'touch', 'one door, window, or similar portal no more than 10 feet by 10 feet in area', NULL, NULL, '1 round/level (D)', 'Will disbelief', 'no', 'You alter the appearance of a door and disguise whether it is open or closed. You can cause the touched door to appear closed regardless of whether it is open or closed, to appear open regardless of whether it is open or closed, or to appear to open or close. After you cast the spell, you can change between these options as a move action. Creatures using a move action to open or shut the door can attempt a Will save to disbelieve the illusion.', NULL, 'a doornail, doorknob, or hinge', false, false),
  ('open_arms', 'Open Arms', 'transmutation', NULL, NULL, 5, 'arcane', 'sorcerer/wizard 5', '1 immediate action', 'touch', 'melee weapon touched', NULL, NULL, '1 minute/level', 'none', 'no', 'You cast this spell in response to a specific cavalier’s challenge, inquisitor’s judgment, or smite (such as a paladin’s smite evil) declared against you by an enemy creature. It can also be cast if a creature uses a spell that causes you to qualify as the creature’s favored enemy when you normally wouldn’t, such as instant enemy.', NULL, 'a magical or masterwork melee weapon', false, false),
  ('open_book', 'Open Book', 'divination', NULL, 'curse', 2, 'divine', 'antipaladin 2, bard 2, inquisitor 2, mesmerist 2, psychic 2, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'permanent', 'Will negates', 'yes', 'You lay bare not only the mind of a target, but the target’s history as well. The target takes a –2 penalty on saving throws against divinations, and Diplomacy checks to gather information about the target gain a bonus equal to half your caster level (maximum +10).', 'a page torn from a book', NULL, false, false),
  ('open_close', 'Open-Close', 'transmutation', NULL, NULL, 0, 'arcane', 'bard 0, magus 0, psychic 0, sorcerer/wizard 0, summoner/unchained summoner 0', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'object weighing up to 30 lbs. or portal that can be opened or closed', NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'You can open or close (your choice) a door, chest, box, window, bag, pouch, bottle, barrel, or other container. If anything resists this activity (such as a bar on a door or a lock on a chest), the spell fails. In addition, the spell can only open and close things weighing 30 pounds or less. Thus, doors, chests, and similar objects sized for enormous creatures may be beyond this spell’s ability to affect.', NULL, 'a brass key', false, false),
  ('opportunistic_loyalty', 'Opportunistic Loyalty', 'enchantment', 'compulsion', NULL, 1, 'divine', 'antipaladin 1, cleric 1, inquisitor 1, mesmerist 1, psychic 1, witch 1', '1 immediate action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Cast this spell when a creature within range casts a spell that provides an effect for its allies (such as bless or prayer). You are considered an ally of the caster for the purposes of that spell. Although you are momentarily considered an ally, the caster need not target you if the spell requires that the caster select one or more allies to be affected by the spell (as does haste). This spell does not allow a target spell to affect more creatures than described in its target entry. If this spell would raise the total number of affected targets above that allowed by the target spell, opportunistic loyalty has no effect.', NULL, NULL, false, false),
  ('oppressive_boredom', 'Oppressive Boredom', 'enchantment', 'compulsion', 'emotion, mind-affecting', 2, 'arcane', 'bard 2, medium 2, mesmerist 2, psychic 2, sorcerer/wizard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level or until broken (see text)', 'Will negates (see text)', 'yes', 'You fill your target with boredom. The target loses all interest in its current task and must make a Will save against the spell’s effect in order to perform its next action. If the target fails, it takes no action that round. The boredom lasts until the duration expires or the target breaks the spell’s effect with a successful Will save.', NULL, NULL, false, false),
  ('oracle_s_burden', 'Oracle’s Burden', 'necromancy', NULL, 'curse', 2, 'divine', 'oracle 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 minute/level', 'Will negates', 'yes', 'You entreat the forces of fate to bestow your oracle’s curse upon another creature. The target creature suffers all the hindrances and none of the benefits of your oracle’s curse class feature. You still suffer all effects of your oracle’s curse.', NULL, NULL, false, false),
  ('oracle_s_vessel', 'Oracle’s Vessel', 'transmutation', NULL, NULL, 4, 'divine', 'oracle 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes (harmless)', 'The target gains all the benefits of your oracle’s curse, with none of the penalties. In some cases, this has no effect (for example, a fighter with your haunted curse can’t cast spells and doesn’t gain any benefit from having additional spells known).', NULL, NULL, false, false),
  ('orb_of_the_void', 'Orb of the Void', 'necromancy', NULL, NULL, 8, 'divine', 'cleric/oracle 8, sorcerer/wizard 8; Elemental School void 8', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '1-ft.-diameter sphere', '1 round/level (D)', 'Fortitude negates', 'yes', 'You create a small weightless sphere of pure negative energy. As a move action, you can move it up to 30 feet per round in any direction. If it enters a space with a living creature, it stops moving for the round and that creature gains one negative level (Fortitude negates). Any creature passing through or ending its turn in the space occupied by the sphere gains one negative level (Fortitude negates). Twenty-four hours after gaining a negative level from the sphere, the subject must make a Fortitude saving throw (the DC of this save is equal to the DC of this spell) for each negative level. If the save succeeds, that negative level is removed. If it fails, that negative level becomes permanent.', 'a black gemstone of any kind worth 50 gp', NULL, false, true),
  ('orchid_s_drop', 'Orchid’s Drop', 'transmutation', NULL, NULL, 3, 'arcane', 'alchemist 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level', NULL, NULL, 'This extract, distilled from a much-diluted drop of the nectar of a sun orchid flower, can transform an alchemist’s mutagen into a potent healing tonic.', 'a much-diluted drop of sun orchid nectar worth 500 gp', NULL, false, true),
  ('order_s_wrath', 'Order’s Wrath', 'evocation', NULL, 'lawful', 4, 'divine', 'cleric/oracle 4, inquisitor 4; Domain law 4; Mystery godclaw 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'non-lawful creatures within a burst that fills a 30-ft. cube', NULL, 'instantaneous (1 round); see text', 'Will partial; see text', 'yes', 'You channel lawful power to smite enemies. The power takes the form of a three-dimensional grid of energy. Only chaotic and neutral (not lawful) creatures are harmed by the spell.', NULL, NULL, false, false),
  ('out_of_sight', 'Out of Sight', 'enchantment', NULL, 'mind-affecting', 3, 'arcane', 'medium 3, mesmerist 3, psychic 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D); see text', 'Will negates; see text', 'yes; see text', 'The spell inhibits the memories of creatures that perceive you. While creatures can perceive you normally, when a creature stops observing you, it must attempt a Will save (spell resistance applies). If it fails, it loses all memory of its awareness of you and your actions while you were under the effects of this spell. The spell’s duration listed above measures how long the out of sight effect lasts on you, but the memory alteration is instantaneous and can be reversed only by magic such as modify memory.', 'a strip of black cloth', NULL, false, false),
  ('outbreak', 'Outbreak', 'necromancy', NULL, NULL, 2, 'divine', 'antipaladin 2, arcanist 3, bloodrager 3, cleric/oracle 2, druid 2, hunter 2, sorcerer/wizard 3, warpriest 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '20-ft. burst', NULL, 'instantaneous', 'Fortitude partial', 'yes', 'You cause any diseased creatures in the area to become extremely contagious. Any affected creature is overcome by a fit of wracking coughs, causing it to become fatigued and exposing any creatures within 10 feet of the diseased creature to the diseases it carries. On a successful save, a creature is fatigued for 1 round and doesn’t have a chance to infect nearby creatures.', NULL, NULL, false, false),
  ('overland_flight', 'Overland Flight', 'transmutation', NULL, NULL, 4, 'divine', 'alchemist 5, magus 5, shaman 5, sorcerer/wizard 5, summoner 4, unchained summoner 5, witch 5; Domain void 5; Subdomain trade 5; Bloodline arcane 5, djinni 5; Elemental School air 5; Mystery heavens 5', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level', NULL, NULL, 'This spell functions like a fly spell, except you can fly at a speed of 40 feet (30 feet if wearing medium or heavy armor, or if carrying a medium or heavy load) with a bonus on Fly skill checks equal to half your caster level. When using this spell for long-distance movement, you can hustle without taking nonlethal damage (a forced march still requires Constitution checks). This means you can cover 64 miles in an 8-hour period of flight (or 48 miles at a speed of 30 feet).', NULL, NULL, false, false),
  ('overlook', 'Overlook', 'enchantment', 'compulsion', 'mind-affecting', 3, 'arcane', 'bard 3, mesmerist 3, psychic 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'You enhance your natural ability to seem small and unimportant, causing those around you to overlook you. You gain a +20 bonus on Stealth checks, which doesn’t stack with bonuses from effects that actually make you sneakier, such as invisibility or respectful quiet (see below); you do not need cover or concealment to hide; and you can hide while you are being observed. If a creature fails to notice you because of this spell, that creature can still remember seeing a halfling pass by, but attach no importance to the memory. You do not gain these benefits against creatures that are immune to compulsions or mind-affecting effects, and spell resistance applies. If you take an actively aggressive or extremely conspicuous action, creatures automatically notice you, and you gain no further benefits against those creatures for the remainder of the spell’s duration.', NULL, NULL, false, false),
  ('overstimulate', 'Overstimulate', 'transmutation', NULL, NULL, 2, 'divine', 'alchemist 2, bard 2, bloodrager 2, cleric 2, druid 2, psychic 2, ranger 2, shaman 2, summoner 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Fort negates (harmless)', 'yes (harmless)', 'You deprive a creature of the blissful oblivion of unconsciousness, either to keep it going despite grievous injuries or to prolong its suffering. For the duration of the spell, the target gains the ferocity ability, allowing it to remain conscious and continue fighting even if its hit point total is below 0. The target is still staggered and loses 1 hit point each round, and the target still dies when its hit point total reaches a negative amount equal to its Constitution score.', 'smelling salts', NULL, true, false),
  ('overwhelming_grief', 'Overwhelming Grief', 'enchantment', 'compulsion', 'emotion, mind-affecting', 3, 'arcane', 'bard 3, sorcerer/wizard 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will negates (see text)', 'yes', 'You cause a single opponent to become profoundly stricken with intense grief. He can take no actions, takes a –2 penalty to Armor Class, and loses his Dexterity bonus (if any). He can attempt a new save each round to break the spell’s effect.', NULL, NULL, false, false),
  ('overwhelming_poison', 'Overwhelming Poison', 'necromancy', NULL, 'poison', 4, 'divine', 'antipaladin 4, cleric 6, druid 6, ranger 4, shaman 6, witch 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature or one dose of poison; see text', NULL, NULL, '10 minutes/level', 'none', 'no', 'This spell increases the virulence of the targeted dose of poison, making the poison more difficult to resist. The poison is unaffected by delay poison, and the DC to remove it with neutralize poison is increased by 5. Additionally, the poison uses its own saving throw DC or overwhelming poison’s DC, whichever is higher.', 'an adder’s fang', NULL, false, false),
  ('overwhelming_presence', 'Overwhelming Presence', 'enchantment', 'compulsion', 'emotion, mind-affecting', 6, 'divine', 'bard 6, cleric/oracle 9, inquisitor 6, sorcerer/wizard 9; Domain [subdomain] Nobility [aristocracy, hubris] 9; Bloodline imperious 9; Mystery dragon 9, intrigue 9', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 round/level', 'Will negates, see text', 'yes', 'Your presence inspires incredible awe in those nearby. A creature that fails a save against this spell falls to the ground and prostrates itself before you, believing it bows before a divine presence. A flying creature incapable of hovering must land immediately in order to prostrate itself. These creatures are considered to be helpless for the duration of the spell. Each round on its turn, a target of this spell may attempt a new saving throw to end the effect; this is a full-round action that does not provoke attacks of opportunity. A creature that recovers from this spell early after being affected by it for at least 1 round takes 1d6 points of Wisdom drain and is staggered for 1d4 rounds. A creature that makes the initial save to resist this spell is merely staggered for 1 round.', 'a swan feather', NULL, false, false),
  ('owl_s_wisdom', 'Owl’s Wisdom', 'transmutation', NULL, NULL, 2, 'divine', 'alchemist 2, cleric/oracle 2, druid 2, medium 2, paladin 2, psychic 2, ranger 2, shaman 2, sorcerer/wizard 2, summoner/unchained summoner 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 min./level', 'Will negates (harmless)', 'yes', 'The transmuted creature becomes wiser. The spell grants a +4 enhancement bonus to Wisdom, adding the usual benefit to Wisdom-related skills. Clerics, druids, and rangers (and other Wisdom-based spellcasters) who receive owl’s wisdom do not gain any additional bonus spells for the increased Wisdom, but the save DCs for their spells increase.', 'feathers or droppings from an owl', NULL, true, false),
  ('pack_empathy', 'Pack Empathy', 'divination', NULL, NULL, 2, 'divine', 'bloodrager 3, druid 3, inquisitor 3, medium 2, ranger 2, sorcerer/wizard 3, spiritualist 3, summoner 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'you plus one willing living creature per 3 levels, no two of which can be more than 30 ft. apart', NULL, NULL, '1 hour/level (D)', 'none', 'no', 'You create an instinctual connection between the targets. Each can sense the others’ overall emotional states, which allows them to communicate basic emotional concepts (such as alerting each other of danger due to increased stress). Once the spell has been cast on the subjects, the distance between them and the caster doesn’t affect the spell as long as they are on the same plane of existence. If a subject leaves the plane, or if it dies, the spell ceases to function for it.', NULL, NULL, false, false),
  ('page_bound_epiphany', 'Page-Bound Epiphany', 'divination', NULL, NULL, 2, 'divine', 'bard 2, cleric 2, magus 2, sorcerer/wizard 2', '1 round', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You magically scour the world’s libraries for information that might refresh your memory about a topic. Upon casting this spell, the focus book’s pages fill with snippets and selections from countless books. You can spend up to 1 round per caster level (maximum 10) reading these notes. You may cease reading at any time, and when you do you can immediately attempt one Knowledge check with a +1 circumstance bonus for each round you spent studying the book (maximum +10). The writing disappears when the spell ends, and if you fail to succeed at a Knowledge check on the round you stop reading the notes, you don’t gain the benefits of this spell.', NULL, 'a book with blank pages', false, false),
  ('pain_strike', 'Pain Strike', 'evocation', NULL, 'evil, pain', 2, 'arcane', 'bloodrager 3, psychic 2, sorcerer/wizard 3, witch 3; Subdomain torture 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level (D)', 'Fortitude negates', 'yes', 'Pain strike racks the targeted creature with agony, inflicting 1d6 points of nonlethal damage per round for 1 round per level (maximum 10 rounds). Additionally, the affected creature is sickened for the spell’s duration, and the caster gains a +4 circumstance bonus on Intimidate checks against the target.', NULL, NULL, false, false),
  ('painful_revelation', 'Painful Revelation', 'abjuration', NULL, 'mind-affecting, pain', 2, 'divine', 'antipaladin 2, bard 2, mesmerist 2, psychic 2, sorcerer/wizard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one ongoing illusion effect', NULL, NULL, '1 hour/level or until discharged', 'Will partial', 'no', 'You augment an ongoing illusion effect to strike out painfully at creatures that see through it. When a creature successfully disbelieves an illusion that is the target of painful revelation, it takes 1d6 points of nonlethal damage for every 2 caster levels you have (maximum 10d6) and is staggered for 1d4 rounds. A successful Will save reduces the nonlethal damage by half and negates the staggered effect. Once painful revelation has been triggered, the spell ends.', NULL, NULL, false, false),
  ('paladin_s_sacrifice', 'Paladin’s Sacrifice', 'abjuration', NULL, NULL, 2, 'divine', 'paladin 2', '1 immediate action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous', 'Fortitude negates (harmless)', 'yes (harmless)', 'You open up a brief but powerful divine conduit between you and another creature, taking on the damage and any other effects that creature suffers. When a creature in range is hit by an attack or fails a saving throw, you can cast this spell and the wounds and/or effects are magically transmitted to you instead of the target. You are affected as if you were hit by the attack or failed the saving throw, taking all the damage and suffering all of the adverse effects. Any resistances or immunities you have are applied normally, but you cannot otherwise reduce or negate the damage or effects in any way.', NULL, NULL, true, false),
  ('pale_flame', 'Pale Flame', 'evocation', NULL, 'fire', 2, 'divine', 'druid 2, hunter 2, shaman 2', '1 standard action', '0 ft.', NULL, NULL, 'flame in your palm', '1 minute/level (D)', 'none', 'yes', 'This spell functions as per produce flame, except that the flames never glow brighter than dim light, including any fires started by this spell. These flames cast light only half the distance of a torch and cannot be seen from more than 100 feet away. The flames deal 2d6 points of fire damage + 1 point per caster level (maximum +5). Against plants, this damage increases to 2d6 points + 2 points per caster level (maximum +10).', 'caphorite shard', NULL, false, false),
  ('paragon_surge', 'Paragon Surge', 'transmutation', 'polymorph', NULL, 3, 'divine', 'alchemist 3, arcanist 3, bloodrager 3, cleric 3, crimson assassin 3, investigator 3, magus 4, medium 3, oracle 3, paladin 4, sorcerer/wizard 3, warpriest 3, witch 3; Domain [subdomain] Liberation/Strength [self-realization]', '1 standard action', 'personal (half-elf only)', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'You surge with ancestral power, temporarily embodying all the strengths of both elvenkind and humankind simultaneously, and transforming into a paragon of both races, something greater than elf or human alone. Unlike with most polymorph effects, your basic form does not change, so you keep all extraordinary and supernatural abilities of your half-elven form as well as all of your gear.', NULL, NULL, false, false),
  ('paranoia', 'Paranoia', 'illusion )', 'phantasm', 'mind-affecting', 1, 'arcane', 'bard 2, medium 1, mesmerist 1, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level (D)', 'Will negates', 'yes', 'The target believes everyone it sees is an enemy. The target becomes hostile to all creatures, treating all creatures as enemies and only itself as an ally. The target must attempt attacks of opportunity whenever any creature provokes them. Finally, whenever the target is adjacent to two or more creatures, its paranoia overwhelms it, and it takes a –2 penalty on attack rolls, weapon damage rolls, ability checks, skill checks, and saving throws.', NULL, NULL, false, false),
  ('parasitic_soul', 'Parasitic Soul', 'necromancy', NULL, 'death, evil', 9, 'divine', 'cleric 9, psychic 9, shaman 9, sorcerer/wizard 9, witch 9', '1 standard action Duration permanent (D) Saving Throw Will negates; Spell Resistance yes', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like magic jar except as noted above, and instead of your own soul, you can transfer a trapped soul (such as one trapped in a soul gem or trapped with soul bind or trap the soul) from the receptacle into an unwilling target’s body. If the target creature fails its saving throw, it dies and the trapped soul in the receptacle permanently inhabits the body as if using magic jar. The trapped soul does not get a saving throw to resist this transfer. To dismiss the spell, you must be within range of the possessed body.', NULL, NULL, false, false),
  ('parchment_swarm', 'Parchment Swarm', 'transmutation', NULL, NULL, 4, 'arcane', 'magus 5, occultist 4, sorcerer/wizard 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'Reflex half; see text', 'yes', 'When you cast this spell, you quickly tear a parchment into shreds, releasing the flying fragments to swarm around a target creature and deliver thousands of tiny paper cuts.', 'blank parchment or magic scroll; see text', NULL, false, false),
  ('particulate_form', 'Particulate Form', 'transmutation', NULL, NULL, 5, 'divine', 'cleric 7, occultist 5, psychic 7, sorcerer/wizard 7, witch 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level (D)', 'none (harmless)', 'no', 'The targets’ physical forms undergo a bizarre transformation. They look and function normally, but are composed of countless particles that separate and reconnect to remain whole. Each target gains fast healing 1 and is immune to bleed damage, critical hits, sneak attacks, and other forms of precision damage. The value of this fast healing increases by 1 at caster levels 10th, 15th, and 20th. Any target can end the spell effect on itself as a swift action; the target then regains 5d6 hit points and can attempt an additional saving throw against any one disease or poison affecting it (at the original save DC), ending that disease or poison with a successful saving throw.', 'a pinch of fine sand', NULL, false, false),
  ('pass_without_trace', 'Pass without Trace', 'transmutation', NULL, NULL, 1, 'divine', 'druid 1, ranger 1, shaman 1', '1 standard action', 'touch', NULL, NULL, NULL, '1 hour/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'The subject or subjects of this spell do not leave footprints or a scent trail while moving. Tracking the subjects is impossible by non-magical means.', NULL, NULL, true, false),
  ('passing_fancy', 'Passing Fancy', 'enchantment', 'compulsion', 'mind-affecting', 2, 'arcane', 'bard 2, mesmerist 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, '4d4 rounds (D)', 'Will negates', 'yes', 'When you cast this spell, you dictate one specific topic or recent event and instill a magical obsession with that subject within the target. An affected creature becomes fascinated by the topic, and becomes completely focused on discussing the event with anyone nearby, possibly wandering off or distracting unaffected creatures.', NULL, NULL, false, false),
  ('passwall', 'Passwall', 'transmutation', NULL, NULL, 5, 'arcane', 'sorcerer/wizard 5; Elemental School earth 5', '1 standard action', 'touch', NULL, NULL, NULL, '1 hour/level (D)', 'none', 'no', 'You create a passage through wooden, plaster, or stone walls, but not through metal or other harder materials. The passage is 10 feet deep plus an additional 5 feet deep per three caster levels above 9th (15 feet at 12th, 20 feet at 15th, and a maximum of 25 feet deep at 18th level). If the wall’s thickness is more than the depth of the passage created, then a single passwall simply makes a niche or short tunnel. Several passwall spells can then form a continuing passage to breach very thick walls. When passwall ends, creatures within the passage are ejected out the nearest exit. If someone dispels the passwall or you dismiss it, creatures in the passage are ejected out the far exit, if there is one, or out the sole exit if there is only one.', 'sesame seeds', NULL, false, false),
  ('path_of_glory', 'Path of Glory', 'conjuration', 'healing', NULL, 2, 'divine', 'bard 2, cleric 2', '1 standard action', 'touch (see text)', NULL, 'four 5-ft. squares/level (see text)', NULL, '1 round/level', 'none', 'no', 'You cause four 5-foot squares (one of which must be your space) to glow with dim illumination. Starting on your next turn, as a swift action you can extend the glowing area by an additional four 5-foot squares; each new square must be adjacent to a square that was previously glowing. Allies that end their turns on a glowing square (including one who falls unconscious in the square) are healed of 1 point of damage.', NULL, NULL, false, false),
  ('path_of_the_winds', 'Path of the Winds', 'evocation', NULL, 'air', 6, 'divine', 'druid 6, sorcerer/wizard 6', '1 standard action', '100 ft.', NULL, NULL, '40-ft.-high downdraft of wind in a 100-foot line', 'concentration + 1 round', 'Fort negates', 'yes', 'With a sweeping gesture, you call forth mighty winds to clear a path ahead of you. The winds are the equivalent of a windstorm. During the first round of the spell, the winds sweep the designated area clear of anything of Small or smaller size, blowing it outward to the sides of the spell’s effect (50% chance of landing on either side). You may move within the effect without penalty, though all other creatures are subject to the wind’s effects. On the second and all later rounds of the spell, the edges of the effect are treated as a wind wall. If the effect includes a body of water or other liquid, the winds create a channel up to 40 feet deep into the surface of the liquid. On your turn as a move action, you can move the effect of this spell, either rotating it at one of its ends up to 45 degrees, or moving it up to 50 feet in line with its current orientation (toward you or away from you).', NULL, NULL, false, false),
  ('pattern_recognition', 'Pattern Recognition', 'transmutation', NULL, NULL, 1, 'arcane', 'sorcerer/wizard 1', '1 standard action', 'personal', 'you', NULL, NULL, '10 min./level', NULL, NULL, 'Pattern recognition allows you to notice unusual breaks in the patterns of stones in a wall, boards in a ﬂoor, cracks in glass, trees in a forest, or similar interruptions. You gain an insight bonus equal to one-half your caster level (minimum +1, maximum +10) on Perception checks.', NULL, NULL, false, false),
  ('peace_bond', 'Peace Bond', 'abjuration', NULL, NULL, 1, 'divine', 'bard 1, cleric 1, druid 1, inquisitor 1, paladin 1, shaman 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, 'one or more 5-ft. cubes, no two of which can be more than 30 ft. apart', NULL, '1 minute/level', 'none', 'no', 'This spell creates one glowing rune of peace, plus one per 2 caster levels above 1st (to a maximum of five runes at 9th level). An identical symbol appears on your forehead for the duration of the spell and cannot be disguised (though it is visible only if you are visible). Each rune illuminates a 5-foot cube, preventing any spell you cast of up to 3rd level and that has a defined area (as opposed to targets or an effect) from entering or affecting the 5-foot cube. For example, creatures and items within any square affected by peace bond take no damage from a fireball you cast. However, if you cast stinking cloud, the noxious vapors are an effect and enter such cubes normally. This spell does not break line of effect within any other spells you cast; it simply negates all effects of your 1st-, 2nd- and 3rd-level area spells within the peace bond’s area.', 'a glass cube', NULL, true, false),
  ('peacebond', 'Peacebond', 'abjuration', NULL, NULL, 1, 'divine', 'inquisitor 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one sheathed or slung weapon', NULL, NULL, '1 minute/level', 'Will negates (object)', 'yes (object)', 'You lock a weapon in place on its owner’s body, or within the weapon’s sheath or holster. Anyone who then tries to draw the weapon must spend a standard action and succeed at a Strength check (DC equal to the saving throw DC) to do so, provoking attacks of opportunity whether the attempt succeeds or fails.', NULL, NULL, false, false),
  ('peacemaker_s_parley', 'Peacemaker’s Parley', 'enchantment', 'charm', 'language-dependent, mind- affecting', 9, 'arcane', 'cleric/oracle 2 (Grundinnar)', '1 swift action', 'close (25 ft. + 5 ft./2 levels)', NULL, 'creatures in a 20-ft.-radius spread', NULL, 'instantaneous', 'Will negates', 'yes', 'You can attempt to influence unfriendly or hostile creatures, altering their attitudes toward you. After casting, make a Diplomacy check against the creatures as a free action; you gain a +2 sacred bonus on this check against creatures that failed their saves against the spell. Even if you favorably manipulate the attitude of the affected targets, they quickly revert to their previous attitude if threatened or treated poorly.', NULL, NULL, false, false),
  ('peerless_integrity', 'Peerless Integrity', 'illusion', 'glamer', NULL, 2, 'divine', 'antipaladin 2, bard 2, mesmerist 2, psychic 2, sorcerer/wizard 2', '1 standard action', 'personal', NULL, '10-ft.-radius emanation centered on you', NULL, '10 minutes/level', 'none or Will negates; see text', 'none', 'Peerless integrity conceals the alignment of creatures from divination magic. All creatures within the spell’s area, including you, appear to have lawful good auras for the purposes of divination spells and effects that reveal alignments (such as detect law and see alignment), instead of their actual alignments. If the caster of such divination magic succeeds at a Will save, the caster recognizes whether the readings are true or false. Any creature under the effects of this spell gains a +2 circumstance modifier on Bluff and Diplomacy checks.', NULL, NULL, true, false),
  ('pellet_blast', 'Pellet Blast', 'conjuration', 'creation', NULL, 3, 'arcane', 'bloodrager 4, magus 4, psychic 3, sorcerer/wizard 3, summoner/unchained summoner 3', '1 standard action', '30 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous', 'Reflex half', 'no', 'This spell creates an explosion of conjured metal pellets, striking everything within its area and dealing 1d8 points of piercing damage per two caster levels, maximum 5d8. This damage is subject to damage reduction. If the material component is made of cold iron (costing 50 gp), silver (costing 20 gp), or adamantine (costing 100 gp), the resulting blast can overcome damage reduction of the appropriate type. The pellets disappear after the spell is cast and the damage is dealt.', 'a handful of metal pellets or handful of cold iron, silver, or adamantine pellets; see descriptions for cost', NULL, false, false),
  ('penumbral_disguise', 'Penumbral Disguise', 'conjuration', NULL, 'shadow', 3, 'divine', 'alchemist 3, bard 3, inquisitor 3, mesmerist 3, occultist 3, sorcerer/wizard 3, witch 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level (D)', 'none', 'no', 'You mask your features with shadowy illumination, gaining a competence bonus equal to your caster level on Disguise checks and Stealth checks attempted while in normal light, dim light, or darkness. In addition, creatures that see you while you are in dim light or darkness are unable to discern any but the most general information about your appearance or actions. For example, they can determine your general shape (such as humanoid), as well as the gist of your actions (such as, “She was trying to break into the store”), but cannot determine your precise actions, your appearance, or any identifying information about you. In bright light, your normal appearance is revealed.', NULL, NULL, false, false),
  ('perceive_betrayal', 'Perceive Betrayal', 'divination', NULL, NULL, 4, 'divine', 'cleric 6, inquisitor 4, sorcerer/wizard 7, witch 6', '1 minute', 'personal', 'you', NULL, NULL, '1 hour/level', NULL, NULL, 'By donning a silver circlet anointed with blood, you gain the ability to sense traitorous intent toward a single person to whom you defer, designated when you cast the spell. The spell alerts you when a creature with traitorous intent is within 200 feet, although it doesn’t identify the source. By concentrating, you can learn the strength of the greatest threat, based on the following categories.', '12 drops of blood', 'a silver circlet worth 500 gp', false, true),
  ('perceive_cues', 'Perceive Cues', 'transmutation', NULL, NULL, 2, 'divine', 'alchemist 2, inquisitor 2, mesmerist 2, occultist 2, psychic 2, ranger 2, witch 2', '1 standard action', 'personal', NULL, NULL, NULL, '10 minutes/level', NULL, NULL, 'Your senses become preternaturally keen, and you gain insight into subtle behavioral cues. For the duration of the spell, you receive a +5 competence bonus on Perception and Sense Motive checks.', 'a drop of water', NULL, false, false),
  ('perfect_placement', 'Perfect Placement', 'divination', NULL, NULL, 2, 'arcane', 'bard 2, bloodrager 2, magus 3, psychic 3, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. plus 5 ft./2 levels)', 'one creature/level, no two of which can be more than 30 ft. apart', NULL, NULL, '1 round/level', 'Will negates (harmless)', 'yes (harmless)', 'Affected creatures gain tactical knowledge and maximize their efficiency on the field of battle. Each gains a +1 insight bonus to AC and Reflex saves. Against attacks of opportunity, the insight bonus to AC increases to +3.', 'a chess piece', NULL, false, false),
  ('permanency', 'Permanency', 'universal', NULL, NULL, 5, 'arcane', 'sorcerer/wizard 5; Domain [subdomain] Magic [rites] 5; Bloodline astral 5; Mystery time 5', '2 rounds', 'see text', 'see text', NULL, NULL, 'permanent; see text', 'none', 'no', 'This spell makes the duration of certain other spells permanent. You first cast the desired spell and then follow it with the permanency spell.', 'see tables below', NULL, false, false),
  ('permanent_hallucination', 'Permanent Hallucination', 'illusion', 'phantasm', 'mind-affecting', 7, 'arcane', 'psychic 7, sorcerer/wizard 7', NULL, NULL, 'one creature', NULL, NULL, 'permanent (D)', NULL, NULL, 'This spell functions as audiovisual hallucination, except that the phantasm you create includes visual, auditory, olfactory, tactile, and thermal components, and the phantasm follows a complex script. The phantasm follows that script without your having to concentrate on it and can react to stimuli the target perceives, as appropriate for the script. Unlike most illusions with a save to disbelieve, if the target disbelieves a permanent hallucination, she can choose to end the effect entirely at any time.', NULL, NULL, false, false),
  ('permanent_image', 'Permanent Image', 'illusion', 'figment', NULL, 6, 'arcane', 'bard 6, sorcerer/wizard 6', NULL, NULL, NULL, NULL, 'figment that cannot extend beyond a 20-ft. cube + one 10-ft. cube/level (S)', 'permanent (D)', NULL, NULL, 'This spell functions like silent image, except that the figment includes visual, auditory, olfactory, and thermal elements, and the spell is permanent. By concentrating, you can move the image within the limits of the range, but it is static while you are not concentrating.', NULL, NULL, false, false),
  ('pernicious_poison', 'Pernicious Poison', 'necromancy', NULL, 'poison', 2, 'divine', 'antipaladin 2, druid 2, sorcerer/wizard 2, witch 2; Subdomain venom 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minute/level', 'none', 'yes', 'You weaken the target’s defenses against poison. The target gains a –4 penalty on saves against poison, and poisons affecting the target continue for another 2 frequency increments (for example, black adder venom lasts 8 rounds instead of 6, and arsenic lasts for 6 minutes instead of 4). Attempts to cure the poisoned target with skill or magic take a –4 penalty.', NULL, NULL, true, false),
  ('pernicious_pranksters', 'Pernicious Pranksters', 'conjuration', 'summoning', NULL, 3, 'divine', 'bard 3, druid 5, occultist 3, shaman 5, sorcerer/wizard 5, witch 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'fey pranksters', '1 round/level (D)', 'none', 'no', 'You summon intangible forces of whimsy to perform a variety of tricks and pranks upon your foes. Each round on your turn (including the round you cast this spell), these incorporeal pranksters perform a single dirty trick, disarm, steal, or trip combat maneuver against one of your foes within the spell’s range. The whimsical forces have a bonus on combat maneuver checks equal to your caster level + your primary spellcasting ability score modifier (Intelligence for wizards, Charisma for sorcerers, etc.). Unless the target of the combat maneuver can see invisible creatures or forces, the spell gains an additional +4 bonus on combat maneuver checks.', 'three drops of honey rolled in a sycamore leaf', NULL, false, false),
  ('persistent_image', 'Persistent Image', 'illusion', 'figment', NULL, 5, 'arcane', 'bard 5, sorcerer/wizard 5; Bloodline efreeti 5', NULL, NULL, NULL, NULL, NULL, '1 min./level (D)', NULL, NULL, 'This spell functions like silent image, except that the figment includes visual, auditory, olfactory, and thermal components, and the figment follows a script determined by you. The figment follows that script without your having to concentrate on it. The illusion can include intelligible speech if you wish.', NULL, NULL, false, false),
  ('persistent_vigor', 'Persistent Vigor', 'transmutation', NULL, NULL, 4, 'divine', 'alchemist 4, cleric 4, inquisitor 4, shaman 4, witch 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', NULL, NULL, 'You are filled with a persistent vigor. You gain fast healing 2 and are immune to bleed effects as well as the sickened and nauseated conditions. When you succeed at a saving throw against a disease or poison effect, that disease or poison effect ends (as if you had succeeded at enough saving throws to cure that effect).', 'ginseng root shavings', NULL, true, false),
  ('persuasive_goad', 'Persuasive Goad', 'necromancy', NULL, 'pain', 1, 'divine', 'inquisitor 1', '1 standard action component V, S', 'close (25 ft. +5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous and 1 minute', 'Fortitude negates', 'yes', 'Your eyes flash and the target takes 1d6 points of nonlethal damage. For the next minute, you gain a +4 circumstance bonus on Intimidate checks against the target.', NULL, NULL, false, false),
  ('pessimism', 'Pessimism', 'enchantment', 'compulsion', 'emotion, mind-affecting', 4, 'arcane', 'bard 4, medium 4, mesmerist 4, psychic 5, sorcerer/wizard 5, witch 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 hour/level', 'Will negates', 'yes', 'You erode the target’s confidence and instill a sense of despair.', 'a shard of a broken mirror', NULL, true, false),
  ('phantasmal_affliction', 'Phantasmal Affliction', 'illusion', 'phantasm', 'mind-affecting', 2, 'arcane', 'mesmerist 2, psychic 3, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'living creature', NULL, NULL, 'see text', 'Will disbelief, then Fortitude or Will negates (see text)', 'yes', 'You cause the creature to believe she has a debilitating affliction.', 'a drop of cod liver oil', NULL, false, false),
  ('phantasmal_asphyxiation', 'Phantasmal Asphyxiation', 'illusion )', 'phantasm', 'mind-affecting', 3, 'arcane', 'medium 3, mesmerist 4, psychic 4, sorcerer/wizard 4, spiritualist 4, witch 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one living creature', NULL, NULL, '1 round/level (D)', 'Will disbelief, then Fortitude partial (see text)', 'yes', 'Your target must succeed at a Will save or believe it can no longer breathe. An affected target must attempt a Fortitude save each round at the beginning of its turn. The first time it fails the Fortitude save, it is staggered until the next time it attempts a save against the spell. If the target fails a second Fortitude save in a row, it falls unconscious for the spell’s remaining duration. The target breathes normally while unconscious, but is shaken for 1 minute upon awakening. If the target succeeds at two Fortitude saves in a row, it shakes off the spell’s effects entirely. Otherwise, the target continues to attempt a save each round until it falls unconscious or the spell ends. This spell has no effect on creatures that don’t need to breathe.', 'an empty vial', NULL, false, false),
  ('phantasmal_killer', 'Phantasmal Killer', 'illusion', 'phantasm', 'emotion, fear, mind-affecting', 4, 'arcane', 'bloodrager 4, magus 4, sorcerer/wizard 4, witch 4; Domain madness 6; Subdomain nightmare 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one living creature', NULL, NULL, 'instantaneous', 'Will disbelief, then Fortitude partial; see text', 'yes', 'You create a phantasmal image of the most fearsome creature imaginable to the subject simply by forming the fears of the subject’s subconscious mind into something that its conscious mind can visualize: this most horrible beast. Only the spell’s subject can see the phantasmal killer. You see only a vague shape. The target first gets a Will save to recognize the image as unreal. If that save fails, the phantasm touches the subject, and the subject must succeed on a Fortitude save or die from fear. Even if the Fortitude save is successful, the subject takes 3d6 points of damage.', NULL, NULL, false, false),
  ('phantasmal_putrefaction', 'Phantasmal Putrefaction', 'illusion )', 'phantasm', 'fear, mind-affecting', 4, 'arcane', 'medium 4, mesmerist 5, sorcerer/wizard 6, witch 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature/level, no two of which can be more than 30 ft. apart', NULL, NULL, '1 round/level (D)', 'Will disbelief, then Fortitude partial (see text)', 'yes', 'You implant within the minds of your targets the illusion that their skin is rotting away, large rents are appearing all over their bodies, and their internal organs are spilling out into a putrid halfliquid mass at their feet. Those who fail to disbelieve phantasmal putrefaction immediately take 1d4 points of Wisdom damage.', NULL, NULL, false, false),
  ('phantasmal_reminder', 'Phantasmal Reminder', 'illusion )', 'phantasm', 'mind-affecting', 3, 'divine', 'antipaladin 3, bard 4, mesmerist 3, psychic 3, shaman 4, sorcerer/wizard 3, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one living creature', NULL, NULL, '1 round (see text)', 'Will disbelief, then Fortitude partial; see text', 'yes', 'You create a memory loop of a successful attack made against the target, forcing its conscious mind to recall the details of the attack in such excruciating detail that its physical body is racked by the recollection. This spell can affect only a creature that has taken damage since the end of your last turn. The target first can attempt a Will save to recognize the attack as unreal. If it fails that saving throw, the target must succeed at a Fortitude save or take an amount of damage equal to 1d6 per caster level (maximum 10d6). Because the damage is a quasi-real memory of existing wounds, this damage can’t be reduced or prevented (such as by the shield other spell).', NULL, NULL, false, false),
  ('phantasmal_revenge', 'Phantasmal Revenge', 'illusion', 'phantasm', 'emotion, fear, mind-affecting', 7, 'arcane', 'sorcerer/wizard 7', '1 standard action', 'touch and unlimited; see text', NULL, NULL, NULL, 'instantaneous', 'Will disbelief then Fortitude partial; see text', 'yes', 'When you cast this eerie spell upon a recently slain creature, you cause a ghastly, spectral image of it to rise up from its corpse, shrieking for vengeance before it vanishes in a burst of unnatural light. This phantom then unerringly seeks out the creature that killed it, as long as that creature is on the same plane, and tries to slay its killer in turn.', NULL, NULL, false, false),
  ('phantasmal_web', 'Phantasmal Web', 'illusion', 'phantasm', 'mind-affecting', 5, 'arcane', 'bard 5, sorcerer/wizard 5; Subdomain insanity 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 round/level (D)', 'Will disbelief, then Fortitude partial; see text', 'yes', 'You implant within the minds of your targets the illusion that they are engulfed in tangled webs teeming with swarms of tiny spiders. Those who fail to disbelieve the phantasmal web are treated as if in a web spell, but must also make a Fortitude save at the beginning of each turn or become nauseated for that round by the phantasmal spiders.', NULL, NULL, false, false),
  ('phantom_blood', 'Phantom Blood', 'necromancy', NULL, NULL, 1, 'arcane', 'alchemist 1, bloodrager 1, magus 1, sorcerer/wizard 1', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level', NULL, NULL, 'You bolster your life energy. If the loss of hit points at the end of a temporary effect that modifies your Constitution (such as barbarian’s rage or bloodrager‘s bloodrage) would cause you to become unconscious or kill you, you gain temporary hit points equal to your caster level (maximum 10). Each casting of this spell grants you temporary hit points only once.', NULL, NULL, false, false),
  ('phantom_chariot', 'Phantom Chariot', 'conjuration', 'creation', NULL, 3, 'arcane', 'sorcerer/wizard 4, summoner 3', '10 minutes', '0 ft.', NULL, NULL, 'one quasi-real chariot and draft team', '1 hour/level (D)', 'none', 'no', 'You conjure a quasi-real heavy chariot with four horselike creatures in a team to pull it. (The exact description can be customized as you wish.) The chariot has all the normal qualities of a heavy chariot. You or a person you designate while casting the spell must drive the chariot, which can carry up to six passengers (including the driver). The team and chariot make no sound and the team does not fight, although the driver can use the chariot like any normal chariot. The chariot and team are essentially a single entity with an AC of 19 (–2 size, +6 natural armor, +5 Dex), and 10 hit points + 2 hit points per caster level (maximum 50). If the entity loses all its hit points, it disappears, possibly subjecting all aboard to a crash (treat as wrecked). The entity gains certain powers according to caster level, just like a mount does in the phantom steed spell.', NULL, NULL, false, false),
  ('phantom_driver', 'Phantom Driver', 'conjuration', 'creation', NULL, 3, 'arcane', 'bard 3, sorcerer/wizard 3', '10 minutes', '10 ft.', NULL, NULL, 'one quasi-real, humanlike creature', '1 hour/level (D)', 'none', 'no', 'You conjure a Small or Medium, quasi-real, humanlike creature (the exact physical features can be customized as you wish). This creation can drive any vehicle you command it to. This phantom creature does not fight, and while animals that power a muscle-propelled vehicle driven by the creature do respond to its commands, animals otherwise shun the creature and refuse to attack it.', NULL, NULL, false, false),
  ('phantom_hunt', 'Phantom Hunt', 'transmutation', NULL, NULL, 4, 'divine', 'druid 4, ranger 4', '1 standard action', 'personal (see text)', 'you and one animal companion within 30 ft.', NULL, NULL, '1 hour/level (D)', NULL, NULL, 'You affect yourself and a single animal companion within 30 feet of you. Both you and the animal companion gain darkvision to 100 feet, tremorsense to 20 feet, and a 40-foot enhancement bonus to movement. Furthermore, you can track while moving at full speed without taking any penalty. If you already have the ability to track at full speed, you gain a +4 bonus on Survival checks while tracking instead.', NULL, NULL, true, false),
  ('phantom_limb', 'Phantom Limb', 'necromancy', NULL, NULL, 5, 'arcane', 'psychic 6, spiritualist 5', '1 standard action', 'touch', 'one creature', NULL, NULL, '24 hours; see text', 'none', 'yes', 'This spell creates a semi-visible psychic manifestation that allows a creature to replace a missing body part or parts. This could be as simple as a missing finger or toe or as complex as one or more limbs or even a set of wings. The creature can use these ghostly appendages exactly as if they were the creature’s own limbs, including any natural attacks or other special abilities. This includes any extraordinary abilities granted by the appendages, but not supernatural ones.', NULL, NULL, false, false),
  ('phantom_steed', 'Phantom Steed', 'conjuration', 'creation', NULL, 2, 'arcane', 'bard 3, bloodrager 3, magus 3, sorcerer/wizard 3, summoner/unchained summoner 2', '10 minutes', '0 ft.', NULL, NULL, 'one quasi-real, horse-like creature', '1 hour/level (D)', 'none', 'no', 'You conjure a Large, quasi-real, horse-like creature (the exact coloration can be customized as you wish). It can be ridden only by you or by the one person for whom you specifically created the mount. A phantom steed has a black head and body, gray mane and tail, and smoke-colored, insubstantial hooves that make no sound. It has what seems to be a saddle, bit, and bridle. It does not fight, but animals shun it and refuse to attack it.', NULL, NULL, false, false),
  ('phantom_trap', 'Phantom Trap', 'illusion', 'glamer', NULL, 2, 'arcane', 'mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 2, spiritualist 2', '1 standard action', 'touch', 'object touched', NULL, NULL, 'permanent (D)', 'none', 'no', 'This spell makes a lock or other small mechanism seem to be trapped to anyone who can detect traps. You place the spell upon any small mechanism or device, such as a lock, hinge, hasp, cork, cap, or ratchet. Any character able to detect traps, or who uses any spell or device enabling trap detection, is certain a real trap exists. Of course, the effect is illusory and nothing happens if the trap is “sprung”; its primary purpose is to frighten away thieves or make them waste precious time.', 'special dust worth 50 gp', NULL, false, true),
  ('phase_door', 'Phase Door', 'conjuration', 'creation', NULL, 7, 'arcane', 'sorcerer/wizard 7, witch 7; Domain travel 8; Bloodline fey 7', '1 standard action', 'touch', NULL, NULL, NULL, 'one usage per two levels', 'none', 'no', 'This spell creates an ethereal passage through wooden, plaster, or stone walls, but not other materials. The phase door is invisible and inaccessible to all creatures except you, and only you can use the passage. You disappear when you enter the phase door and appear when you exit. If you desire, you can take one other creature (Medium or smaller) through the door. This counts as two uses of the door. The door does not allow light, sound, or spell effects through it, nor can you see through it without using it. Thus, the spell can provide an escape route, though certain creatures, such as phase spiders, can follow with ease. A gem of true seeing or similar magic reveals the presence of a phase door but does not allow its use.', NULL, NULL, false, false),
  ('phase_step', 'Phase Step', 'conjuration', 'teleportation', NULL, 3, 'arcane', 'alchemist 3, bard 3, magus 3, sorcerer/wizard 3, summoner 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one willing creature touched', NULL, NULL, 'instantaneous', 'none', 'yes (harmless)', 'You instantly transfer the touched creature to a point you designate within range. This otherwise functions as the spell dimension door, except that you must have line of sight and line of effect to the target’s destination for this spell’s effects to properly function.', NULL, NULL, false, false),
  ('phasic_challenge', 'Phasic Challenge', 'transmutation', NULL, NULL, 6, 'divine', 'cleric 8, psychic 8, shaman 8, sorcerer/wizard 8, spiritualist 6, witch 7', '1 standard action', 'short (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level (D)', 'Will negates (see below)', 'yes', 'You select one enemy and one willing ally as targets. The enemy gains a new Will saving throw at the beginning of each turn, and on a successful saving throw the spell ends. Both targets remain visible and audible, and can see and hear other creatures, but cannot physically interact with any creature save one another. Spells or weapon attacks from the affected creatures impact only each other, though spells might affect terrain or other factors not related to other creatures. If one of the creatures becomes unconscious or dies, or if the effect is dispelled, the effect ends for both of them.', 'a scrap of a knight’s banner', NULL, false, false),
  ('phobia', 'Phobia', 'enchantment', 'compulsion', 'emotion, fear, mind-affecting', 5, 'arcane', 'bard 5, mesmerist 5, psychic 6, sorcerer/wizard 6, witch 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one intelligent creature', NULL, NULL, 'instantaneous', 'Will negates', 'yes', 'You instill the target with an intense, instinctual fear of a condition or circumstance, more powerful than the phobia lesser madness. You can name an energy type (acid, cold, electricity, fire, or sonic), a hazard (such as an avalanche or earthquake), or a single creature of the animal type or all vermin (applying when the target sees a swarm or a single Small or larger creature). Alternatively, you can name the following specific environments: darkness (darker than dim light, and you can’t apply this phobia to a creature with natural racial darkvision, see in darkness, blindsight, or similar senses), enclosed spaces (places that require the creature to squeeze),heights (10 times the target’s height, and you can’t apply this phobia to creatures with a natural fly speed), or water (you can’t apply this phobia to aquatic creatures or creatures with a natural swim speed).', 'a single white hair', NULL, false, false),
  ('pick_your_poison', 'Pick Your Poison', 'conjuration', 'healing', 'mind-affecting', 1, 'divine', 'bard 1, cleric/oracle 1, inquisitor 1, witch 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minute/level', 'Fort negates (harmless)', 'yes (harmless)', 'This spell temporarily converts even the deadliest poison affecting a creature into an intoxicating alcohol. If the subject is affected by a poison effect while under the effects of this spell, instead of the poison’s normal effect, she feels intoxicated as if she’d just had a very strong drink and takes a –2 penalty on attacks, saves, and checks for the duration of the spell. When the spell’s duration expires, the penalty ends and the poison’s normal effects apply. Pick your poison does not affect any poison effects that occurred before the spell was cast.', NULL, NULL, true, false),
  ('pied_piping', 'Pied Piping', 'enchantment', 'compulsion', 'mind-affecting, sonic', 6, 'arcane', 'bard 6', '1 standard action', '90 ft.', NULL, '90-ft.-radius emanation, centered on you', NULL, 'concentration + 1 round/level', 'Will partial; see text', 'yes', 'You call forth a melody so compelling and attractive that creatures belonging to a group with a specific, identifiable physical trait (such as type, subtype, age, gender, or hair color) find it almost impossible not to approach and follow you. You choose the nature of the creatures you seek to attract when you cast the spell and, once you make this choice, cannot alter it. You can only use physical traits to determine your audience. You can never use social and other more voluntary criteria (such as alignment, religion, nationality, or class) to select targets for this spell.', NULL, 'musical instrument', false, false),
  ('pierce_disguise', 'Pierce Disguise', 'divination', NULL, NULL, 3, 'divine', 'bard 3, medium 3, occultist 3, psychic 3, shaman 3, sorcerer/wizard 3, witch 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'You see through magical disguises (whether illusions or polymorph effects) of the same spell level or lower. This allows you to see the true forms of creatures magically disguised by such methods. The true form appears as a ghostly overlay on the creature’s disguised appearance.', NULL, NULL, false, false),
  ('pierce_facade', 'Pierce Facade', 'divination', NULL, NULL, 1, 'divine', 'alchemist 1, bard 1, cleric 1, inquisitor 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level', 'Will negates (harmless)', 'yes (harmless)', 'The target gains a +5 insight bonus on Perception checks to see through disguises. This bonus increases to +10 at caster level 7th.', 'an eagle’s eye', NULL, true, false),
  ('piercing_shriek', 'Piercing Shriek', 'evocation', NULL, 'pain, sonic', 2, 'arcane', 'bard 2, psychic 2', '1 standard action', 'medium (100 ft. + 10ft./level)', 'one creature', NULL, NULL, '1 round/level', 'Fortitude negates', 'yes', 'You emit an ear-splitting shriek which can be heard only by the target of this spell; all other observers merely see you screaming silently. The target suffers wracking pain from the scream, gaining the staggered condition. This spell has no effect on deaf creatures and cannot penetrate an area of silence.', NULL, NULL, false, false),
  ('pilfering_hand', 'Pilfering Hand', 'evocation', NULL, 'force', 2, 'divine', 'bard 2, cleric 2, magus 2, medium 2, mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 2, spiritualist 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one object', NULL, NULL, 'see text', 'none', 'yes (object)', 'You create and control an invisible telekinetic force, manipulating it with either startling abruptness or careful deliberateness, allowing you to seize an object from an opponent or remotely manipulate an object. You can utilize this force to one of two ends.', NULL, NULL, false, false),
  ('pillar_of_life', 'Pillar of Life', 'conjuration', 'healing', 'light', 5, 'divine', 'cleric/oracle 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, '5-ft.-square pillar of positive energy, 20 ft. high', '1 round/level', 'none', 'no', 'You conjure a pillar of positive energy in a single 5-foot square within range that radiates light as if it were a sunrod. Living creatures adjacent to the pillar can spend a standard action to touch the pillar and heal 2d8 points of damage + 1 point per caster level (maximum +20). Creatures can move into the square containing the pillar, but if an undead creature moves into the pillar it takes 1d6 points of damage per caster level (maximum 10d6). Undead creatures vulnerable to bright light take 1d8 points of damage per caster level (maximum 10d8). A creature cannot benefit or suffer more than once from a single casting of this spell.', NULL, NULL, true, false),
  ('pillow_talk', 'Pillow Talk', 'enchantment', 'compulsion', 'language-dependent, mind-affecting', 3, 'divine', 'bard 3, inquisitor 3, mesmerist 3, psychic 3, sorcerer/wizard 3, witch 3', '10 minutes', 'touch', 'sleeping, living creature touched', NULL, NULL, '1 minute/level', 'Will negates; see text', 'yes', 'This spell can be cast only on a sleeping creature, which must be present for the full duration of the casting time. You grant the semblance of wakefulness to the target, allowing it to answer questions. You can ask one question per 2 caster levels. The target’s knowledge is limited to what it normally knows, including the languages it speaks. Answers are brief, cryptic, or repetitive, especially if the creature would have opposed you when awake. If the target succeeds at a Will save, it awakens (unless some force is preventing it from being awake, such as magic or drugs), and it remains aware of the first question you asked. If the target has been subject to pillow talk within the past week, the new spell fails. While your questions don’t otherwise wake the target, this spell does nothing to prevent other sounds or stimulus from waking the target. A target who sleeps through the spellcasting and duration of the spell has no memory of it taking place, but a target who awakens before the spell ends remembers every question asked and what answers it gave.', NULL, NULL, false, false),
  ('pinecone_bomb', 'Pinecone Bomb', 'evocation', NULL, NULL, 2, 'divine', 'druid 2, ranger 3, shaman 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '10-ft.-radius spread', NULL, 'instantaneous', 'Reflex half', 'yes', 'This spell infuses a small pinecone with power, causing it to detonate with explosive force when thrown.', 'a pinecone', NULL, false, false),
  ('placebo_effect', 'Placebo Effect', 'illusion )', 'phantasm', 'mind-affecting', 2, 'arcane', 'medium 2, mesmerist 2, psychic 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level', 'Will disbelief (harmless)', 'Yes (harmless)', 'The subject temporarily ceases to feel the ill effects of a single ongoing affliction or condition from the following list: blinded, cursed, dazed, deafened, diseased, fatigued, frightened, nauseated, panicked, paralyzed, poisoned, shaken, sickened, staggered, or stunned. If that affliction or condition has a duration, it is suspended until this spell expires. If the subject has multiple instances of the same type of affliction (such as multiple diseases), a single casting of this spell can suspend only one of them. Placebo effect doesn’t remove or temporarily negate any damage that the affliction may have already caused, nor does it provide protection against receiving such conditions again.', 'a sugar cube', NULL, false, false),
  ('plague_bearer', 'Plague Bearer', 'necromancy', NULL, 'disease, evil', 6, 'divine', 'alchemist 6, antipaladin 6, cleric/oracle 6, druid 6, inquisitor 6, sorcerer/wizard 7, witch 6', '1 standard action', 'touch', 'one living creature', NULL, NULL, '1 round/level; see text', 'Fort negates; see text', 'yes', 'You make the target an asymptomatic carrier for a host of virulent diseases. Creatures that end their turn adjacent to the target must succeed at a Fortitude save or be affected as if by the spell contagion. The target itself does not become diseased, and suffers no ill effects from this spell. Once plague bearer ends, the target is no longer contagious, though any creature it infected remains diseased.', NULL, NULL, false, false),
  ('plague_carrier', 'Plague Carrier', 'necromancy', NULL, 'disease, evil', 4, 'divine', 'cleric/oracle 4, druid 4, sorcerer/wizard 5, witch 5', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level', 'Fortitude negates (harmless)', 'yes', 'The target’s natural attacks carry filth fever (DC 10 + 1/2 of the creature’s Hit Dice + creature’s Con modifier)', NULL, NULL, false, false),
  ('plague_storm', 'Plague Storm', 'necromancy', NULL, 'disease, evil', 6, 'divine', 'cleric/oracle 6, druid 6, sorcerer/wizard 7, witch 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'cloud spreads in 20-ft. radius, 20 ft. high', '1 minute/level and instantaneous (see text)', 'Fortitude negates', 'no', 'You create a hideous gray cloud, similar to fog cloud, that occasionally crackles with foul-smelling bolts of sickly green lightning. Creatures in the area must save or contract one of the following diseases: blinding sickness, bubonic plague, cackle fever, demon fever, devil chills, filth fever, leprosy, mindfire, red ache, shakes, or slimy doom (the disease is chosen by you when you cast the spell and applies to all creatures that fail the save). The disease is contracted immediately (the onset period does not apply) and is an instantaneous effect. Use the disease’s listed frequency to determine further effects, but the disease’s save DC increases by +2.', NULL, NULL, false, false),
  ('planar_adaptation', 'Planar Adaptation', 'transmutation', NULL, NULL, 4, 'divine', 'alchemist 5, cleric/oracle 4, sorcerer/wizard 5, summoner/unchained summoner 5; Elemental School air 5, earth 5, fire 5, water 5; Mystery solar 5', '1 standard action', 'personal', NULL, NULL, NULL, '1 hour/level (D)', NULL, NULL, 'Planar adaptation grants you immunity to the harmful environmental effects of a particular plane of existence, including such hazards as toxicity, extreme temperatures, and lack of air. Additionally, you gain energy resistance 20 to a single energy type prevalent on that plane (choose one if more than one type is equally prevalent). Planar adaptation has no effect when cast upon your native plane.', NULL, NULL, false, false),
  ('planar_aegis', 'Planar Aegis', 'abjuration', NULL, NULL, 3, 'divine', 'druid 5, occultist 4, ranger 3, sorcerer/wizard 5, summoner 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', NULL, NULL, 'You draw motes of essence from material native to a plane that has elemental or energy essence traits, weaving the essence together into a shield of force. Choose an essence trait from the list below; the material component for this spell must come from a plane that has the essence trait you chose. Each essence trait has an associated damage type (see the table below). Any creature that hits you with a non-reach melee weapon, natural weapon, or unarmed attack takes 3d6 points of damage plus 1 point per caster level you have (maximum +20) of a type corresponding to the essence trait you chose. In addition, you take only half damage from attacks or effects of the associated damage type, and if such an attack or effect allows a saving throw for half damage, you take no damage on a successful saving throw.', 'a fistful of naturally occurring material from a plane', NULL, false, false),
  ('planar_ally', 'Planar Ally', 'conjuration', 'calling', 'see text for lesser planar ally', 6, 'divine', 'cleric/oracle 6, shaman 6; Subdomain agathion 6, archon (good, law) 6, azata (chaos, good) 6, psychopomp (death, repose) 6', NULL, NULL, NULL, NULL, 'one or two called outsiders, totaling no more than 12 HD, which cannot be more than 30 ft. apart when they appear', NULL, NULL, NULL, 'This spell functions like lesser planar ally, except you may call a single creature of 12 HD or less, or two creatures of the same kind whose HD total no more than 12. The creatures agree to help you and request your return payment together.', 'offerings worth 1,250 gp plus payment', NULL, true, true),
  ('planar_binding', 'Planar Binding', 'conjuration', 'calling', 'see text', 5, 'arcane', 'sorcerer/wizard 6, summoner 5, unchained summoner 6; Domain void 6; Subdomain aeon 6, daemon 6, demon (chaos, evil) 6, devil (evil, law) 6, inevitable 6, protean 6; Bloodline efreeti 6; Elemental School air 6, earth 6, fire 6, water 6; Mystery dark tapestry 6, outer rifts 6', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like lesser planar binding, except that you may call a single creature of 12 HD or less, or up to three creatures of the same kind whose Hit Dice total no more than 12. Each creature gets a saving throw, makes an independent attempt to escape, and must be individually persuaded to aid you.', NULL, NULL, false, false),
  ('planar_inquiry', 'Planar Inquiry', 'conjuration', 'calling', NULL, 3, 'divine', 'cleric 3, druid 3, inquisitor 3, shaman 3, sorcerer/wizard 3, summoner 3, witch 3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell calls a creature from another plane to your precise location, functioning like lesser planar ally except as noted. When you call a creature using planar inquiry, the only task that you can ask of the creature is for it to answer questions or gather information regarding a specific topic (a person, a place, or a thing). After hearing your request, if the creature has an appropriate Knowledge skill, it can attempt a check to provide the information it has. If it lacks such a skill, the called creature leaves for 1d4 hours to gather this information. Upon its return, you roll 1d20 + your caster level, and use the result to determine what information the creature has gathered about the subject (as if using Diplomacy). The called creature stays for up to 10 minutes as it relays this information to you, after which it departs to its home plane. If the creature is attacked or damaged at any time during the spell’s duration, the spell ends and the creature returns to the plane from which you summoned it.', 'offerings worth 100 gp per HD of creature called', NULL, false, true),
  ('planar_orientation', 'Planar Orientation', 'divination', NULL, NULL, 1, 'divine', 'bard 1, cleric 1, druid 1, inquisitor 1, psychic 1, ranger 1, shaman 1, sorcerer/wizard 1, summoner 1, witch 1', '1 standard action', 'personal', 'you', NULL, NULL, 'instantaneous', NULL, NULL, 'This spell helps creatures accustomed to the concrete reality of the Material Plane to navigate within the confusing realities of other planes. When cast, it functions as know direction, save that instead of revealing true north, it reveals the direction of the palace or demesnes most associated with that plane or demiplane’s ruling god or demigod, as well as a brief and generic vision of that entity’s appearance or holy symbol. The spell functions only within whatever plane or demiplane you are located in at the time; for instance, if cast within a specific demon lord’s Abyssal realm or on a given layer of Hell, it would point to the seat of power for that demon lord or archdevil. If a plane or demiplane has multiple gods or rulers, it reveals the directions of the closest three, allowing for triangulation.', NULL, NULL, false, false),
  ('planar_refuge', 'Planar Refuge', 'conjuration', 'creation', NULL, 6, 'divine', 'cleric 7, druid 7, sorcerer/wizard 7, shaman 7, summoner 6, witch 7', '1 hour', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '50-ft.-radius area of safe environment', '1 day/level', 'none', 'no', 'This spell enforces the rules of the Material Plane on other planes of existence. Upon casting this spell on another plane, a spherical pocket of wilderness terrain forms around the designated point. The affected area defies the local climate and planar traits, suppressing any harmful environmental effects such as toxicity, extreme temperatures, or lack of air (though this spell doesn’t affect gravity). The area also becomes lush with edible plants whose appearance, taste, and smell bear characteristics distinct to the environment. On a negative-dominant plane, for example, the plants grow ghastly white leaves and taste bitter. Though planar refuge can be cast on any plane of existence other than the Material Plane, it requires a body of solid matter at least as large as its area to function.', 'precious stones worth 500 gp', NULL, false, true),
  ('plane_shift', 'Plane Shift', 'conjuration', 'teleportation', NULL, 5, 'divine', 'cleric/oracle 5, shaman 7, sorcerer/wizard 7, summoner 5, unchained summoner 6, witch 7; Subdomain freedom 5; Bloodline aberrant 7, djinni 7, efreeti 7', '1 standard action', 'touch', 'creature touched, or up to eight willing creatures joining hands', NULL, NULL, 'instantaneous', 'Will negates', 'yes', 'You move yourself or some other creature to another plane of existence or alternate dimension. If several willing persons link hands in a circle, as many as eight can be affected by the plane shift at the same time. Precise accuracy as to a particular arrival location on the intended plane is nigh impossible. From the Material Plane, you can reach any other plane, though you appear 5 to 500 miles (5d%) from your intended destination. Plane shift transports creatures instantaneously and then ends. The creatures need to find other means if they are to travel back (including casting plane shift again).', NULL, 'a forked metal rod attuned to the plane of travel', false, false),
  ('planeslayer_s_call', 'Planeslayer’s Call', 'enchantment', 'compulsion', 'mind-affecting, see text', 4, 'divine', 'cleric 5, inquisitor 4, paladin 4', '1 standard action', '20 ft.', NULL, NULL, NULL, '1 round/level', 'none', 'yes', 'The magic of your allies in the area becomes more potent against certain outsiders. Chose one alignment subtype (chaotic, evil, good, or lawful). Against outsiders with that alignment component or subtype, your allies in the area gain a +2 bonus on caster level checks to overcome spell resistance, and their spells ignore the first 10 points of energy resistance (but not energy immunity).', NULL, NULL, true, false),
  ('planetarium', 'Planetarium', 'illusion', 'figment', NULL, 2, 'divine', 'bard 2, cleric 2, druid 2, sorcerer/wizard 2, summoner 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '15-ft.-radius spherical projection of night sky', 'concentration + 3 rounds', 'none', 'Will disbelief (harmless)', 'You project an image of the night sky based on your current location and the local time, allowing you to observe the heavens and all of its celestial bodies and features even during the daytime, indoors, or underground. Anyone within the planetarium’s sphere can see the projection, though outside of the sphere the image becomes grainy and indistinct.', NULL, NULL, false, false),
  ('planetary_adaptation', 'Planetary Adaptation', 'transmutation', NULL, NULL, 4, 'divine', 'alchemist 5, cleric/oracle 4, sorcerer/wizard 5, summoner 5', '1 standard action', 'personal', NULL, NULL, NULL, '1 hour/level (D)', NULL, NULL, 'This spell functions as planar adaptation, except that it works only on worlds of the Material Plane. The cold void of space is considered a single world for the purpose of this spell, allowing you to survive in vacuum.you immunity to the harmful environmental effects of a particular plane of existence, including such hazards as toxicity, extreme temperatures, and lack of air.', NULL, NULL, false, false),
  ('planned_assault', 'Planned Assault', 'transmutation', NULL, NULL, 3, 'divine', 'cleric/oracle 3, paladin 3, ranger 4 (Angradd)', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, 'one creature/level, no two of which can be more than 30 ft. apart', NULL, '1 minute/level or until discharged', 'none', 'no', 'This spell increases the effectiveness of a planned action. If the targets spend at least 1 minute studying a situation, they receive bonuses to their first actions in response to the situation. All targets must declare in advance what their intended actions are. If they perform those actions, they receive a +2 sacred bonus to AC, saving throws, and checks for the first round. This bonus increases to +4 at 10th level and +6 at 15th level.', NULL, NULL, true, false),
  ('plant_growth', 'Plant Growth', 'transmutation', NULL, NULL, 3, 'divine', 'druid 3, ranger 3; Domain plant 3; Elemental School wood 4', '1 standard action', 'see text', 'or', 'see text', NULL, 'instantaneous', 'none', 'no', 'Plant growth has different effects depending on the version chosen.', NULL, NULL, true, false),
  ('plant_shape', 'Plant Shape', 'transmutation', 'polymorph', NULL, 5, 'arcane', 'alchemist 5,  sorcerer/wizard 5', '1 standard action', 'personal', 'you', NULL, NULL, '1 min./level (D)', NULL, NULL, 'When you cast this spell you can assume the form of any Small or Medium creature of the plant type. If the form you assume has any of the following abilities, you gain the listed ability: darkvision 60 feet, low-light vision, constrict, grab, and poison. If the form you assume does not possess the ability to move, your speed is reduced to 5 feet and you lose all other forms of movement. If the creature has vulnerability to an element, you gain that vulnerability.', 'a piece of the creature whose form you plan to assume', NULL, false, false),
  ('plant_voice', 'Plant Voice', 'transmutation', NULL, NULL, 2, 'divine', 'cleric 3, druid 2, shaman 2, witch 3', '1 standard action', NULL, 'one plant creature', NULL, NULL, '10 minutes/level', 'Will negates (harmless)', 'yes (harmless)', 'You grant one plant creature the ability to speak, hear, and understand any of the languages you know. If you know more than one language, you may grant the plant creature up to one language per 2 caster levels and you decide which languages to grant when the spell is cast. This spell does not cause the plant creature to be predisposed toward you in any way, but allows you to interact with them with Charisma-based skills normally. Plant creatures with an Intelligence score of 2 or lower can communicate and understand only the simplest of concepts, such as “friend,” “food,” and “danger.” This spell has no effect on ordinary plants and fungus.', 'a small root cutting', NULL, false, false),
  ('play_instrument', 'Play Instrument', 'divination', NULL, NULL, 1, 'arcane', 'bard 1', '1 standard action', 'personal', 'you', NULL, NULL, '10 minute/level', NULL, NULL, 'You may play one instrument of your choice as if you had 1 rank in the appropriate Perform skill. Instead of a conventional instrument, you may use an object as an improvised instrument, such as using a barrel as a drum or a bow as a harp, playing it as if it were crafted to make music.', NULL, NULL, false, false),
  ('plundered_power', 'Plundered Power', 'necromancy', NULL, 'evil', 6, 'divine', 'cleric 7, druid 7, occultist 6, shaman 7, sorcerer/wizard 7, summoner 6, witch 7', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 day/level', 'Will negates', 'no', 'You must sacrifice a creature just as you finish casting this spell.', 'crushed rubies worth 2,500 gp and a major organ from the sacrificed target, see text', NULL, false, true),
  ('pocketful_of_vipers', 'Pocketful of Vipers', 'conjuration', 'summoning', NULL, 3, 'divine', 'druid 3, occultist 3, ranger 3, shaman 3, witch 3', '1 round', 'touch', 'object touched', NULL, NULL, '1 hour/level or until discharged (D)', 'Fort negates (object)', 'no', 'You set a magical ward upon the object touched, which must be a container such as a pouch, bag, backpack, or pocket. If any creature opens the container without first speaking a command word, 1d3 summoned venomous snakes appear, slithering out of the container and attacking that creature for 1 round/level before disappearing. They attack other creatures only if they themselves are attacked.', 'a snake scale and fang', NULL, false, false),
  ('poison', 'Poison', 'necromancy', NULL, 'poison', 3, 'divine', 'antipaladin 4, cleric/oracle 4, druid 3, shaman 4, witch 4; Domain scalykind 4; Subdomain decay 4; Bloodline fey 4', '1 standard action', 'touch', 'living creature touched', NULL, NULL, 'instantaneous; see text', 'Fortitude negates; see text', 'yes', 'Calling upon the venomous powers of natural predators, you infect the subject with a horrible poison by making a successful melee touch attack. This poison deals 1d3 Constitution damage per round for 6 rounds. Poisoned creatures can make a Fortitude save each round to negate the damage and end the affliction.', NULL, NULL, true, false),
  ('poison_breath', 'Poison Breath', 'evocation', NULL, 'poison', 6, 'divine', 'cleric 7, druid 6, witch 7', '1 standard action', '15 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous', 'Fort negates', 'yes', 'You expel a cone-shaped burst of toxic mist from your mouth, subjecting everyone caught in the area to a deadly poison, as per the poison spell.', 'a spider’s mandible', NULL, true, false),
  ('poisoned_egg', 'Poisoned Egg', 'transmutation', NULL, 'poison', 1, 'divine', 'bard 1, cleric/oracle 1, inquisitor 1, magus 1, shaman 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'one egg', NULL, NULL, '1 minute/level', 'none (object)', 'no (object)', 'You transform the contents of a normal egg into a single dose of small centipede poison (injury; save DC 11; frequency 1/round for 4 rounds; effect 1 Dex; cure 1 save). The poison reverts to a normal egg at the end of the spell’s duration (the reverted egg substance is harmless unless the poisoned creature is vulnerable to eggs). The egg may be raw or cooked but must be whole and not empty when you cast the spell. When applying the poisoned egg’s contents to a weapon, the wielder has no chance of poisoning herself, as though she had the poison use class feature.', NULL, NULL, true, false),
  ('poisoner_s_exchange', 'Poisoner’s Exchange', 'transmutation', NULL, 'poison', 2, 'divine', 'alchemist 2, cleric 3, druid 2, occultist 3, psychic 3, sorcerer/wizard 3', '1 standard action', 'personal', 'you', NULL, NULL, 'instantaneous', NULL, NULL, 'You swallow a dose of poison with no effect and regurgitate a dose of a different poison (your choice) into the old container (or another you have on hand). Attempt a Craft (alchemy) check against the new poison’s DC. If you succeed, you create a dose of your chosen poison. If you fail, the poison you regurgitate is inert. If you roll a natural 1, you expose yourself to the original poison (although you remain immune to that poison if you have venom immunity or a similar class feature or ability). The new poison’s price must be the same as or less than the original poison’s price.', 'a dose of poison', NULL, false, false),
  ('poisonous_balm', 'Poisonous Balm', 'conjuration', 'healing', 'poison, ruse', 4, 'divine', 'cleric 4, druid 5, occultist 4, shaman 4, witch 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous, then 1 hour or until triggered plus 6 rounds; see text', 'Will partial (harmless), then Fort negates (see text)', 'yes', 'You mend the target’s injuries, curing 3d8 hit points + 1 point per caster level (maximum +15) as cure serious wounds, but leaving its body laced with a subtle toxin that remains inert until you activate it. A target that decides to attempt the Will save and succeeds is healed for half (as cure serious wounds) and negates the toxin. Otherwise, you can activate the toxin by concentrating on the spell as a standard action, at which point the victim takes 1d3 points of Strength damage per round for 6 rounds. Once the poison is active, the target can attempt a Fortitude save each round to negate that round’s damage and end the affliction. If you don’t trigger the poison for 1 hour, the spell ends and leaves the target unharmed.', NULL, NULL, false, false),
  ('poisonous_cloud', 'Poisonous Cloud', 'conjuration', 'creation', 'poison', 4, 'divine', 'bloodrager 4, magus 4, shaman 4, sorcerer/wizard 4, summoner 4, witch 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'cloud spreads in 20-ft. radius, 20 ft. high', '1 round/level', 'Fort negates; see text', NULL, 'Poisonous cloud creates a bank of fog like that created by fog cloud, except that the vapors are toxic. The cloud deals 1d2 points of Constitution damage per round to living creatures that fail their Fortitude saves.', 'small drop of poison', NULL, false, false),
  ('polar_midnight', 'Polar Midnight', 'transmutation', NULL, 'cold, darkness', 9, 'divine', 'cleric/oracle 9, druid 9, shaman 9, witch 9; Mystery lunar 9', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '30-ft. spread', '1 round/level', 'Fortitude partial', 'yes', 'You plunge an area into the brutal chill of the arctic night.', NULL, NULL, false, false),
  ('polar_ray', 'Polar Ray', 'evocation', NULL, 'cold', 8, 'arcane', 'sorcerer/wizard 8; Subdomain ice 9; Bloodline boreal 8; Elemental School water 8; Mystery winter 8', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'ray', 'instantaneous', 'none', 'yes', 'A blue-white ray of freezing air and ice springs from your hand. You must succeed on a ranged touch attack with the ray to deal damage to a target. The ray deals 1d6 points of cold damage per caster level (maximum 25d6) and 1d4 points of Dexterity drain.', NULL, 'a white ceramic cone or prism', false, false),
  ('polymorph', 'Polymorph', 'transmutation', 'polymorph', NULL, 5, 'arcane', 'alchemist 5, sorcerer/wizard 5', '1 standard action', 'touch', 'living creature touched', NULL, NULL, '1 min/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'This spell transforms a willing creature into an animal, humanoid or elemental of your choosing; the spell has no effect on unwilling creatures, nor can the creature being targeted by this spell influence the new form assumed (apart from conveying its wishes, if any, to you verbally).', 'a piece of the creature whose form you choose', NULL, false, false),
  ('polymorph_any_object', 'Polymorph Any Object', 'transmutation', 'polymorph', NULL, 8, 'arcane', 'sorcerer/wizard 8; Domain [subdomain] Artifice [construct] 8', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature, or one non-magical object of up to 100 cu. ft./level', NULL, NULL, 'see text', 'Fortitude negates (object); see text', 'yes (object)', 'This spell functions like greater polymorph, except that it changes one object or creature into another. You can use this spell to transform all manner of objects and creatures into new forms- you aren’t limited to transforming a living creature into another living form. The duration of the spell depends on how radical a change is made from the original state to its transmuted state. The duration is determined by using the following guidelines.', 'mercury, gum arabic, and smoke', NULL, true, false),
  ('polymorph_familiar', 'Polymorph Familiar', 'transmutation', 'polymorph', NULL, 3, 'divine', 'shaman 3, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. +5 ft./2 levels)', 'your familiar', NULL, NULL, '1 minute/level (D)', 'none', 'yes (harmless)', 'This spell functions as beast shape I, except it grants your familiar the form of any Small animal. Your familiar retains all of its special abilities and continues to grant you the special ability associated with its normal shape (such as a bat familiar’s bonus on Fly checks).', NULL, NULL, false, false),
  ('polypurpose_panacea', 'Polypurpose Panacea', 'transmutation', NULL, NULL, 1, 'arcane', 'alchemist 1, psychic 1, sorcerer/wizard 1', '1 standard action', 'personal', 'you', NULL, NULL, 'see below', NULL, NULL, 'This creates one of several cantrip-level effects relating to your health, well-being, and entertainment. The panacea has no side effects (for example, the intoxication panacea does not cause a hangover). When you use polypurpose panacea, choose one of the following effects.', NULL, NULL, false, false),
  ('positive_pulse', 'Positive Pulse', 'necromancy', NULL, NULL, 1, 'divine', 'cleric 1, inquisitor 1, paladin 1, shaman 1, sorcerer/wizard 1, spiritualist 1, summoner 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '5-ft.-radius burst', NULL, 'instantaneous plus 1 round (see text)', 'Will negates or Will negates (harmless); see text', 'yes', 'This spell causes a wave of positive energy to spread from a point you designate, damaging foes vulnerable to positive energy and bolstering living creatures. Each creature damaged by positive energy in the area (such as undead) must succeed at a Will save or take 1d6 points of damage, plus 1 point for every 2 caster levels (maximum +5). Haunts manifesting in the spell’s area also take this damage.', NULL, NULL, false, false),
  ('possess_object', 'Possess Object', 'necromancy', NULL, NULL, 5, 'arcane', 'sorcerer/wizard 5, witch 5', '1 standard action', NULL, 'one object; see text', NULL, NULL, '1 hour/level or until you return to your body', NULL, NULL, 'This spell functions as magic jar, except you transfer your mind to a single object, animating it as if using animate objects, except your mind controls the object as if it were your own body. You cannot speak or cast spells while possessing the object. Because your original body is effectively dead while under the effect of this spell, this temporarily suspends disease, poisons, and other afflictions affecting you.', NULL, NULL, false, false),
  ('possession', 'Possession', 'necromancy', NULL, NULL, 3, 'arcane', 'medium 3, mesmerist 5, occultist 4, psychic 5, sorcerer/wizard 5, spiritualist 4, summoner 5, witch 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, '1 hour/level (D)', 'Will negates', 'yes', 'You attempt to possess a creature by projecting your soul into its body. The target creature must be within spell range and you must know where it is, though you do not need line of sight or line of effect to it. When you transfer your soul upon casting, your body appears to be dead. Failure to take over a host ends the spell.', NULL, NULL, false, false),
  ('possession_trap', 'Possession Trap', 'necromancy', NULL, NULL, 5, 'arcane', 'sorcerer/wizard 5, witch 5', '1 standard action', 'personal', 'you', NULL, NULL, '24 hours or until activated (see text); 1 round/level', NULL, NULL, 'You place a protective ward over your spirit that ensnares creatures attempting to possess you. Should a creature attempt to possess you (such as via magic jar or a similar effect) while you are under the effects of possession trap, that creature must first succeed at a Will save or its possession attempt is ruined and its spirit is shunted into this spell’s focus gem. The trapped creature is contained within the focus gem for 1 round per caster level, acting as though it were trapped in a magic jar for the duration of this effect. This effect fails if you are not carrying the focus gem during the time of the possession attempt.', NULL, 'a gem or crystal worth at least 500 gp', false, true),
  ('pouncing_fury', 'Pouncing Fury', 'transmutation', NULL, NULL, 2, 'divine', 'alchemist 2, bloodrager 2, druid 2, magus 2, ranger 2, sorcerer/wizard 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'When you charge, you can make a full attack at the end of that charge, but only with claw attacks you have, and you can make only one attack per claw. If you have abilities that grant bonuses on damage rolls or that apply other special effects to charge attacks, only the first claw attack benefits from these bonuses. When you make a claw attack as an attack of opportunity, you can expend one additional use of your attacks of opportunity to make an additional claw attack against the target that provoked the attack.', NULL, NULL, false, false),
  ('power_word_blind', 'Power Word Blind', 'enchantment', 'compulsion', 'mind-affecting', 7, 'arcane', 'sorcerer/wizard 7, witch 7; Domain darkness 7,  war 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature with 200 hp or less', NULL, NULL, 'see text', 'none', 'yes', 'You utter a single word of power that causes a creature to become blinded, whether the creature can hear the word or not. The duration of the spell depends on the target’s current hit point total. Any creature that currently has 201 or more hit points is unaffected.', NULL, NULL, false, false),
  ('power_word_kill', 'Power Word Kill', 'enchantment', 'compulsion', 'death, mind-affecting', 9, 'arcane', 'sorcerer/wizard 9, witch 9; Domain war 9', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature with 100 hp or less', NULL, NULL, 'instantaneous', 'none', 'yes', 'You utter a single word of power that instantly kills one creature of your choice, whether the creature can hear the word or not. Any creature that currently has 101 or more hit points is unaffected by power word kill.', NULL, NULL, false, false),
  ('power_word_stun', 'Power Word Stun', 'enchantment', 'compulsion', 'mind-affecting', 8, 'arcane', 'sorcerer/wizard 8, witch 8; Domain war 8; Bloodline arcane 8', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature with 150 hp or less', NULL, NULL, 'See text', 'none', 'yes', 'You utter a single word of power that instantly causes one creature of your choice to become stunned, whether the creature can hear the word or not. The duration of the spell depends on the target’s current hit point total. Any creature that currently has 151 or more hit points is unaffected by power word stun.', NULL, NULL, false, false),
  ('pox_of_rumors', 'Pox of Rumors', 'enchantment', 'compulsion', 'curse, mind-affecting', 5, 'divine', 'bard 5, cleric 7, mesmerist 5, psychic 7, sorcerer/wizard 7, spiritualist 5, witch 7', '8 hours', 'see text', 'one creature', NULL, NULL, '1 day/level', 'Will negates, then Will partial (see text)', 'yes', 'You curse the target to attract negative assumptions and rumors of a sort you specify when you cast the spell. If the target fails the initial save to negate the curse, every day that it spends in a settlement, it must attempt a Will save. If it fails, it accidentally says or does something that makes others assume the rumor you specified is true in some way that is unflattering or incriminating. If the creature is not aware of the nature of the rumors, it takes a –4 penalty on these secondary saves.', 'a physical connection to the target; see text', NULL, false, false),
  ('pox_pustules', 'Pox Pustules', 'necromancy', NULL, 'disease', 2, 'divine', 'druid 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 minute/level', 'Fortitude negates', 'yes', 'You inflict a painful, itching rash on the target creature. The target is sickened and takes a -4 penalty to Dexterity (this penalty cannot lower Dexterity below 0). The target can spend a move action scratching furiously at the rash to remove the sickened condition (but not the Dexterity penalty) until the start of its next turn.', 'leaves from a toxic plant', NULL, false, false),
  ('prayer', 'Prayer', 'enchantment', 'compulsion', 'mind-affecting', 3, 'divine', 'cleric/oracle 3, inquisitor 3, paladin 3; Domain community 3; Subdomain archon (good, law) 3, leadership 3', '1 standard action', '40 ft.', NULL, 'all allies and foes within a 40-ft.-radius burst centered on you', NULL, '1 round/level', 'none', 'yes', 'You bring special favor upon yourself and your allies while bringing disfavor to your enemies. You and each of your allies gain a +1 luck bonus on attack rolls, weapon damage rolls, saves, and skill checks, while each of your foes takes a -1 penalty on such rolls.', NULL, NULL, true, false),
  ('prediction_of_failure', 'Prediction of Failure', 'divination', NULL, 'curse, fear, mind-affecting', 8, 'arcane', 'sorcerer/wizard 8, witch 8; Bloodline imperious 8', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'permanent or 1 round/level (see text)', 'Will partial', 'yes', 'You wrack the target’s body and mind with the anguish and suffering of every bitter failure it will ever experience, rendering it permanently shaken and sickened. A successful Will save reduces the duration to 1 round per level. If the target is a spellcaster, failing this saving throw means it also gains a random minor spellblight.', NULL, NULL, false, false),
  ('prehensile_pilfer', 'Prehensile Pilfer', 'transmutation', NULL, NULL, 3, 'arcane', 'alchemist 3, bard 3, magus 3, sorcerer/wizard 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level', 'Fort negates (harmless)', 'yes (harmless)', 'The target’s tail moves and acts more quickly, almost with a mind of its own. When making a full-attack action, the target may use its tail to make a dirty trick or steal combat maneuver as a swift action. For the purpose of this attack, the target’s tail is a natural weapon with a reach of 5 feet. This spell has no effect on creatures lacking a prehensile tail. If the target already has an extra attack from haste or a similar effect, this spell only allows the tail to make dirty trick and steal combat maneuvers, but does not grant an extra attack.', NULL, NULL, false, false),
  ('preserve', 'Preserve', 'necromancy', NULL, NULL, 1, 'divine', 'adept 1, cleric 1, medium 1, occultist 1, ranger 1, shaman 1, sorcerer/wizard 1, spiritualist 1, witch 1', '1 standard action', 'touch', 'one or more objects touched, up to 1 lb./level', NULL, NULL, '1 week', 'Will negates (object)', 'yes (object)', 'You imbue one or more objects with magic that dramatically slows down natural processes that lead to decay and spoilage.', 'a pinch of salt', NULL, true, false),
  ('preserve_grace', 'Preserve Grace', 'divination', NULL, 'good', 1, 'divine', 'cleric 2, inquisitor 1, paladin 1', '1 minute', 'touch', 'one good-aligned creature', NULL, NULL, '1 day', 'Will negates (harmless)', 'no', 'You grant a creature the ability to foresee moral consequences, as if the creature were wearing a phylactery of faithfulness. The spell’s guidance focuses on the protection of beauty and encourages peaceful resolution and mercy.', NULL, 'a silver hand mirror worth 50 gp', false, true),
  ('pressure_adaptation', 'Pressure Adaptation', 'abjuration', NULL, NULL, 3, 'divine', 'alchemist 3, bloodrager 3, cleric/oracle 3, druid 3, hunter 3, investigator 3, psychic 3, ranger 3, shaman 3, summoner 3, summoner (unchained) 3, warpriest 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level', 'Fort negates (harmless)', 'yes (harmless)', 'The target adapts incredibly quickly to changes in pressure, adjusting to 100 feet of new pressure (or the entire shift, in the case of an instantaneous shift within its native range) after just one successful Fortitude saving throw instead of the usual five.', 'slime from a cephalopod', NULL, false, false),
  ('prestidigitation', 'Prestidigitation', 'universal', NULL, NULL, 0, 'arcane', 'bard 0, magus 0, psychic 0, sorcerer/wizard 0', '1 standard action', '10 ft.', NULL, 'see text', NULL, '1 hour', 'see text', 'no', 'Prestidigitations are minor tricks that novice spellcasters use for practice. Once cast, a prestidigitation spell enables you to perform simple magical effects for 1 hour. The effects are minor and have severe limitations. A prestidigitation can slowly lift 1 pound of material. It can color, clean, or soil items in a 1-foot cube each round. It can chill, warm, or flavor 1 pound of nonliving material. It cannot deal damage or affect the concentration of spellcasters. Prestidigitation can create small objects, but they look crude and artificial. The materials created by a prestidigitation spell are extremely fragile, and they cannot be used as tools, weapons, or spell components. Finally, prestidigitation lacks the power to duplicate any other spell effects. Any actual change to an object (beyond just moving, cleaning, or soiling it) persists only 1 hour.', NULL, NULL, false, false),
  ('primal_regression', 'Primal Regression', 'enchantment', 'compulsion', 'mind-affecting', 5, 'divine', 'druid 6, mesmerist 5, psychic 6, shaman 6, witch 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature/2 levels, no two of which can be more than 30 feet apart', NULL, NULL, '1 minute/level', 'Will negates', 'yes', 'This spell sequesters the targets’ ability for higher reasoning, allowing their darker impulses to come to the fore. An affected target becomes a ravening monster—savage, bloodthirsty, and brutish. Until the spell ends, the targets have all of the following benefits and drawbacks.', NULL, NULL, false, false),
  ('primal_scream', 'Primal Scream', 'abjuration', NULL, 'mind-affecting, sonic', 4, 'arcane', 'bard 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'You voice a mighty yell from the depths of your soul, invigorating yourself and dispelling enchantment and paralysis effects. This functions as break enchantment, except it only affects you and only frees you from enchantment and paralysis effects. If the caster level check to break the hostile effect succeeds, you give voice to your scream and the spell takes effect normally; if not, this spell fails without further effect. You can cast this spell even when paralyzed or unable to speak because of an enchantment effect, but not in an area of silence, if you are unable to speak for reasons other than enchantments or paralysis (for example, if you are gagged), or if cast in an environment where speaking is not possible.', NULL, NULL, false, false),
  ('prismatic_sphere', 'Prismatic Sphere', 'abjuration', NULL, NULL, 9, 'arcane', 'sorcerer/wizard 9; Domain artifice 9, protection 9, sun 9; Mystery solar 9', NULL, '10 ft.', NULL, NULL, '10-ft.-radius sphere centered on you', NULL, NULL, NULL, 'This spell functions like prismatic wall, except you conjure up an immobile, opaque globe of shimmering, multicolored light that surrounds you and protects you from all forms of attack. The sphere flashes in all colors of the visible spectrum.', NULL, NULL, false, false),
  ('prismatic_spray', 'Prismatic Spray', 'evocation', NULL, NULL, 7, 'arcane', 'sorcerer/wizard 7; Mystery heavens 7', '1 standard action', '60 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous', 'see text', 'yes', 'This spell causes seven shimmering, multicolored beams of light to spray from your hand. Each beam has a different power. Creatures in the area of the spell with 8 HD or less are automatically blinded for 2d4 rounds. Every creature in the area is randomly struck by one or more beams, which have additional effects.', NULL, NULL, false, false),
  ('prismatic_wall', 'Prismatic Wall', 'abjuration', NULL, NULL, 8, 'arcane', 'sorcerer/wizard 8; Subdomain isolation 8', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'wall 4 ft./level wide, 2 ft./level high', '10 min./level (D)', 'see text', 'see text', 'Prismatic wall creates a vertical, opaque wall- a shimmering, multicolored plane of light that protects you from all forms of attack. The wall flashes with seven colors, each of which has a distinct power and purpose. The wall is immobile, and you can pass through and remain near the wall without harm. Any other creature with less than 8 HD that is within 20 feet of the wall is blinded by the colors for 2d4 rounds if it looks at the wall.', NULL, NULL, false, false),
  ('probe_history_half_elf', 'Probe History (Half-Elf)', 'divination', NULL, NULL, 2, 'divine', 'bard 3, cleric 4, inquisitor 4, medium 2, mesmerist 3, occultist 3, sorcerer/wizard 4', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous', 'Will negates', 'yes', 'You gain a glimpse of a potential reality similar to this one but that never was. If the target fails her Will save, you can ask about one topic and attempt the appropriate Knowledge check with a +5 competence bonus; track Knowledge checks attempted with this spell separately for the purpose of disallowing retries on Knowledge checks. You learn information on that topic from a reality in which you were an acquaintance of the target, although the differences in that reality might cause the answer to be subtly different than in your own. Once you have probed a target’s history, successfully or not, you cannot target the same creature’s history or search for the same information in another creature’s history.', NULL, NULL, true, false),
  ('produce_flame', 'Produce Flame', 'evocation', NULL, 'fire', 1, 'divine', 'druid 1, shaman 1; Domain fire 2', '1 standard action', '0 ft.', NULL, NULL, 'flame in your palm', '1 min./level (D)', 'none', 'yes', 'Flames as bright as a torch appear in your open hand. The flames harm neither you nor your equipment.', NULL, NULL, false, false),
  ('profane_nimbus', 'Profane Nimbus', 'evocation', NULL, 'evil', 4, 'divine', 'antipaladin 4, cleric 5, inquisitor 5', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', NULL, NULL, 'You are surrounded by a nimbus of shadow shaped like your god’s unholy symbol or a symbol of your faith. Any good creature striking you with unarmed strikes, natural weapons, or a handheld weapon deals normal damage, but at the same time, the attacker takes 1d6 points of damage + 1 point per caster level (maximum +15).', NULL, NULL, true, false),
  ('prognostication', 'Prognostication', 'divination', NULL, NULL, 4, 'divine', 'cleric 6, inquisitor 6, medium 4, psychic 6, shaman 6, spiritualist 6, witch 6', '8 hours', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You glimpse the future. Prognostication functions as divination except that the spell can see up to a year and a day into the future. Because of the increased unpredictability of the distant future, prognostication is significantly more cryptic than the already-cryptic divination spell.', 'rare incense and tonics worth 250 gp', NULL, false, true),
  ('programmed_image', 'Programmed Image', 'illusion', 'figment', NULL, 6, 'arcane', 'bard 6, sorcerer/wizard 6', NULL, NULL, NULL, NULL, 'visual figment that cannot extend beyond a 20-ft. cube + one 10-ft. cube/level (S)', 'permanent until triggered, then 1 round/level', NULL, NULL, 'This spell functions like silent image, except that this spell’s figment activates when a specific condition occurs. The figment includes visual, auditory, olfactory, and thermal elements, including intelligible speech.', 'fleece and jade dust worth 25 gp', NULL, false, true),
  ('project_image', 'Project Image', 'illusion', 'shadow', 'shadow', 6, 'arcane', 'bard 6, sorcerer/wizard 7; Subdomain deception 7; Mystery occult 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'one shadow duplicate', '1 round/level (D)', 'Will disbelief (if interacted with)', 'no', 'You tap energy from the Plane of Shadow to create a quasi-real, illusory version of yourself. The projected image looks, sounds, and smells like you but is intangible. The projected image mimics your actions (including speech) unless you direct it to act differently (which is a move action).', 'a small replica of you worth 5 gp', NULL, false, true),
  ('prophetic_lore', 'Prophetic Lore', 'divination', NULL, NULL, 6, 'arcane', 'sorcerer/wizard 6', 'see below', 'personal', 'you', NULL, NULL, NULL, NULL, NULL, 'You call to mind prophecies regarding a person, place, item, or event. These might be predictions made in the past, lost to history, or entirely new. If the person or item is present or if you are at the desired location, the casting time is 1d4×10 minutes; if you have general but specific information about the subject, the casting time is 1d4×2 hours. If you have only rumors, you cannot cast this spell with any effect.', 'incense worth 150 gp', 'rare herbs and spices worth 250 gp', false, true),
  ('prosperous_room', 'Prosperous Room', 'enchantment', NULL, NULL, 3, 'arcane', 'bard 3, sorcerer/wizard 3', '1 day', 'touch', 'room you own; see text', NULL, NULL, '1 day/level (D)', 'none', 'yes', 'The targeted room is enchanted to have magical appeal for customers, an increase in the workflow of its employees, or the generation of additional materials to work with. While this spell is in effect, the targeted room produces 1 more Goods, Labor, Influence, or Magic than it already does. If the room produces multiple types of capital, it produces an additional capital of each type. If the room generates gp, it generates 25% more.', NULL, NULL, false, false),
  ('protection_from_arrows', 'Protection from Arrows', 'abjuration', NULL, NULL, 2, 'arcane', 'alchemist 2, bloodrager 2, psychic 2, sorcerer/wizard 2, spiritualist 2, summoner/unchained summoner 2; Elemental School wood 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level or until discharged', 'Will negates (harmless)', 'yes (harmless)', 'The warded creature gains resistance to ranged weapons. The subject gains damage reduction 10/magic against ranged weapons. This spell doesn’t grant you the ability to damage creatures with similar damage reduction. Once the spell has prevented a total of 10 points of damage per caster level (maximum 100 points), it is discharged.', NULL, 'a piece of tortoiseshell or turtle shell', false, false),
  ('protection_from_chaos', 'Protection from Chaos', 'abjuration', NULL, 'lawful', 1, 'divine', 'bloodrager 1, cleric/oracle 1, inquisitor 1, paladin 1, shaman 1, sorcerer/wizard 1, summoner/unchained summoner 1; Domain law 1; Subdomain purity 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 min./level (D)', 'Will negates (harmless)', 'no; see text', 'This spell functions like protection from evil, except that the deflection and resistance bonuses apply to attacks made by chaotic creatures. The target receives a new saving throw against control by chaotic creatures and chaotic summoned creatures cannot touch the target.', NULL, NULL, true, false),
  ('protection_from_energy', 'Protection from Energy', 'abjuration', NULL, NULL, 2, 'divine', 'alchemist 3, bloodrager 3, cleric/oracle 3, druid 3, inquisitor 3, occultist 3, psychic 3, ranger 2, shaman 3, sorcerer/wizard 3, spiritualist 3, summoner/unchained summoner 3; Domain luck 3, protection 3; Bloodline destined 3, elemental 3 Elemental School air 3, earth 3, fire 3, water 3; Mystery volcano 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 min./level or until discharged', 'Fortitude negates (harmless)', 'yes (harmless)', 'Protection from energy grants temporary immunity to the type of energy you specify when you cast it (acid, cold, electricity, fire, or sonic). When the spell absorbs 12 points per caster level of energy damage (to a maximum of 120 points at 10th level), it is discharged.', NULL, NULL, true, false),
  ('protection_from_evil', 'Protection from Evil', 'abjuration', NULL, 'good', 1, 'divine', 'cleric/oracle 1, inquisitor 1, paladin 1, shaman 1, sorcerer/wizard 1, summoner/unchained summoner 1; Domain good 1; Subdomain purity 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 min./level (D)', 'Will negates (harmless)', 'no; see text', 'This spell wards a creature from attacks by evil creatures, from mental control, and from summoned creatures. It creates a magical barrier around the subject at a distance of 1 foot. The barrier moves with the subject and has three major effects.', NULL, NULL, true, false),
  ('protection_from_good', 'Protection from Good', 'abjuration', NULL, 'evil', 1, 'divine', 'antipaladin 1, cleric/oracle 1, inquisitor 1, shaman 1, sorcerer/wizard 1, summoner/unchained summoner 1; Domain evil 1; Subdomain purity 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 min./level (D)', 'Will negates (harmless)', 'no; see text', 'This spell functions like protection from evil, except that the deflection and resistance bonuses apply to attacks made by good creatures. The target receives a new saving throw against control by good creatures and good summoned creatures cannot touch the target.', NULL, NULL, true, false),
  ('protection_from_law', 'Protection from Law', 'abjuration', NULL, 'chaotic', 1, 'divine', 'antipaladin 1, cleric/oracle 1, inquisitor 1, shaman 1, sorcerer/wizard 1, summoner/unchained summoner 1; Domain chaos 1; Subdomain purity 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 min./level (D)', 'Will negates (harmless)', 'no; see text', 'This spell functions like protection from law, except you divide the duration in 1-minute intervals among the creatures touched.', NULL, NULL, true, false),
  ('protection_from_natural_attacks', 'Protection from Natural Attacks', 'abjuration', NULL, NULL, 2, 'divine', 'alchemist 3, druid 4, hunter 2, investigator 3, psychic 4, ranger 2, shaman 4, spiritualist 3, summoner 3, summoner (unchained) 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level', 'Fort negates (harmless)', 'yes (harmless)', 'Upon casting this spell, select one type of natural attack from the following: bite, claw, gore, hoof, pincers, slam, sting, swarm, tail slap, talon, tentacle, or wing. For the duration of the spell, the target gains DR 5/— against all attacks from natural weapons of the selected type.', 'a scale from a lizard', NULL, true, false),
  ('protection_from_outsiders', 'Protection from Outsiders', 'abjuration', NULL, 'see text', 2, 'divine', 'cleric 2, inquisitor 2, paladin 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level (D)', 'Will negates (harmless)', 'no; see text', 'This spell wards a creature from attacks by outsiders with a specific racial subtype, from mental control exerted by creatures of the chosen subtype, and from summoned creatures of that subtype. Only the subtypes of specific outsider races—angel, azata, demon, oni, psychopomp, protean, and so on—can be chosen as the subtype this spell protects against. Alignment subtypes or other general subtypes (like elemental, extraplanar, or native) cannot be selected. Outsiders without an outsider racial subtype (like genies, night hags, yeth hounds, or xills) are not affected by this spell.', NULL, NULL, true, false),
  ('protection_from_spells', 'Protection from Spells', 'abjuration', NULL, NULL, 8, 'arcane', 'sorcerer/wizard 8, summoner 6; Domain magic 8', '1 standard action', 'touch', NULL, NULL, NULL, '10 min./level', 'Will negates (harmless)', 'yes (harmless)', 'The subject gains a +8 resistance bonus on saving throws against spells and spell-like abilities (but not against supernatural and extraordinary abilities).', 'diamond worth 500 gp', 'One 1,000 gp diamond per target. Each subject must carry the gem for the duration of the spell. If a subject loses the gem, the spell ceases to affect him.', false, true),
  ('protection_from_spores', 'Protection from Spores', 'abjuration', NULL, NULL, 1, 'divine', 'alchemist 2, cleric/oracle 2, druid 2, hunter 1, investigator 2, ranger 1, shaman 2, warpriest 2, witch 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level', 'Fort negates (harmless)', 'no', 'With a touch, you bolster a creature’s body to protect it from the harmful effects of spores and similar afflictions. While under the effect of this spell, a creature is immune to the effects of brown mold, green slime, russet mold, yellow mold, and any similar hazard, provided the hazard is CR 6 or lower. Similarly, the creature is immune to poison, disease, and infestation attacks from all fungal creatures of CR 6 or lower, including effects such as basidirond spores, violet fungus rot, and the like. The target is immune to fungus-based toxins, such as striped toadstool. Against similar hazards or monsters of CR 7 or higher, the target gains a bonus on all saving throws against the effect equal to half your caster level. Protection from spores offers no protection against fungal infestations created by the seeded, or by the spell what grows within.', NULL, NULL, false, false),
  ('protection_from_technology', 'Protection from Technology', 'abjuration', NULL, NULL, 2, 'divine', 'cleric 2, sorcerer/wizard 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level (D)', 'Will negates (harmless), see text', 'no, see text', 'This spell wards a creature from attacks by technological objects and creatures of the robot subtype, and protects against mental control from technological sources. It creates a magical barrier around the subject at a distance of 1 foot. The barrier moves with the subject and has two major effects.', 'a pinch of powdered copper', NULL, true, false),
  ('protective_penumbra', 'Protective Penumbra', 'evocation', NULL, 'darkness', 2, 'divine', 'cleric/oracle 2, occultist 2, psychic 2, sorcerer/wizard 2, spiritualist 2, witch 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level', 'Will negates (harmless)', 'yes', 'This spell keeps the target slightly in shadow. A target with light blindness, light sensitivity, or vulnerability to sunlight (such as vampires and wraiths) may ignore penalties from those qualities. The spell gives the target a +2 bonus on saving throws against nonmagical hazards related to bright light, such as glare or sunburn.', NULL, NULL, false, false),
  ('protective_spirit', 'Protective Spirit', 'conjuration', 'creation', NULL, 2, 'divine', 'ranger 2', '1 standard action', 'personal', NULL, NULL, NULL, '1 round/level', NULL, NULL, 'A protective spirit is an invisible, mindless, shapeless force that hovers about you, defending you against unexpected attacks. When a creature makes an attack of opportunity against you, the protective spirit makes an immediate attack using your base attack bonus plus your Dexterity modifier. On a successful hit, the spirit does no damage, but it causes the attack of opportunity to automatically miss. A protective spirit can defend against a number of attacks of opportunity equal to your Dexterity bonus (minimum 1) per round.', NULL, NULL, true, false),
  ('prying_eyes', 'Prying Eyes', 'divination', NULL, NULL, 5, 'arcane', 'sorcerer/wizard 5, witch 5', '1 minute', '1 mile', NULL, NULL, '10 or more levitating eyes', '1 hour/level; see text (D)', 'none', 'no', 'You create a number of semi-tangible, visible magical orbs (called “eyes”) equal to 1d4 + your caster level. These eyes move out, scout around, and return as you direct them when casting the spell. Each eye can see 120 feet (normal vision only) in all directions.', 'a handful of crystal marbles', NULL, false, false),
  ('psychic_asylum', 'Psychic Asylum', 'illusion )', 'phantasm', 'mind-affecting', 5, 'arcane', 'mesmerist 5, psychic 5, sorcerer/wizard 6', '1 swift action', 'personal', 'you', NULL, NULL, 'instantaneous; see text', 'none', 'no', 'You retreat into a mindscape of your own making that allows you to perform a lengthy mental task in an instant.', NULL, NULL, false, false),
  ('psychic_crush_i', 'Psychic Crush I', 'necromancy', NULL, 'mind-affecting', 5, 'arcane', 'psychic 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'Will partial and Fortitude partial; see text', 'yes', 'Using your psychic power, you invade the mind of the target and tear it asunder, causing massive internal damage to both its mind and body. If the target succeeds at the initial Will save, it is sickened for 1 round. If the target fails its Will save, it must attempt a Fortitude save (with a +4 circumstance bonus on this save if it has more than half its total hit points remaining). If it also fails the Fortitude save, the target is reduced to –1 hit points and is dying. If the target succeeds at its Fortitude save, it instead takes 3d6 points of damage + 1 point of damage per caster level, which cannot reduce the target below –1 hit point, and the target is sickened for 1 round. This attack has no effect on creatures without an Intelligence score.', NULL, NULL, false, false),
  ('psychic_image', 'Psychic Image', 'illusion', 'shadow', NULL, 9, 'arcane', 'psychic 9', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, 'one shadow duplicate', '1 round/level (D)', 'Will disbelief (if interacted with)', 'yes', 'You envelop your consciousness in a quasi-real image of yourself.', NULL, NULL, false, false),
  ('psychic_leech', 'Psychic Leech', 'enchantment', 'compulsion', 'emotion, mind-affecting', 2, 'arcane', 'bloodrager 3, magus 3, medium 3, mesmerist 2, psychic 2, sorcerer/wizard 3, spiritualist 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, '1 minute/level (D)', 'Will partial', 'yes', 'The target experiences feelings of ennui and lethargy, becoming fatigued for the spell’s duration. While the target is fatigued and is within the spell’s range, you gain a +2 enhancement bonus to Strength and Dexterity. On a successful save, the target is fatigued for only 1d4 rounds and you receive no bonus. This spell has no effect if it targets a creature that is already fatigued.', NULL, NULL, false, false),
  ('psychic_reading', 'Psychic Reading', 'divination', NULL, NULL, 1, 'divine', 'bard 2, inquisitor 2, medium 1, mesmerist 1, occultist 1, psychic 1, sorcerer/wizard 2, spiritualist 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one humanoid creature', NULL, NULL, '1 round', 'none', 'yes', 'You are able to read a person’s surface thoughts and take cues from the person’s appearance, body language, and manner of speech to infer a great deal of information about the person, even if that person is in disguise (including polymorph effects). When casting the spell, attempt a DC 20 Sense Motive check with a bonus equal to your caster level.', NULL, NULL, false, false),
  ('psychic_surgery', 'Psychic Surgery', 'enchantment', NULL, 'mind-affecting', 5, 'arcane', 'mesmerist 5, psychic 6', '10 minutes', 'touch', 'one willing and living creature', NULL, NULL, 'instantaneous', 'none', 'no', 'Psychic surgery cures the target of all Intelligence, Wisdom, and Charisma damage and restores all points permanently drained from the target’s Intelligence, Wisdom, and Charisma scores. It also eliminates all ongoing insanity, confusion, and fear effects. Psychic surgery can also remove other mental afflictions, including enchantment spells and abilities, and even instantaneous effects, but in this case, if dispel magic couldn’t remove the effect, psychic surgery works only if the spell level or equivalent spell level of the effect was 6th level or lower. Psychic surgery removes all effects magically altering the target’s memory, even instantaneous effects, and it can restore a memory to perfect clarity like the second use of modify memory.', 'diamond dust worth 250 gp', NULL, false, true),
  ('psychonaut_manifestation', 'Psychonaut Manifestation', 'enchantment', 'compulsion', 'emotion, mind-affecting', 2, 'arcane', 'psychic 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', 'see text', NULL, 'You take a mental journey through the doors of perception to enter an altered state of consciousness. Despite this hallucinatory transmigration being entirely unreal, your mind and body fully react to it. You gain a +4 alchemical bonus to a random ability score, as well as a corresponding –2 penalty. If the bonus applies to Strength, the penalty applies to Intelligence, and vice versa. If the bonus applies to Dexterity, the penalty applies to Wisdom, and vice versa. If the bonus applies to Constitution, the penalty applies to Charisma, and vice versa. Each round as a standard action, you can explore the nooks and crannies of your imagination to further alter your corporal self. If you do so, attempt a Will save against the spell’s save DC. If you succeed, randomly select another ability score and change the alchemical bonus and associated penalty accordingly. If you fail, you are dazed for 1 round instead as your mind reels from learning unexpected truths about yourself.', 'a small piece of psychoactive cactus', NULL, false, false),
  ('pugwampi_s_grace', 'Pugwampi’s Grace', 'enchantment', 'compulsion', 'mind-affecting', 2, 'arcane', 'bard 2, sorcerer/wizard 3, witch 3', '1 standard action', 'short (25 ft. + 5 ft./2 levels)', 'one creature (see below)', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'The gremlins known as pugwampis infect those around them with a malignant form of unluck—an effect that this spell emulates. If the target fails its Will save, it becomes infused with the so-called “grace of the pugwampi.” A creature affected by this spell must roll two d20s whenever a situation calls for a d20 roll (such as an attack roll, a skill check, or a saving throw) and must use the lower of the two results generated. As with the aura shed by actual pugwampies, this spell has no effect on animals, gremlins, or gnolls. The effects of this spell are negated as long as a target gains any sort of luck bonus to a d20 roll (such as those granted by a luckstone or divine favor), but the spell’s duration is not impacted by these effects. If the luck bonus goes away before the pugwampi’s grace effect ends, the unluck returns and remains until the spell’s normal duration runs out.', 'a pugwampi’s hair', NULL, false, false),
  ('punishing_armor', 'Punishing Armor', 'abjuration', NULL, NULL, 1, 'divine', 'alchemist 1, bloodrager 1, magus 1, shaman 1, sorcerer/wizard 1, spiritualist 1, summoner 1', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level (D)', 'Fort negates; see below', 'no', 'You coat yourself with a thin layer of shimmering energy. Any creature dealing nonlethal damage to you immediately takes half the amount of nonlethal damage dealt. A successful Fortitude save made by the attacking creature negates this damage.', NULL, NULL, false, false),
  ('pup_shape', 'Pup Shape', 'transmutation', 'polymorph', NULL, 3, 'divine', 'druid 3, sorcerer/wizard 3, witch 3', '1 standard actionComponent V, S, M (a rag doll)', 'close (25 ft. + 5 ft./2 levels)', 'one animal', NULL, NULL, '1 round/level', 'Fort negates (and Will special, see text)', 'yes', 'You transform the subject animal into a Small magical beast (or a magical beast one size category smaller than the original creature, whichever is smaller), creating a young magical version of itself for a short period of time. While in this form, the target has only 1 HD (maximum hit points), and the target takes a –4 penalty to Strength, Constitution, Intelligence and Wisdom (minimum 1). The creature also gains a +4 size bonus to Dexterity and a +2 natural bonus.', 'a rag doll', NULL, false, false),
  ('purge_spirit', 'Purge Spirit', 'necromancy', NULL, NULL, 2, 'arcane', 'medium 2, occultist 2, psychic 3, sorcerer/wizard 4, spiritualist 2, witch 4; Mystery reaper 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature or haunt', NULL, NULL, 'instantaneous', 'Will partial', 'yes', 'Purge spirit rips away at the target’s spiritual substance, scattering it over a wide area and hampering the target’s ability to reform. The target takes 1d6 points of damage per caster level (maximum 10d6) and is staggered for 1 round. On a successful saving throw, the target takes half damage and is not staggered. This spell affects astrally projected creatures, ethereal creatures, haunts, incorporeal creatures, mediums channeling a spirit, and phantoms, and at the GM’s discretion can affect other spirits or creatures made of ectoplasm.', NULL, NULL, false, false),
  ('purging_finale', 'Purging Finale', 'conjuration', 'healing', NULL, 3, 'arcane', 'bard 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes (harmless)', 'You must have a bardic performance in effect to cast this spell. With a flourish, you immediately end your bardic performance, removing one of the following conditions on a creature within range affected by your bardic performance: cowering, dazzled, exhausted, paralyzed, shaken, or stunned.', NULL, NULL, false, false),
  ('purified_calling', 'Purified Calling', 'conjuration', 'healing', NULL, 4, 'arcane', 'summoner/unchained summoner 4', '1 standard action', 'personal', NULL, NULL, NULL, '1 minute', NULL, NULL, 'Your eidolon is restored to full health when you summon it. Upon casting this spell, you must immediately begin the ritual to summon your eidolon. Upon completion of the ritual, your eidolon appears at full hit points and without any damage or penalties to its ability scores, regardless of its previous condition. In addition, any temporary negative conditions affecting your eidolon are immediately removed.', 'a stick of incense', NULL, false, false),
  ('purify_body', 'Purify Body', 'conjuration', 'healing', NULL, 4, 'divine', 'alchemist 4, cleric/oracle 4, medium 4, paladin 4, psychic 5, warpriest 4', '1 standard action', 'touch', 'living creature touched', NULL, NULL, 'instantaneous and 1 hour or until discharged', 'Will negates (harmless)', 'yes (harmless)', 'You align the target’s chakras and soothe any unwanted imperfections found within its physical form, leaving its body pristine and without any pain or weakness.', NULL, NULL, false, false),
  ('purify_food_and_drink', 'Purify Food and Drink', 'transmutation', NULL, NULL, 0, 'divine', 'cleric/oracle 0, druid 0, shaman 0', '1 standard action', '10 ft.', '1 cu. ft./level of contaminated food and water', NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'This spell makes spoiled, rotten, diseased, poisonous, or otherwise contaminated food and water pure and suitable for eating and drinking. This spell does not prevent subsequent natural decay or spoilage. Unholy water and similar food and drink of significance is spoiled by purify food and drink, but the spell has no effect on creatures of any type nor upon magic potions. Water weighs about 8 pounds per gallon. One cubic foot of water contains roughly 8 gallons and weighs about 60 pounds.', NULL, NULL, false, false),
  ('putrefy_food_and_drink', 'Putrefy Food and Drink', 'transmutation', NULL, 'poison', 0, 'arcane', 'witch 0', '1 standard action', '10 ft.', NULL, NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'This spell causes otherwise edible food to rot and spoil instantly, and water and other liquids to become brackish and undrinkable. Holy water and similar food and drink of significance are spoiled by putrefy food and drink, but the spell has no effect on creatures of any type, nor upon unholy water. Water weighs about 8 pounds per gallon. One cubic foot of water contains roughly 8 gallons and weighs about 60 pounds.', NULL, NULL, false, false),
  ('puzzle_box', 'Puzzle Box', 'enchantment', 'compulsion', 'curse, mind-affecting', 2, 'arcane', 'bard 2, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels) or touch; see text', 'one creature or one object up to 5 lbs./level', NULL, NULL, '1 round/level or permanent; see text', 'Will negates or none', 'yes', 'This spell causes even commonly used objects to become conundrums. When cast on a creature, the target loses all weapon and shield proficiencies. The target also forgets how to use all spell-completion, spell-trigger, and use-activated magic items, as well as any mundane items used as part of a skill check, imposing a –5 penalty on all ability and skill checks attempted with such items. These effects last for 1 round per level. As a move action, the target can attempt a skill check to negate the effects of this spell for one object. Weapons, shields, and mundane objects require a successful Craft skill check of the type required to craft the item in question, with a DC equal to the spell’s save DC. Magic items require a successful Spellcraft or Use Magic Device skill check against the spell’s save DC.', NULL, NULL, false, false),
  ('pyrotechnic_eruption', 'Pyrotechnic Eruption', 'evocation', NULL, 'fire', 3, 'arcane', 'bloodrager 3, magus 4, occultist 4, sorcerer/wizard 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, 'see text', 'Reflex half (see text)', 'yes', 'The caster causes jets of flame to erupt from the ground and surround the target. The target takes 1d6 points of damage per caster level (maximum 15d6) unless it succeeds at a Reflex save for half damage. The blaze surrounds the target for the duration of the spell, forcing the creature to attempt a new save each round.', 'a pinch of coal', NULL, false, false),
  ('pyrotechnics', 'Pyrotechnics', 'transmutation', NULL, NULL, 2, 'arcane', 'bard 2, bloodrager 2, magus 2, mesmerist 2, psychic 2, sorcerer/wizard 2; Subdomain smoke 2; Elemental School fire 2', '1 standard action', 'long (400 ft. + 40 ft./level)', 'one fire source, up to a 20-ft. cube', NULL, NULL, '1d4+1 rounds, or 1d4+1 rounds after creatures leave the smoke cloud; see text', 'Will negates or Fortitude negates; see text', 'yes or no; see text', 'Pyrotechnics turns a fire into a burst of blinding fireworks or a thick cloud of choking smoke, depending on your choice. The spell uses one fire source, which is immediately extinguished. A fire so large that it exceeds a 20-foot cube is only partly extinguished. Magical fires are not extinguished, although a fire-based creature used as a source takes 1 point of damage per caster level.', 'one fire source', NULL, false, false),
  ('qualm', 'Qualm', 'enchantment', 'compulsion', 'mind-affecting', 2, 'divine', 'bard 2, inquisitor 2, medium 2, mesmerist 2, psychic 2, sorcerer/wizard 2, witch 2; Subdomain redemption 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 minute/level or until discharged', 'Will negates', 'yes', 'The target is suddenly beset with unexplainable doubts about the effectiveness of its actions and the righteousness of its cause. The creature takes a –10 penalty on its ability checks, skill checks, and concentration checks, until the duration ends, or until it spends its entire turn doing absolutely nothing (it spends a full-round action gaining focus). Spending an entire turn doing nothing discharges the spell.', NULL, NULL, false, false),
  ('quell_energy', 'Quell Energy', 'abjuration', NULL, NULL, 3, 'divine', 'druid 3, inquisitor 3, occultist 3, psychic 3, shaman 3, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will partial', 'yes', 'You reduce the target creature’s ability to tap into a single energy type (acid, cold, electricity, fire, or sonic) of your choice. This reduces damage of the selected type the creature deals with spells, spell-like abilities, and supernatural abilities by 10 points.', NULL, NULL, false, false),
  ('quench', 'Quench', 'transmutation', NULL, NULL, 3, 'divine', 'druid 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one 20-ft. cube/level (S) or one fire-based magic item', 'or Target one 20-ft. cube/level (S) or one fire-based magic item', NULL, 'instantaneous', 'none or Will negates (object)', 'no or yes (object)', 'Quench is often used to put out forest fires and other conflagrations. It extinguishes all non-magical fires in its area. The spell also dispels any fire spells in its area, though you must succeed on a dispel check (1d20 +1 per caster level, maximum +15) against each spell to dispel it. The DC to dispel such spells is 11 + the caster level of the fire spell.', NULL, NULL, true, false),
  ('questing_stone', 'Questing Stone', 'divination', NULL, NULL, 4, 'arcane', 'bard 4, sorcerer/wizard 4', '10 minutes', 'touch and unlimited', 'one ioun stone touched', NULL, NULL, '1 minute/level (D)', 'none', 'no', 'This spell functions like arcane eye, except that it uses an ioun stone as a visible scrying sensor. The ioun stone moves at the same rate as an arcane eye, and may pass through holes or spaces as small as 2 inches in diameter. It can enter another plane of existence using a gate or similar portal, but the caster loses contact with the sensor should this occur. The enhanced ioun stone has AC 24, 10 hp, hardness 5, fly speed 30 (perfect), and a +16 Stealth bonus. The stone does not provide you with its normal benefits while you are using it as a scrying sensor.', NULL, NULL, false, false),
  ('quick_change', 'Quick Change', 'transmutation', 'polymorph', NULL, 2, 'divine', 'alchemist 2, bard 2, bloodrager 2, druid 2, inquisitor 2, magus 2, medium 2, mesmerist 2, occultist 2, ranger 2, shaman 2, sorcerer/wizard 2, spiritualist 2, summoner 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level', NULL, NULL, 'If you have the change shape special quality, you can revert to your true form as a swift action. If a creature is not aware of your true form, when you use this spell to revert to your true form and attack that creature in the same round, the creature is denied its Dexterity bonus to AC against your first attack.', NULL, NULL, false, false),
  ('quick_throwing', 'Quick Throwing', 'transmutation', NULL, NULL, 2, 'divine', 'antipaladin 2, bloodrager 2, magus 2, paladin 2, ranger 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature/level, no two of which can be more than 30 ft. apart', NULL, NULL, '1 round/level', 'Fort negates (harmless)', 'yes (harmless)', 'Those under the effects of this spell become faster in the use of thrown weapons. They can draw thrown weapons (including rocks if they have the rock throwing ability) on their bodies or within their space without the need for the Quick Draw feat, allowing them to make their full normal rate of attacks with such weapons. This has no effects on other forms of ranged weapon ammunition.', NULL, NULL, false, false),
  ('quieting_weapons', 'Quieting Weapons', 'illusion', 'glamer', NULL, 3, 'divine', 'bard 4, cleric 4, inquisitor 4, magus 4, occultist 4, psychic 4, ranger 3, sorcerer/wizard 4, spiritualist 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'up to one natural or manufactured weapon per 3 caster levels', NULL, NULL, '10 minutes/level', 'Will negates (object)', 'yes (object)', 'The target weapons and any ammunition they fire make no sound as part of their normal functions as a weapon. For instance, a firearm’s firing would not make an explosive sound, but if you cast this spell on a creature’s bite attack, it would not prevent it from vocalizing from its mouth. The first time a creature is struck by a weapon affected by this spell, it must succeed at a Will save (SR applies to this effect) or it becomes unable to make noise louder than a whisper (Perception DC 10 to hear) whether vocally or by other means for the duration of the effect. Because the creature can still whisper, this doesn’t interfere with verbal spell components. Whether it succeeds or fails its saving throw, the creature is immune to further effects from this casting of quieting weapons.', NULL, NULL, false, false),
  ('quintessence', 'Quintessence', 'illusion', 'glamer', NULL, 1, 'arcane', 'bard 1, medium 1, mesmerist 1, occultist 1, psychic 1, sorcerer/wizard 1', '1 standard action', 'touch', 'creature or object touched', NULL, NULL, '10 minutes/level (D)', 'Will negates (harmless) and Will disbelief; see text', 'see text', 'You draw forth the idealized image of the target creature or object, masking any flaws or damage. An injured or ill creature appears healthy, and a damaged object or one with the broken condition appears intact. However, a corpse masked by quintessence remains obviously dead, and a completely destroyed object can’t be made to seem whole.', NULL, NULL, false, false),
  ('quintessence_mastery', 'Quintessence Mastery', 'transmutation', NULL, NULL, 8, 'divine', 'cleric 8, sorcerer/wizard 8, witch 8', '1 round or 4 hours; see text', 'personal or up to 10 10-ft. cubes/level (S)', NULL, NULL, 'control over a plane’s terrain and traits', '1 hour/level or 1 day/level; see text', NULL, NULL, 'This spell grants the caster limited control over the quintessence of an Outer Planes. The control granted by quintessence mastery can take one of two forms, depending on the version of the spell cast. Both versions can be cast only on one of the nine Outer Planes, for it is these planes, not the Transitive or Inner Planes, that are comprised of quintessence.', NULL, 'a staff crafted from the chosen plane’s material worth 2,500 gp', false, true),
  ('radiation_ward', 'Radiation Ward', 'abjuration', NULL, NULL, 1, 'divine', 'alchemist 2, arcanist 2, cleric/oracle 2, druid 2, hunter 1, ranger 1, shaman 2, sorcerer/wizard 2, warpriest 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level (D)', 'Fort negates (harmless)', 'yes (harmless)', 'A creature warded by this spell gains a +4 bonus on saving throws against radiation-based effects. In addition, the warded creature is immediately aware when it enters an area of radiation, as well as the radiation level (low, medium, high, or severe) suffusing the area.', NULL, NULL, false, false),
  ('rage', 'Rage', 'enchantment', 'compulsion', 'emotion, mind-affecting', 2, 'arcane', 'alchemist 3, bard 2, bloodrager 3, mesmerist 2, psychic 3, sorcerer/wizard 3, summoner/unchained summoner 3, witch 3; Domain destruction 3, madness 3; Subdomain demon (chaos, evil), ferocity 3; Bloodline abyssal 3, boreal 2; Mystery lunar 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, 'concentration + 1 round/level (D)', 'none', 'yes', 'Each affected creature gains a +2 morale bonus to Strength and Constitution, a +1 morale bonus on Will saves, and a -2 penalty to AC. The effect is otherwise identical with a barbarian’s rage except that the subjects aren’t fatigued at the end of the rage.', NULL, NULL, false, false),
  ('raging_rubble', 'Raging Rubble', 'transmutation', NULL, 'earth', 3, 'divine', 'bard 3, bloodrager 3, cleric 3, druid 3, sorcerer/wizard 3, witch 3', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one swarm of stones', 'concentration + 2 rounds', 'none', 'yes', 'You animate an area of rubble, gravel, or other small stones, creating a dangerous, rolling area of debris. The animated rubble has a space of 10 feet and acts like a swarm, damaging (1d6 hit points) and distracting (DC 12) anything within it. As a move action, you can direct the rubble to move up to 10 feet. If the rubble is attacked, treat it as a Medium animated object with the young creature simple template and the swarm subtype.', NULL, NULL, true, false),
  ('rags_to_riches', 'Rags to Riches', 'transmutation', NULL, NULL, 3, 'divine', 'alchemist 3, bard 3, cleric 4, medium 3, occultist 3, sorcerer/wizard 4, witch 4', '1 standard action', 'touch', '1 weapon, suit or armor, shield, tool, or skill kit touched/5 levels', NULL, NULL, '10 minutes/level', 'Fort negates (object)', 'no', 'The target object is enhanced to function as a masterwork item.', 'a bit of burlap wrapped over a copper coin', NULL, false, false),
  ('raiment_of_command', 'Raiment of Command', 'illusion', 'glamer', NULL, 2, 'arcane', 'bard 2, sorcerer/wizard 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level', 'Will', 'no', 'You are cloaked in an illusion of authority. Others perceive you to be a legitimate figure of authority, such as a higher-ranking official, a religious figure, or a more powerful warrior. This illusion grants you a +5 bonus on all Diplomacy and Intimidate checks. If you attempt to disguise yourself as a specific authority figure whom you have met in person, you gain a +10 competence bonus on the Disguise check and any Bluff check related to impersonating that authority figure.', NULL, NULL, false, false),
  ('rain_of_arrows', 'Rain of Arrows', 'conjuration', 'creation', NULL, 8, 'arcane', 'sorcerer/wizard 8', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, '15-ft.-radius cloud of arrows', 'instantaneous', 'Reflex halves', 'no', 'You point your finger and conjure a cloud of magical arrows that rain down on any creatures and objects in the indicated area.', 'a quiver full of 20 arrows worth 1 gp', NULL, false, true),
  ('rain_of_frogs', 'Rain of Frogs', 'conjuration', 'summoning', NULL, 3, 'divine', 'bard 3, druid 3, psychic 3, shaman 4, sorcerer/wizard 3, summoner/unchained summoner 3, witch 3', '1 round', NULL, NULL, NULL, 'one swarm of poisonous frogs', NULL, NULL, NULL, 'This spell functions as summon swarm, except you summon a swarm of poisonous frogs. This swarm has the statistics of a centipede swarm, except it has the animal type and its poison deals Constitution damage instead of Dexterity damage.', 'a square of red cloth', NULL, true, false),
  ('rainbow_pattern', 'Rainbow Pattern', 'illusion', 'pattern', 'mind-affecting', 4, 'arcane', 'bard 4, sorcerer/wizard 4; Mystery heavens 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'colorful lights with a 20-ft.-radius spread', 'Concentration +1 round/level (D)', 'Will negates', 'yes', 'A glowing, rainbow-hued pattern of interweaving colors fascinates those within it. Rainbow pattern fascinates a maximum of 24 HD of creatures. Creatures with the fewest HD are affected first. Among creatures with equal HD, those who are closest to the spell’s point of origin are affected first. An affected creature that fails its saves is fascinated by the pattern.', 'a piece of phosphor', 'a crystal prism', false, false),
  ('raise_animal_companion', 'Raise Animal Companion', 'conjuration', 'healing', NULL, 4, 'divine', 'druid 5, paladin 4, ranger 4', '1 minute', 'touch', 'dead animal companion or bonded mount', NULL, NULL, 'instantaneous', 'none, see text', 'yes (harmless)', 'This spell functions as raise dead, but it only affects an animal companion, familiar, or paladin’s bonded mount.', 'a diamond worth 1,000 gp', NULL, false, true),
  ('raise_dead', 'Raise Dead', 'conjuration', 'healing', NULL, 5, 'divine', 'cleric/oracle 5, shaman 6, witch 6; Subdomain resurrection 5', '1 minute', 'touch', 'dead creature touched', NULL, NULL, 'instantaneous', 'none, see text', 'yes (harmless)', 'You restore life to a deceased creature. You can raise a creature that has been dead for no longer than 1 day per caster level. In addition, the subject’s soul must be free and willing to return. If the subject’s soul is not willing to return, the spell does not work; therefore, a subject that wants to return receives no saving throw.', 'diamond worth 5,000 gp', NULL, true, true),
  ('rally_point', 'Rally Point', 'enchantment', 'compulsion', 'emotion, good, mind-affecting', 1, 'divine', 'paladin 1', '1 standard action', '5 ft.', NULL, 'one 5-ft. square', NULL, '1 minute/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'You create a spot that has the power to briefly hearten any good creature who comes into contact with it. A good creature who enters this square (even if simply as part of its normal move) gains a +2 morale bonus on attacks, saving throws, and 2 temporary hit points per caster level for 1 round. Nongood creatures gain no benefit from this spell.', NULL, NULL, true, false),
  ('rampart', 'Rampart', 'conjuration', 'creation', 'earth', 7, 'divine', 'druid 7, sorcerer/wizard 7; Elemental School earth 7', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, '10-ft.-high earthen wall, in a line up to 10 ft. long/2 levels, or a circle with radius of up to 3 ft. + 1 ft./level', 'instantaneous', 'none', 'no', 'You create a massive rampart of hard-packed earth and stone 5 feet thick. The rampart cannot be conjured so that it occupies the same space as another creature or object. Each 5-foot-wide section of the rampart has hardness 0 and 180 hit points. A section of the rampart whose hit points drop to 0 is breached. If a creature tries to break through the rampart with a single attack, the DC for the Strength check is 60. A creature can climb over the rampart with a DC 20 Climb check.', 'a handful of earth', NULL, false, false),
  ('rapid_repair', 'Rapid Repair', 'transmutation', NULL, NULL, 5, 'divine', 'cleric/oracle 5, sorcerer/wizard 5; Elemental School metal 5', '1 standard action', 'touch', 'construct touched', NULL, NULL, '1 round/level', 'Fortitude negates (harmless)', 'yes (harmless)', 'The targeted construct gains fast healing 5. This does not stack with any fast healing the construct already has. Fast healing has no effect on a construct that has been brought to 0 hit points or destroyed.', NULL, NULL, true, false),
  ('raven_s_flight', 'Raven’s Flight', 'transmutation', NULL, NULL, 2, 'divine', 'bard 3, druid 3, inquisitor 3, magus 2, ranger 2, shaman 2, sorcerer/wizard 2, witch 2', '1 swift action', 'personal', 'you', NULL, NULL, '1 round', NULL, NULL, 'You can cast this spell only if it is the first action you take on your turn. In a burst of shadowy feathers, you turn into a Tiny blurred shape reminiscent of a black raven until the beginning of your next turn. You gain a fly speed of 50 feet with good maneuverability, and apply appropriate size modifiers (though your ability scores don’t change). Until the beginning of your next turn, you can take only the 5-foot step, move, run, or withdraw actions. If the spell is dispelled while you are still aloft, the power of flight dissipates slowly; you float downward 60 feet on your next turn, then fall any remaining distance.', NULL, NULL, false, false),
  ('ray_of_enfeeblement', 'Ray of Enfeeblement', 'necromancy', NULL, NULL, 1, 'arcane', 'bloodrager 1, magus 1, sorcerer/wizard 1, witch 1; Bloodline accursed 1, daemon 1, ghoul 1; Mystery spellscar 1, succor 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'ray', '1 round/level', 'Fortitude half', 'yes', 'A coruscating ray springs from your hand. You must succeed on a ranged touch attack to strike a target. The subject takes a penalty to Strength equal to 1d6+1 per two caster levels (maximum 1d6+5). The subject’s Strength score cannot drop below 1. A successful Fortitude save reduces this penalty by half. This penalty does not stack with itself. Apply the highest penalty instead.', NULL, NULL, false, false),
  ('ray_of_exhaustion', 'Ray of Exhaustion', 'necromancy', NULL, NULL, 3, 'arcane', 'bloodrager 3, magus 3, sorcerer/wizard 3, witch 3; Bloodline accursed 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'ray', '1 min./level', 'Fortitude partial; see text', 'yes', 'A black ray projects from your pointing finger. You must succeed on a ranged touch attack with the ray to strike a target.', 'a drop of sweat', NULL, false, false),
  ('ray_of_frost', 'Ray of Frost', 'evocation', NULL, 'cold', 0, 'arcane', 'magus 0, sorcerer/wizard 0; Elemental School water 0', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'ray', 'instantaneous', 'none', 'yes', 'A ray of freezing air and ice projects from your pointing finger. You must succeed on a ranged touch attack with the ray to deal damage to a target. The ray deals 1d3 points of cold damage.', NULL, NULL, false, false),
  ('ray_of_sickening', 'Ray of Sickening', 'necromancy', NULL, NULL, 1, 'divine', 'bloodrager 1, cleric/oracle 1, druid 1, sorcerer/wizard 1, summoner/unchained summoner 1, witch 1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as ray of exhaustion, except the target is sickened if it fails its save and unaffected if it makes its save.', NULL, NULL, false, false),
  ('read_magic', 'Read Magic', 'divination', NULL, NULL, 0, 'divine', 'antipaladin 1, bard 0, cleric/oracle 0, druid 0, inquisitor 0, magus 0, paladin 1, psychic 0, ranger 1, shaman 0, sorcerer/wizard 0, summoner/unchained summoner 0, witch 0', '1 standard action', 'personal', 'you', NULL, NULL, '10 min./level', NULL, NULL, 'You can decipher magical inscriptions on objects – books, scrolls, weapons, and the like – that would otherwise be unintelligible. This deciphering does not normally invoke the magic contained in the writing, although it may do so in the case of a cursed or trapped scroll. Furthermore, once the spell is cast and you have read the magical inscription, you are thereafter able to read that particular writing without recourse to the use of read magic. You can read at the rate of one page (250 words) per minute. The spell allows you to identify a glyph of warding with a DC 13 Spellcraft check, a greater glyph of warding with a DC 16 Spellcraft check, or any symbol spell with a Spellcraft check (DC 10 + spell level).', NULL, 'a clear crystal or mineral prism', false, false),
  ('read_weather', 'Read Weather', 'divination', NULL, NULL, 1, 'divine', 'bard 1, cleric/oracle 1, druid 1, ranger 1, shaman 1, witch 1', '1 minute', 'personal', 'you', NULL, NULL, 'instantaneous', NULL, NULL, 'This spell allows you to forecast the weather at your location for the next 48 hours, providing you with advance warning of storms, tornadoes, and so on. This forecast reveals only the weather that would arise naturally, and does not take into account any magical occurrences that might change the weather.', NULL, 'a set of marked sticks or bones worth at least 25 gp', false, true),
  ('realm_retribution', 'Realm Retribution', 'conjuration', 'teleportation', NULL, 6, 'divine', 'cleric 8, inquisitor 6', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'All attacks made by the target match your alignment, counting as either chaotic, evil, good, or lawful as appropriate. If your alignment includes multiple alignment components, such as lawful good, you select one alignment component to impart to the target. Whenever the target confirms a critical hit against or takes damage from a creature, that creature must attempt a Will save. On a failed save, the creature is sent to the Outer Planes matching your alignment, as per plane shift, and the spell ends. A warpriest treats this spell as a 6th-level cleric spell for the purposes of preparing the spell, determining DCs, and so forth.', NULL, NULL, false, false),
  ('reaper_s_coterie', 'Reaper’s Coterie', 'necromancy', NULL, 'evil', 2, 'divine', 'antipaladin 2, bloodrager 2, cleric 3, inquisitor 3, witch 3', NULL, 'touch', 'weapon touched', NULL, NULL, '1 round/level', 'none', 'no', 'The target weapon becomes a reservoir of spiritual energy, fueling its destructive power by drawing in a tiny fragment of the essence of each creature it is used to defeat.', NULL, NULL, true, false),
  ('reboot', 'Reboot', 'transmutation', NULL, NULL, 4, 'divine', 'cleric 5, sorcerer/wizard 5, summoner 4, witch 5', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one destroyed construct of up to 2 HD/level', NULL, NULL, '1 round/level (D)', 'none', 'no', 'Whispering in the dense, information-rich machine language of the First Ones, you bring a destroyed construct back to operational status for a short time, restoring it to 1 hit point. The construct can be further healed with spells like make whole, but it returns to its destroyed state as soon as this spell’s duration expires or it is brought to 0 hit points, whichever comes first. As long as the construct is active, it obeys your commands to the best of its ability, fighting on your behalf and carrying out tasks that it is capable of performing.', NULL, 'a ruby worth at least 25 gp per HD of the target construct', false, true),
  ('rebuke', 'Rebuke', 'evocation', NULL, 'sonic', 4, 'arcane', 'inquisitor 4; Subdomain judgment 4', '1 standard action', '20 ft.', NULL, '20-ft.-radius burst centered on you', NULL, 'instantaneous', 'Fortitude partial', 'yes', 'Your wrathful words cause physical harm to your enemies.', NULL, NULL, true, false),
  ('rebuke_technology', 'Rebuke Technology', 'abjuration', NULL, NULL, 4, 'divine', 'druid 4, sorcerer/wizard 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one technological object or creature', NULL, NULL, '1 round/level', 'Fort negates (object)', 'yes (object)', 'You shroud the targeted technological object or creature (such as a robot or a nanotech swarm) with magical energy. If the targeted creature fails to resist the spell, it is rendered inert and unusable (or unconscious in the case of creatures) for the spell’s duration. A creature can attempt a new Fortitude saving throw to end the effect early at the end of its turn after the first full round it is affected by this spell.', NULL, NULL, true, false),
  ('recentering_drone', 'Recentering Drone', 'abjuration', NULL, NULL, 2, 'divine', 'cleric 2, druid 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'concentration', 'Will negates (harmless)', 'yes (harmless)', 'You emit a calming subsonic drone that allows the targets to temporarily refocus and restore their balance when they’re suffering from debilitating conditions. A target with the dazzled, fatigued, shaken, or sickened condition ignores the penalties of those conditions for the duration of this spell. A target with one of the following conditions is treated as having the associated lesser condition for the duration of the spell, as shown by the following table.', NULL, NULL, true, false),
  ('recharge', 'Recharge', 'evocation', NULL, NULL, 2, 'divine', 'bard 2, cleric 3, magus 3, sorcerer/wizard 3', '1 round', 'touch', 'object touched', NULL, NULL, 'instantaneous', 'Fort negates (object)', 'yes (object)', 'You restore up to 1 charge per level to a battery or half that number of charges to a technological item capable of being charged by a battery. If you recharge a battery, there is a 20% chance that the battery is destroyed by the attempt. If you restore more charges than the item can hold, the item must succeed at a Fortitude saving throw or take 1d6 points of electricity damage for each excess charge. This spell provides no knowledge of how many charges an item can safely hold, but you can choose to bestow fewer charges than the maximum allowed to reduce the risk; you must declare how many charges you are restoring before casting this spell.', '500 gp of diamond dust', NULL, false, true),
  ('recharge_innate_magic', 'Recharge Innate Magic', 'transmutation', NULL, NULL, 1, 'divine', 'alchemist 1, bard 1, cleric 1, druid 1, inquisitor 1, magus 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'personal', 'you', NULL, NULL, 'instantaneous', NULL, NULL, 'You channel magic energy into your own aura, recharging your innate magic abilities. You regain one use of all 0-level and 1st-level spell-like abilities you can use as a result of a racial trait.', NULL, NULL, false, false),
  ('reckless_infatuation', 'Reckless Infatuation', 'enchantment', 'compulsion', 'emotion, mind-affecting', 2, 'arcane', 'bard 2, mesmerist 2, psychic 3, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 day/level', 'Will negates', 'yes', 'You fill your target with feelings of intense infatuation for a specific individual known to the target. At the time of the casting, you designate a single creature as the focus of the target’s desire. Thereafter, the target does all it can to remain within 30 feet of the object of its desire. If the target moves outside this range, it gains the staggered condition until it is again near the focus of its desire. If remaining within 30 feet of the focus of its affection would place the target in obvious physical danger, the target can attempt a second save to break the spell’s effect.', NULL, NULL, false, false),
  ('recoil_fire', 'Recoil Fire', 'transmutation', NULL, NULL, 2, 'arcane', 'sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '1 firearm', NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'The target firearm suddenly fires of its own volition, even if it is unloaded, generating a recoil so great that the wielder or carrier of the firearm must scramble to hold onto it and becomes flat-footed until the start of his next turn. If the wielder is already flat-footed, he is instead knocked prone. If the firearm was loaded, that ammunition is wasted.', 'hoof shavings from a mule', NULL, false, false),
  ('recorporeal_incarnation', 'Recorporeal Incarnation', 'necromancy', NULL, NULL, 7, 'arcane', 'sorcerer/wizard 7, witch 7', '10 minutes', 'touch', 'one living creature and one corpse', NULL, NULL, '1 week/level', 'none', 'no', 'Recorporeal incarnation effectively replaces the target living creature’s body with that of the target corpse. The target corpse must be fresh—either dead for no more than 24 hours or appropriately preserved by an effect such as gentle repose. While casting the spell, you must remain in contact with the corpse while touching the living target with the focus item. As the spell is cast, the dead body’s flesh unravels like ribbons to sheathe the living target, who must be within one size category of the corpse. While the spell is in effect, the focus item must remain within 30 feet of the target living creature.', NULL, 'a gem or crystal worth at least 250 gp', false, true),
  ('red_hand_of_the_killer', 'Red Hand of The Killer', 'necromancy', NULL, NULL, 3, 'divine', 'bard 4, cleric 4, inquisitor 4, medium 3, occultist 4, paladin 4, psychic 5, sorcerer/wizard 5, spiritualist 4, witch 5', '1 standard action', 'see text', 'one creature', NULL, NULL, '1 day/level (D)', 'Will negates', 'yes', 'Drawing upon the spiritual link between a corpse and its killer, you reach out across space to brand the killer of the corpse you used as a focus for this spell, creating a physical manifestation of the killer’s guilt.', 'a black candle', 'a corpse slain no more than 1 day ago per caster level', false, false),
  ('redcap_s_touch', 'Redcap’s Touch', 'transmutation', NULL, NULL, 4, 'divine', 'antipaladin 4, bloodrager 4, druid 6, ranger 4, shaman 6, sorcerer/wizard 6, witch 6', '1 standard action', 'touch', 'one non-magical hat touched', NULL, NULL, '1 minute/level (D)', 'Will negates (harmless, object)', 'yes (harmless, object)', 'You infuse the target with the blood used as a material component, imparting malicious power. As long as the hat is worn (occupying the wearer’s head slot as though it were a magic item), it grants its wearer a +2 bonus on damage rolls and causes the wearer to regain 1d4 hit points whenever they deal the killing blow to a living creature.', '1 ounce of blood', NULL, false, false),
  ('reduce_animal', 'Reduce Animal', 'transmutation', NULL, NULL, 2, 'divine', 'druid 2, ranger 3', '1 standard action', 'touch', 'one willing animal of Small, Medium, Large, or Huge size', NULL, NULL, '1 hour/level (D)', 'none', 'no', 'This spell functions like reduce person, except that it affects a single willing animal. Reduce the damage dealt by the animal’s natural attacks as appropriate for its new size (see Table: Tiny and Large Weapon Damage to adjust damage for size).', NULL, NULL, false, false),
  ('reduce_person', 'Reduce Person', 'transmutation', NULL, NULL, 1, 'arcane', 'alchemist 1, bloodrager 1, magus 1, psychic 1, sorcerer/wizard 1, summoner/unchained summoner 1, witch 1', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one humanoid creature', NULL, NULL, '1 min./level (D)', 'Fortitude negates', 'yes', 'This spell causes instant diminution of a humanoid creature, halving its height, length, and width and dividing its weight by 8. This decrease changes the creature’s size category to the next smaller one. The target gains a +2 size bonus to Dexterity, a -2 size penalty to Strength (to a minimum of 1), and a +1 bonus on attack rolls and AC due to its reduced size.', 'a pinch of powdered iron', NULL, false, false),
  ('refine_improvised_weapon', 'Refine Improvised Weapon', 'transmutation', NULL, NULL, 1, 'divine', 'cleric 1, inquisitor 1, ranger 1, sorcerer/wizard 1', '1 standard action', 'touch', 'one improvised weapon', NULL, NULL, '1 hour/level (D)', 'Will negates (harmless, object)', 'yes (harmless, object)', 'You transform an improvised weapon into an equivalent simple or martial weapon of masterwork quality. This effect does not alter the weapon’s shape or appearance in any way. For example, if this spell is cast on a chair leg, a butter knife, or a pitchfork, the items function as a masterwork club, a masterwork dagger, or a masterwork trident, respectively, but the items look no different than they did before the spell was cast.', NULL, NULL, true, false),
  ('reflexive_barrier', 'Reflexive Barrier', 'evocation', NULL, 'force', 3, 'arcane', 'magus 3, psychic 3', '1 immediate action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round (see text)', 'none (harmless)', 'no (harmless)', 'In the blink of an eye, you erect a deflective barrier of force to protect one target.', NULL, NULL, false, false),
  ('refuge', 'Refuge', 'conjuration', 'teleportation', NULL, 7, 'divine', 'cleric/oracle 7, sorcerer/wizard 9, witch 9; Domain  community 7, liberation 7; Elemental School wood 9', '1 standard action', 'touch', 'object touched', NULL, NULL, 'permanent until discharged', 'none', 'no', 'When you cast this spell, you create powerful magic in a specially prepared object. This object contains the power to instantly transport its possessor across any distance within the same plane to your abode. Once the item is so enhanced, you must give it willingly to a creature and at the same time inform it of a command word to be spoken when the item is used. To make use of the item, the subject speaks the command word at the same time that it rends or breaks the item (a standard action). When this is done, the individual and all objects it is wearing and carrying (to a maximum of the character’s heavy load) are instantly transported to your abode. No other creatures are affected (aside from a familiar or animal companion that is touching the subject).', 'a prepared object worth 1,500 gp', NULL, false, true),
  ('regenerate', 'Regenerate', 'conjuration', 'healing', NULL, 7, 'divine', 'cleric/oracle 7, druid 9, shaman 7, witch 7; Domain healing 7', '3 full rounds', 'touch', 'living creature touched', NULL, NULL, 'instantaneous', 'Fortitude negates (harmless)', 'yes (harmless)', 'The subject’s severed body members (fingers, toes, hands, feet, arms, legs, tails, or even heads of multi-headed creatures), broken bones, and ruined organs grow back. After the spell is cast, the physical regeneration is complete in 1 round if the severed members are present and touching the creature. It takes 2d10 rounds otherwise.', NULL, NULL, true, false),
  ('reincarnate', 'Reincarnate', 'transmutation', NULL, NULL, 4, 'divine', 'druid 4, shaman 4, witch 5', '10 minutes', 'touch', 'dead creature touched', NULL, NULL, 'instantaneous', 'none, see text', 'yes (harmless)', 'With this spell, you bring back a dead creature in another body, provided that its death occurred no more than 1 week before the casting of the spell and the subject’s soul is free and willing to return. If the subject’s soul is not willing to return, the spell does not work; therefore, a subject that wants to return receives no saving throw.', 'oils worth 1,000 gp', NULL, true, true),
  ('reincarnate_spy', 'Reincarnate Spy', 'conjuration', 'healing', NULL, 6, 'divine', 'druid 6, shaman 6, witch 7', '10 minutes', 'touch', 'dead creature touched', NULL, NULL, 'instantaneous', 'none (see text)', 'yes', 'This spell functions as reincarnate except that you can cause the new body to resemble a particular creature, matching its age category and sex and rerolling any race result that would be the wrong size category. The subject further gains a +5 bonus on Disguise checks to impersonate the chosen creature due to similar features, although it might take a penalty for being the wrong race.', 'oils worth 2,500 gp and a possession or piece of the body of the creature to resemble', NULL, true, true),
  ('reinforce_armaments', 'Reinforce Armaments', 'transmutation', NULL, NULL, 1, 'divine', 'cleric 1, magus 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'one armor suit or weapon touched', NULL, NULL, '10 minutes/level', 'Will negates (harmless, object)', 'yes (harmless, object)', 'You reinforce a weapon or armor suit to give it a temporarily upgrade or mitigate the fragile quality. A suit of armor or weapon touched that has the fragile quality is not considered to have the fragile quality for the spell’s duration. Normal armor suits or weapons subjected to this spell instead gain the masterwork quality for the spell’s duration and their hardness is doubled. If this spell is cast on masterwork or magical armor or weapons, their hardness is doubled for the duration of the spell.', 'a metal pin', NULL, true, false),
  ('reinvigorating_wind', 'Reinvigorating Wind', 'enchantment', 'compulsion', 'air, mind-affecting', 2, 'divine', 'bard 2, druid 3, hunter 3, shaman 2, skald 2, witch 3', '1 standard action', '30 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous', 'Will negates (harmless)', 'yes (harmless)', 'You exhale deeply, creating a gentle magical wind that invigorates any allies in the affected area, as follows. Any sleeping allies immediately wake up. Fascinated allies are shaken free of the fascinate effect. Flat-footed allies no longer count as flat-footed even if they have not acted yet. The duration of effects that cause any allies to be confused, frightened, paralyzed, slowed, or stunned is decreased by 1d4 rounds (roll separately for each target). If the duration of any such effect is reduced to 0 rounds or fewer, the effect ends for that ally. Finally, any allies lying prone may stand up as an immediate action, provoking attacks of opportunity as normal.', 'a flower petal', NULL, true, false),
  ('rejuvenate_eidolon', 'Rejuvenate Eidolon', 'conjuration', 'healing', NULL, 3, 'arcane', 'summoner/unchained summoner 3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as lesser rejuvenate eidolon, except that it cures 3d10 points of damage +1 point per caster level (maximum +10).', 'a drop of your blood', NULL, false, false),
  ('release_fury', 'Release Fury', 'enchantment', 'compulsion', 'draconic, evil, mind-affecting', 5, 'divine', 'mesmerist 5, occultist 5, shaman 5, sorcerer/wizard 5, witch 5', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You unleash all the target’s anger and destructive urges, causing it to fly into a violent bloodlust.
